	describe_150001 = [=[轻巧便携，记录下与指挥官有关的每一份小心思。送给对象后能够激发一定的心音共鸣。]=],
	describe_150002 = [=[淡淡香草气息，让言语也变得柔软起来。送给对象后能够激发一定的心音共鸣。]=],
	describe_150003 = [=[精致的手绘图景，寄托无法说出的万千心意。送给对象后能够激发一定的心音共鸣。]=],
	describe_150004 = [=[平凡日常中，悄然系上的一份在意。送给对象后能够激发一定的心音共鸣。]=],
	describe_150005 = [=[甜蜜密封其中，每一颗都是悄悄为你藏好的心情。送给对象后能够激发一定的心音共鸣。]=],
	describe_150006 = [=[一点微光，一抹香气，为她的夜晚带去静谧温柔。送给对象后能够激发一定的心音共鸣。]=],
	describe_150007 = [=[柔软可握的温度，就像寒冷中始终在她身边一样。送给对象后能够激发一定的心音共鸣。]=],
	describe_150008 = [=[让每一次护理都成为犒赏自己的一段精致时光。送给对象后能够激发一定的心音共鸣。]=],
	describe_150009 = [=[专属图案，盛装她与避风港的每一日温热回忆。送给对象后能够激发一定的心音共鸣。]=],
	describe_150010 = [=[寒冬中柔软贴身的呵护，耳边响起的那句“注意保暖”。送给对象后能够激发一定的心音共鸣。]=],
	describe_150011 = [=[温暖的烛光，是为她点燃的安心与浪漫。送给对象后能够激发一定的心音共鸣。]=],
	describe_150012 = [=[清爽又治愈，仿佛将港区午后的海风封存在掌中。送给对象后能够激发一定的心音共鸣。]=],
	describe_150013 = [=[香甜入口，每一颗都藏着写给她的秘密。送给对象后能够激发一定的心音共鸣。]=],
	describe_150014 = [=[轻轻涂抹的每一次，都是想起你的温柔日常。送给对象后能够激发一定的心音共鸣。]=],
	describe_150015 = [=[柔软与优雅兼具，是她出门时最安心的陪伴。送给对象后能够激发一定的心音共鸣。]=],
	describe_150016 = [=[每一旋律都似曾相识，就像她第一次心动时的回响。送给对象后能够激发一定的心音共鸣。]=],
	describe_150017 = [=[记录时间，也铭记每一秒相遇的日子。送给对象后能够激发一定的心音共鸣。]=],
	describe_150018 = [=[若隐若现的气息，就像她悄然靠近时的那份悸动。送给对象后能够激发一定的心音共鸣。]=],
	describe_150019 = [=[温润柔光，为她的发梢点缀一份永不过时的优雅。送给对象后能够激发一定的心音共鸣。]=],
