	functionDes_202_11 = [=[强化等级达到12级的金色品质及以上攻击舰装可以进行熔合。]=],
	functionDes_202_12 = [=[进行舰装熔合时，需要选中两个相同的攻击舰装。]=],
	functionDes_202_21 = [=[熔合结果会选择更高的瞄准值和工艺值。]=],
	functionDes_202_22 = [=[熔合结果的附加属性会从两件待熔合装备的所有附加属性中随机选择4条不同类型属性。]=],
	functionDes_202_31 = [=[选中1条附加属性，会消耗1个"定向精调工具"，使熔合结果必定获得这条附加属性。]=],
	functionDes_202_32 = [=[额外增益必定会继承1个到熔合结果。]=],
	functionDes_202_4 = [=[熔合成功后，消耗2件攻击舰装，获得1件与消耗的攻击舰装相同的12级新攻击舰装。]=],
