	SkillDes_1 = [=[攻击单个敌军，造成炮击<color=#32a6ff>90%</color>的伤害。]=],
	SkillDes_2 = [=[攻击单个敌军，造成雷击<color=#32a6ff>90%</color>的伤害。]=],
	SkillDes_3 = [=[测试地形消耗减少效果用]=],
	SkillDes_4 = [=[侦察指定范围区域。范围内的所有敌军炮击、雷击降低<color=#32a6ff>15%</color>，持续<color=#32a6ff>2</color>回合。范围内的所有友军防空提升<color=#32a6ff>30%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_5 = [=[造成炮击<color=#32a6ff>160%</color>的伤害，对<color=#32a6ff>「战列舰」</color>有特效。击沉单位后恢复自己<color=#32a6ff>50%</color>的耐久。]=],
