	SkillDes_25 = [=[耐久值低于<color=#32a6ff>70%</color>时，造成的伤害降低<color=#32a6ff>15%</color>；耐久值低于<color=#32a6ff>30%</color>时，造成的伤害降低<color=#32a6ff>30%</color>。]=],
	SkillDes_26 = [=[行动结束时，如果没有进行过攻击或使用技能，进入<color=#32a6ff>「下潜」</color>状态。普攻、使用技能后，立刻移除<color=#32a6ff>「下潜」</color>状态。<color=#32a6ff>「下潜」</color>：受到的伤害降低<color=#32a6ff>30%</color>，受到的伤害额外降低<color=#32a6ff>20%</color>。]=],
	SkillDes_27 = [=[[航母]射程<color=#32a6ff>-1</color>。[潜艇]、[驱逐]造成的伤害提升<color=#32a6ff>10%</color>。]=],
	SkillDes_28 = [=[所有角色本场战斗无法暴击]=],
