	SkillDes_177 = [=[[旗舰技]为我方全体附加强化效果，除“耐久”、“幸运”外，全属性提升<color=#32a6ff>20%</color>，单体远程攻击时，造成的伤害提升<color=#32a6ff>15%</color>，持续<color=#32a6ff>4</color>回合。]=],
	SkillDes_178 = [=[攻击单个敌军，造成雷击<color=#32a6ff>150%</color>的伤害。暴击率提升<color=#32a6ff>20%</color>，攻击目标为<color=#32a6ff>「航母」</color>时必定暴击。]=],
	SkillDes_179 = [=[[支援]恢复自身<color=#32a6ff>60%</color>耐久值，<color=#32a6ff>2</color>格范围内的所有友军暴击率提升<color=#32a6ff>30%</color>，持续<color=#32a6ff>1</color>回合。使用后可额外移动<color=#32a6ff>2</color>格，可再次攻击。]=],
	SkillDes_180 = [=[攻击单个敌军，造成雷击<color=#32a6ff>160%</color>的伤害。攻击前将目标<color=#32a6ff>2</color>个强化效果转化为随机弱化效果。]=],
