	SkillDes_183 = [=[[支援]使用后，获得移动力<color=#32a6ff>+1</color>，造成的伤害提升<color=#32a6ff>10%</color>。持续<color=#32a6ff>1</color>回合。可额外行动<color=#32a6ff>1</color>次。]=],
	SkillDes_184 = [=[[旗舰技]为我方全体附加强化效果，除“耐久”、“幸运”外，全属性提升<color=#32a6ff>20%</color>，在“深海”海域中作战时，造成的伤害提升<color=#32a6ff>12%</color>，持续<color=#32a6ff>4</color>回合。]=],
	SkillDes_185 = [=[攻击单个敌军，造成炮击<color=#32a6ff>160%</color>的伤害，击败敌人后回复自身最大耐久值<color=#32a6ff>30%</color>的耐久值，移动力<color=#32a6ff>+1</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_186 = [=[造成炮击<color=#32a6ff>130%</color>的伤害，施加“被动技能失效”和“无法强化”效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_187 = [=[对范围内的所有敌军造成<color=#32a6ff>75%</color>的炮击伤害,并施加“造成炮击伤害降低<color=#32a6ff>20%</color>，受到炮击伤害提升<color=#32a6ff>20%</color>”效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_188 = [=[造成炮击<color=#32a6ff>160%</color>的伤害，攻击前自身获得<color=#32a6ff>2</color>回合的大西洋宪章（无法被驱散）：行动结束时，使2格范围内的所有敌军移动力-2，且无法进行护卫，持续1回合。]=],
