	SkillDes_190 = [=[攻击单个敌军，造成<color=#32a6ff>120%</color>的炮击伤害并附加<color=#32a6ff>30%</color>*装甲值的伤害；击退目标1格并附加移动力<color=#32a6ff>-1</color>，持续<color=#32a6ff>1</color>回合。]=],
