	SkillDes_192 = [=[攻击单个敌军，造成炮击<color=#32a6ff>145%</color>的伤害，并在进入攻击前使其“炮击、雷击”降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_193 = [=[攻击单个敌军，造成雷击<color=#32a6ff>130%</color>的伤害，对<color=#32a6ff>「功能舰、援护舰」</color>有特效。本次攻击的暴击率提升<color=#32a6ff>30%</color>。]=],
	SkillDes_194 = [=[攻击前，驱散敌方<color=#32a6ff>2</color>个强化效果。造成雷击<color=#32a6ff>130%</color>的伤害。成功消灭敌军时，自身获得<color=#32a6ff>30%</color>伤害减免，持续<color=#32a6ff>1</color>回合，并重置该技能冷却时间。]=],
	SkillDes_195 = [=[[支援]使用后，“炮击、雷击”，“机动”提升<color=#32a6ff>20%</color>，持续<color=#32a6ff>1</color>回合，可再次进行攻击。夜间时，提升效果提高至<color=#32a6ff>30%</color>。]=],
