	SkillDes_197 = [=[对范围内敌军造成<color=#32a6ff>40%</color>的雷击伤害，并附加[燃烧]：行动结束时损失<color=#32a6ff>20%</color>的耐久，持续<color=#32a6ff>2</color>回合。对航母单位额外附加造成伤害降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_198 = [=[造成炮击<color=#32a6ff>120%</color>的伤害。攻击后自身获得“炮击反击2”，持续<color=#32a6ff>2</color>回合。“炮击反击2”：受到<color=#32a6ff>2</color>格范围内的单体炮击时，进行反击，造成<color=#32a6ff>60%</color>的炮击伤害。]=],
	SkillDes_199 = [=[造成炮击<color=#32a6ff>100%</color>的伤害。攻击前为目标附加<color=#32a6ff>2</color>个随机异常状态，持续<color=#32a6ff>2</color>回合。目标身上每存在<color=#32a6ff>1</color>个异常状态，此技能伤害系数提升<color=#32a6ff>25%</color>。(最大提升<color=#32a6ff>100%</color>）]=],
	SkillDes_200 = [=[造成炮击<color=#32a6ff>120%</color>的伤害，攻击前，将自身雷击值的<color=#32a6ff>30%</color>附加到炮击上。攻击后对目标附加移动力<color=#32a6ff>-2</color>效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_201 = [=[使用时，如果未进行移动，额外增加3格射程。如果进行过移动，每移动1格，射程增加效果-1。（最少增加<color=#32a6ff>1</color>格）可再次攻击。]=],
	SkillDes_202 = [=[造成雷击<color=#32a6ff>150%</color>的伤害，并附加“束缚”和“装甲”降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>2</color>回合。束缚：移动力降低至<color=#32a6ff>0</color>。（此效果无法驱散）]=],
	SkillDes_203 = [=[对范围内的所有敌军造成<color=#32a6ff>45%</color>的雷击伤害，并附加<color=#32a6ff>2</color>个随机异常效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_204 = [=[造成雷击<color=#32a6ff>80%</color>的伤害，并附加“瘫痪”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_205 = [=[攻击<color=#32a6ff>3</color>条直线上的所有敌军造成炮击<color=#32a6ff>60%</color>伤害，将目标击退<color=#32a6ff>1</color>格并附加<color=#32a6ff>1</color>个随机弱化效果，持续<color=#32a6ff>1</color>回合。]=],
