	SkillDes_207 = [=[在指定空位置布置<color=#32a6ff>1</color>枚“磁性水雷”，使用后可再次移动<color=#32a6ff>2</color>格，并再次攻击。]=],
	SkillDes_208 = [=[攻击单个敌军，造成雷击<color=#32a6ff>160%</color>的伤害，攻击后可再次移动<color=#32a6ff>2</color>格。我方“磁性水雷”不在场时，攻击后使目标“炮击、雷击”降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>1</color>回合；“磁性水雷”在场时，攻击前恢复自身<color=#32a6ff>40%</color>耐久。]=],
	SkillDes_209 = [=[造成炮击<color=#32a6ff>160%</color>的伤害。攻击后，使附加“干扰”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_210 = [=[对<color=#32a6ff>3</color>条直线上的所有敌军造成雷击<color=#32a6ff>80%</color>的伤害，并驱散<color=#32a6ff>1</color>个强化状态。对敌军施加移动力<color=#32a6ff>-2</color>效果，且无法进行援护，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_211 = [=[无视援护对单个敌军造成炮击<color=#32a6ff>150%</color>的伤害。攻击后，使敌军“被动技能失效”，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_212 = [=[[旗舰技]为我方全体附加强化效果，除“耐久”、“幸运”外，全属性提升<color=#32a6ff>20%</color>，周围<color=#32a6ff>1</color>格没有友军时，造成伤害提升<color=#32a6ff>12%</color>，持续<color=#32a6ff>4</color>回合。]=],
