	SkillDes_214 = [=[对单个敌军造成雷击<color=#32a6ff>160%</color>的伤害，对「潜艇」有特效。战后驱散敌军<color=#32a6ff>2</color>个增益效果。耐久百分比高于敌军时，本次攻击无视其<color=#32a6ff>30%</color>机动。]=],
