	SkillDes_216 = [=[[旗舰技]为我方全体附加强化效果，除“耐久”、“幸运”外，全属性提升<color=#32a6ff>20%</color>，主动单体攻击非克制舰种时伤害提升<color=#32a6ff>15%</color>，持续<color=#32a6ff>4</color>回合。]=],
	SkillDes_217 = [=[造成炮击<color=#32a6ff>160%</color>的伤害。攻击前自身获得“不会受到中破/大破影响”效果，持续<color=#32a6ff>2</color>回合。本技能攻击<color=#32a6ff>2</color>格以外的敌军时，战后使目标“被动技能失效”，持续<color=#32a6ff>1</color>回合；攻击<color=#32a6ff>2</color>格或以内的敌军时，战后使目标“无法使用主动技能”，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_218 = [=[对单个敌军造成雷击<color=#32a6ff>130%</color>的伤害。自身处于<color=#32a6ff>「下潜」</color>状态时不触发本技能冷却。]=],
	SkillDes_219 = [=[对范围内敌军造成雷击<color=#32a6ff>75%</color>的伤害，对<color=#32a6ff>「战列舰」</color>有特效，并使敌军移动力<color=#32a6ff>-2</color>，“无法进行援护”，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_220 = [=[无视护卫对单个敌军造成雷击<color=#32a6ff>160%</color>的伤害。自身处于<color=#32a6ff>「下潜」</color>状态时施放本技能不会受到反击。攻击后立即进入<color=#32a6ff>「下潜」</color>状态。]=],
	SkillDes_221 = [=[造成雷击<color=#32a6ff>130%</color>的伤害，战斗后附加“瘫痪”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_222 = [=[对自身周围<color=#32a6ff>4</color>格范围内所有敌军造成雷击50%的伤害，附加“炮击、雷击”降低<color=#32a6ff>20%</color>效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_223 = [=[使范围内全体友军净化<color=#32a6ff>2</color>个弱化状态、附加暴击率提高<color=#32a6ff>20%</color>效果，持续<color=#32a6ff>2</color>回合。范围内的<color=#32a6ff>「巡洋舰」</color>、<color=#32a6ff>「驱逐舰」</color>、<color=#32a6ff>「功能舰」</color>获得受到伤害降低<color=#32a6ff>30%</color>，持续<color=#32a6ff>2</color>回合。]=],
