	SkillDes_227 = [=[[支援]使用后，驱散目标身上的所有异常效果,回复耐久值至<color=#32a6ff>100%</color>、重置所有技能的冷却时间，并附加“造成伤害提升<color=#32a6ff>30%</color>“的效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_228 = [=[无视护卫对单个敌军造成雷击<color=#32a6ff>150%</color>的伤害，暴击率提升<color=#32a6ff>30%</color>。]=],
	SkillDes_229 = [=[使得范围内友军恢复<color=#32a6ff>35%</color>耐久，且雷击、炮击提升<color=#32a6ff>20%</color>，免疫“雷击、炮击”降低，“干扰”，持续<color=#32a6ff>3</color>回合。]=],
	SkillDes_230 = [=[造成炮击<color=#32a6ff>150%</color>的伤害，对「潜艇」「空军」以外的单位有特效。]=],
	SkillDes_231 = [=[[支援]主动使用后，自身造成的伤害提升<color=#32a6ff>40%</color>，受到的伤害提升<color=#32a6ff>15%</color>，移动力<color=#32a6ff>-2</color>，持续<color=#32a6ff>2</color>回合（该效果无法被驱散）。使用后可以额外移动<color=#32a6ff>2</color>格，并再次攻击。]=],
	SkillDes_232 = [=[攻击单个敌军，造成雷击<color=#32a6ff>140%</color>的伤害。与“克制”单位交战时，攻击前获得<color=#32a6ff>2</color>个随机增益效果，持续<color=#32a6ff>2</color>回合。与“非克制””单位交战时，无视目标<color=#32a6ff>40%</color>的机动值。]=],
