	SkillDes_234 = [=[对范围内的所有敌军造成<color=#32a6ff>60%</color>的炮击伤害，对<color=#32a6ff>「飞行」</color>单位有特效，攻击后移除目标<color=#32a6ff>「下潜」</color>效果，并附加“机动”降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_235 = [=[对所有敌军造成<color=#32a6ff>40%</color>的炮击伤害，并附加“除耐久外，所有属性”降低<color=#32a6ff>15%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_236 = [=[攻击单个敌军，造成雷击<color=#32a6ff>150%</color>的伤害。攻击前对目标附加“机动”降低<color=#32a6ff>20%</color>效果，持续<color=#32a6ff>1</color>回合。攻击后，如果目标死亡，则恢复自身<color=#32a6ff>60%</color>耐久，否则自身获得“炮击、雷击”提升<color=#32a6ff>20%</color>，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_237 = [=[战斗开始时，炮击大于等于雷击时，此技能变更为“技能名-炮击”：对单体目标造成<color=#32a6ff>160%</color>的炮击伤害，额外附加“造成的伤害降低<color=#32a6ff>15%</color>”，持续<color=#32a6ff>1</color>回合；炮击小于雷击时，此技能变更为“技能名-雷击”：对单体目标造成<color=#32a6ff>160%</color>的雷击伤害，本次伤害必定暴击。]=],
	SkillDes_238 = [=[对单体目标造成<color=#32a6ff>160%</color>的炮击伤害，攻击后额外附加“造成的伤害降低<color=#32a6ff>15%</color>”，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_239 = [=[对单体目标造成<color=#32a6ff>160%</color>的雷击伤害，本次伤害必定暴击。]=],
