	SkillDes_241 = [=[[维修]维修指定单个友军，恢复炮击<color=#32a6ff>60%</color>的耐久，使目标“受到炮击单体攻击后，反弹所受伤害的<color=#32a6ff>20%</color>”，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_242 = [=[对范围内所有敌军造成炮击<color=#32a6ff>20%</color>的伤害，移除目标<color=#32a6ff>「下潜」</color>效果并附加“装甲”降低<color=#32a6ff>20%</color>、“机动”降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_243 = [=[[维修]维修指定范围内所有友军，恢复炮击<color=#32a6ff>60%</color>的耐久，并使移动力<color=#32a6ff>+1</color>，造成伤害提升<color=#32a6ff>10%</color>，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_244 = [=[[被动]自身<color=#32a6ff>1</color>格范围内的友军受到单体炮击攻击时，援护该友军。[主动]援护范围扩展至<color=#32a6ff>2</color>格，遭受暴击率降低<color=#32a6ff>20%</color>，并可对<color=#32a6ff>1</color>格范围内敌军进行反击，造成<color=#32a6ff>30%</color>的炮击伤害，持续<color=#32a6ff>2</color>回台。]=],
	SkillDes_245 = [=[造成炮击<color=#32a6ff>140%</color>的伤害。攻击前，获得[装甲转换]效果：将“装甲”的<color=#32a6ff>30%</color>附加到“炮击”上，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_246 = [=[将自身<color=#32a6ff>2</color>个弱化效果转换为随机强化效果，并额外获得[装甲转换]和“免疫所有弱化效果”、“自身<color=#32a6ff>2</color>格范围内的友军受到单体攻击时，援护该友军。”，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_247 = [=[无视护卫对单个敌军造成雷击<color=#32a6ff>120%</color>的伤害，暴击率提升<color=#32a6ff>20%</color>。如果击败目标，自身回复<color=#32a6ff>30%</color>的耐久值。]=],
	SkillDes_248 = [=[对单个敌军造成雷击<color=#32a6ff>160%</color>的伤害，攻击前，偷取敌方<color=#32a6ff>2</color>个强化效果。]=],
	SkillDes_249 = [=[攻击单个敌军，造成雷击<color=#32a6ff>160%</color>的伤害。处于<color=#32a6ff>「下潜」</color>状态时施放本技能可无视护卫。成功消灭敌军时，该技能的冷却时间减少<color=#32a6ff>3</color>回合并可再次移动<color=#32a6ff>2</color>格。]=],
	SkillDes_250 = [=[对单个敌军造成炮击<color=#32a6ff>130%</color>的伤害，对<color=#32a6ff>「空军」</color>有特效。战后追加<color=#32a6ff>1</color>次防空<color=#32a6ff>100%</color>的穿透伤害。]=],
	SkillDes_251 = [=[对单个敌军造成炮击<color=#32a6ff>140%</color>的伤害，对<color=#32a6ff>「驱逐舰」</color>有特效。本次攻击将防空的<color=#32a6ff>40%</color>加到炮击上。]=],
	SkillDes_252 = [=[[支援]使范围内所有友军的所有<color=#32a6ff>「攻击技能」</color>冷却时间减少<color=#32a6ff>3</color>回合，并施加“移动力<color=#32a6ff>+1</color>”，持续<color=#32a6ff>2</color>回合。使用后继承剩余移动力再次移动，可再次攻击。]=],
	SkillDes_253 = [=[攻击单个敌军，造成雷击130%的伤害。攻击前对目标施加“受到暴击提升20%”，持续1回合。]=],
	SkillDes_254 = [=[自身获得“暴击伤害提升20%”，“射程+1”，持续2回合。]=],
