	SkillDes_341 = [=[单体攻击耐久低于<color=#32a6ff>50%</color>敌人时，雷击提高<color=#32a6ff>15%</color>。]=],
	SkillDes_342 = [=[单体攻击耐久大于等于<color=#32a6ff>90%</color>敌人时，炮击提高<color=#32a6ff>15%</color>。]=],
	SkillDes_343 = [=[行动结束时，炮击提升<color=#32a6ff>10%</color>，持续<color=#32a6ff>3</color>回合，无法驱散，可叠加。]=],
	SkillDes_344 = [=[[被动]自身耐久值高于<color=#32a6ff>90%</color>时，受到的伤害降低<color=#32a6ff>30%</color>。]=],
	SkillDes_345 = [=[[被动]行动结束时,恢复自身周围<color=#32a6ff>2</color>格范围内的友军耐久,恢复量为自身炮击值的<color=#32a6ff>15%</color>。]=],
	SkillDes_346 = [=[[被动]单体攻击后有<color=#32a6ff>40%</color>概率触发,遭受所有伤害降低<color=#32a6ff>30%</color>，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_347 = [=[[被动]死亡后对自身<color=#32a6ff>1</color>格范围内的敌军造成最大耐久值<color=#32a6ff>20%</color>的伤害。]=],
	SkillDes_348 = [=[[被动]下潜时移动力<color=#32a6ff>+1</color>。]=],
	SkillDes_349 = [=[受到<color=#32a6ff>1</color>格范围内的单体攻击时，对攻击者进行反击，造成炮击值<color=#32a6ff>30%</color>的伤害。]=],
	SkillDes_350 = [=[受到<color=#32a6ff>2</color>格范围内的单体攻击时，对攻击者进行反击，造成炮击值<color=#32a6ff>60%</color>的伤害。]=],
	SkillDes_351 = [=[周围<color=#32a6ff>3</color>格以内的所有敌军装甲、机动、防空降低<color=#32a6ff>15%</color>。]=],
	SkillDes_352 = [=[被动<color=#32a6ff>2</color>格援护]=],
	SkillDes_353 = [=[主动时，攻击后给对方加buff]=],
	SkillDes_354 = [=[受伤时，攻击后给对方加buff]=],
	SkillDes_355 = [=[造成伤害，攻击后给自己回血]=],
	SkillDes_356 = [=[暴击时，攻击后给自己回血]=],
	SkillDes_357 = [=[受到暴击，攻击后给对方加buff]=],
	SkillDes_358 = [=[造成治疗后，攻击后额外给目标加buff]=],
	SkillDes_359 = [=[受到治疗时，攻击后给自己加buff]=],
	SkillDes_360 = [=[使用技能后，可再移动]=],
	SkillDes_361 = [=[普攻后，可以再行动]=],
	SkillDes_362 = [=[为使用技能、普攻时，攻击后给自己移动力<color=#32a6ff>+2</color>，持续<color=#32a6ff>2</color>回合]=],
	SkillDes_363 = [=[主动攻击时，与战列舰交战，攻击前给自己，加buff]=],
	SkillDes_364 = [=[主动攻击时，与战列舰以外的交战时，攻击前给自己加buff]=],
	SkillDes_365 = [=[行动结束后，使自身<color=#32a6ff>2</color>格范围内周围随机<color=#32a6ff>1</color>名友军[造成的伤害提升]<color=#32a6ff>10%</color>，持续<color=#32a6ff>1</color>回合]=],
	SkillDes_366 = [=[行动结束后，给我方全体加buff]=],
	SkillDes_367 = [=[行动结束后，给我方全体加buff（不包含自己）]=],
	SkillDes_368 = [=[行动结束后，给敌方全体加buff]=],
	SkillDes_369 = [=[行动结束后，给所有目标加buff]=],
	SkillDes_370 = [=[行动结束后，给距离自己最近的友军加buff]=],
	SkillDes_371 = [=[行动结束后，对除自身以外，耐久百分比最低的友军回复耐久值，回复量为自身炮击值的<color=#32a6ff>150%</color>]=],
	SkillDes_372 = [=[装甲提升<color=#32a6ff>5%</color>。击沉单位时，炮击、装甲额外提升<color=#32a6ff>10%</color>，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_376 = [=[装甲、防空降低<color=#32a6ff>5%</color>。炮击、雷击中较高的一项提升<color=#32a6ff>7%</color>。]=],
	SkillDes_377 = [=[自身耐久值大于等于<color=#32a6ff>90%</color>时，除耐久之外的全属性提升<color=#32a6ff>5%</color>。]=],
	SkillDes_378 = [=[自身周围<color=#32a6ff>2</color>格范围内不存在其他友军时，自身雷击提升<color=#32a6ff>10%</color>。]=],
	SkillDes_379 = [=[处于<color=#32a6ff>「下潜」</color>状态时，受到伤害额外降低<color=#32a6ff>10%</color>。]=],
	SkillDes_380 = [=[攻击开始时，将防空的<color=#32a6ff>5%</color>附加到炮击上。]=],
	SkillDes_381 = [=[幸运提升<color=#32a6ff>10%</color>。主动攻击击杀单位后，为自身<color=#32a6ff>3</color>格范围内的所有友军添加<color=#32a6ff>1</color>个增益效果。]=],
	SkillDes_382 = [=[受到单体攻击时，攻击前使攻击者造成伤害降低<color=#32a6ff>20%</color>，持续<color=#32a6ff>2</color>回合。如果该攻击类型为航空炮击/航空雷击，则伤害降低效果提升至<color=#32a6ff>30%</color>。]=],
	SkillDes_383 = [=[与炮击值低于自身的敌方作战时，自身造成的伤害提升<color=#32a6ff>10%</color>。与炮击值高于自身的敌方作战时，自身受到的伤害降低<color=#32a6ff>10%</color>。]=],
	SkillDes_384 = [=[单体主动攻击前，有<color=#32a6ff>50%</color>的概率驱散敌方<color=#32a6ff>1</color>个强化效果。目标是<color=#32a6ff>「潜艇」</color>时，额外移除<color=#32a6ff>「下潜」</color>效果。]=],
	SkillDes_385 = [=[单体主动攻击造成炮击伤害后，有<color=#32a6ff>50%</color>的概率附加“被动技能失效”，持续<color=#32a6ff>1</color>回合，自身炮击值大于敌方时，必定触发。单体主动攻击雷击伤害后，有<color=#32a6ff>50%</color>的概率附加“无法释放技能”，持续<color=#32a6ff>1</color>回合，自身雷击值大于敌方时，必定触发。]=],
	SkillDes_386 = [=[行动结束时，随机获得以下强化效果中的一种，持续<color=#32a6ff>2</color>回合。（炮击提升<color=#32a6ff>20%</color>、装甲提升<color=#32a6ff>20%</color>、机动提升<color=#32a6ff>20%</color>、防空提升<color=#32a6ff>20%</color>、移动力<color=#32a6ff>+1</color>、暴击率提升<color=#32a6ff>30%</color>）]=],
	SkillDes_387 = [=[炮击提高<color=#32a6ff>5%</color>。攻击开始时和自身行动结束时，随机获得<color=#32a6ff>1</color>个增益效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_388 = [=[额外增加幸运值<color=#32a6ff>20%</color>的装甲值和炮击值；不会受到中破/大破的影响。]=],
	SkillDes_389 = [=[行动结束时, 恢复自身<color=#32a6ff>20%</color>耐久。耐久值低于<color=#32a6ff>30%</color>时，恢复效果提升至<color=#32a6ff>30%</color>。]=],
	SkillDes_390 = [=[中破时：暴击率提升<color=#32a6ff>15%</color>，伤害减免提升<color=#32a6ff>15%</color>。大破时：提升效果<color=#32a6ff>翻倍</color>。]=],
	SkillDes_391 = [=[行动结束时，恢复<color=#32a6ff>10%</color>的耐久。受到单体攻击后，有<color=#32a6ff>30%</color>的概率恢复<color=#32a6ff>20%</color>的耐久值。]=],
	SkillDes_392 = [=[机动提升<color=#32a6ff>7%</color>。单体攻击前，对机动低于自身的敌军附加<color=#32a6ff>1</color>个随机异常效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_393 = [=[主动单体攻击时无视目标<color=#32a6ff>20%</color>装甲值。如果自身幸运值高于目标，效果提升至<color=#32a6ff>30%</color>。]=],
	SkillDes_394 = [=[“被动”场上有我方“磁性水雷”存在时，雷击提升<color=#32a6ff>7%</color>;场上无我方“磁性水雷”存在时，装甲提升<color=#32a6ff>7%</color>。]=],
	SkillDes_395 = [=[[被动]死亡后对自身<color=#32a6ff>1</color>格范围内的敌军造成自身雷击值<color=#32a6ff>50%</color>的穿透伤害，并附加“装甲降低<color=#32a6ff>20%</color>”的效果，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_396 = [=[主动单体攻击造成伤害后恢复伤害值<color=#32a6ff>10%</color>的耐久。“绝命孤舰”数量达到<color=#32a6ff>3</color>个或以上时，造成伤害提高<color=#32a6ff>10%</color>。受到<color=#32a6ff>2</color>格范围内的单体攻击时，自身每存在<color=#32a6ff>1</color>个“绝命孤舰”则有<color=#32a6ff>20%</color>概率进行反击，造成炮击<color=#32a6ff>30%</color>的伤害。]=],
	SkillDes_397 = [=[雷击伤害提升<color=#32a6ff>7%</color>。造成伤害后，移除目标的<color=#32a6ff>「下潜」</color>效果，并使其“无法获得下潜效果，持续<color=#32a6ff>2</color>回合。”]=],
	SkillDes_398 = [=[主动单体攻击前对目标造成<color=#32a6ff>1</color>次穿透伤害，伤害值为雷击的<color=#32a6ff>10%</color>；并驱散目标<color=#32a6ff>1</color>个强化效果，并降低其<color=#32a6ff>20%</color>的机动，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_399 = [=[当前耐久<color=#32a6ff>50%</color>或以上时，装甲和机动提升<color=#32a6ff>10%</color>；当前耐久<color=#32a6ff>50%</color>以下时，炮击提升<color=#32a6ff>10%</color>。]=],
	SkillDes_400 = [=[装甲和机动提高<color=#32a6ff>5%</color>。行动结束时如果处于<color=#32a6ff>「下潜」</color>状态则有<color=#32a6ff>60%</color>概率净化自身<color=#32a6ff>1</color>个弱化状态。]=],
	SkillDes_401 = [=[装甲提升<color=#32a6ff>5%</color>。所有水域中的移动力消耗均为<color=#32a6ff>1</color>点。]=],
	SkillDes_402 = [=[维修效果提升<color=#32a6ff>10%</color>。自身<color=#32a6ff>2</color>格范围内每存在<color=#32a6ff>1</color>名友军时，炮击提升<color=#32a6ff>4%</color>。（最高<color=#32a6ff>12%</color>）]=],
	SkillDes_403 = [=[装甲降低<color=#32a6ff>7%</color>，雷击、机动提升<color=#32a6ff>10%</color>。]=],
	SkillDes_404 = [=[场上存在其他<color=#32a6ff>1</color>名以上友军<color=#32a6ff>「航母」</color>单位时，雷击提升<color=#32a6ff>7%</color>，暴击率提升<color=#32a6ff>10%</color>。否则装甲、机动提升<color=#32a6ff>7%</color>。]=],
	SkillDes_405 = [=[装甲、机动提升<color=#32a6ff>5%</color>。受到单体雷击攻击时有<color=#32a6ff>50%</color>的概率使此次伤害降低<color=#32a6ff>15%</color>。]=],
	SkillDes_406 = [=[当自身耐久百分比高于<color=#32a6ff>50%</color>时，炮击、雷击提升<color=#32a6ff>5%</color>，暴击率提升<color=#32a6ff>10%</color>。]=],
	SkillDes_407 = [=[免疫“移动力降低”，在寒冷海域不受移动力降低影响。行动结束时，使<color=#32a6ff>2</color>格范围内的<color=#32a6ff>1</color>个其他非航母友军获得“使用攻击技能后，有<color=#32a6ff>50%</color>概率使该技能的冷却时间<color=#32a6ff>-1</color>效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_408 = [=[装甲提升<color=#32a6ff>7%</color>。遭受致命伤害时不会死亡，之后耐久值恢复<color=#32a6ff>20%</color>，该效果每场战斗最多触发<color=#32a6ff>1</color>次。]=],
	SkillDes_409 = [=[雷击提升<color=#32a6ff>5%</color>。主动单体攻击后有<color=#32a6ff>50%</color>的概率驱散敌方<color=#32a6ff>1</color>个强化状态。]=],
	SkillDes_410 = [=[处于<color=#32a6ff>「下潜」</color>状态时，受到伤害降低<color=#32a6ff>10%</color>。<color=#32a6ff>「下潜」</color>状态下进行攻击，雷击提升<color=#32a6ff>10%</color>。]=],
	SkillDes_411 = [=[友军行动结束时如果位于自身周围<color=#32a6ff>2</color>格范围内，获得“防空提高<color=#32a6ff>20%</color>”，“免疫穿透伤害”，持续2回合。]=],
	SkillDes_412 = [=[单体攻击移动力低于自身的单位时，无视目标10%的装甲。]=],
	SkillDes_413 = [=[装甲提升7%。移动时无视敌方阻挡效果。]=],
	SkillDes_414 = [=[自身周围<color=#32a6ff>3</color>格范围内存在中破、大破敌方时，自身雷击提升<color=#32a6ff>10%</color>。]=],
	SkillDes_415 = [=[受到修理效果提升15%。受到修理后，如果当前耐久达到100%，则随机获得1个改装效果。]=],
	SkillDes_416 = [=[受到「航母」攻击时，将炮击的5%附加到防空。]=],
	SkillDes_417 = [=[未获得「下潜」时，受到主动攻击后获得「下潜」。]=],
	SkillDes_418 = [=[战斗开始时，获得「剥被帽装甲」。「剥被帽装甲」：装甲提升20%，持续至战斗结束。受到导致中破的伤害时，将当前耐久百分比维持在70%，之后失去「剥被帽装甲」。]=],
	SkillDes_419 = [=[免疫晕眩、位移效果。自身<color=#32a6ff>1</color>格范围内没有敌军时，受到伤害减少<color=#32a6ff>20%</color>。]=],
	SkillDes_420 = [=[免疫晕眩、位移效果。行动结束时，对自身<color=#32a6ff>4</color>格范围内的<color=#32a6ff>2</color>个敌军附加“行动前受到最大耐久<color=#32a6ff>10%</color>伤害，无法驱散”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_421 = [=[免疫晕眩、位移效果。受到炮击伤害后，获得“装甲强化Ⅰ”效果，移除“机动强化Ⅰ”效果；受到雷击伤害后，获得“机动强化Ⅰ”效果，移除“装甲强化Ⅰ”效果。]=],
	SkillDes_422 = [=[免疫晕眩、位移效果。自身<color=#32a6ff>1</color>格范围内没有敌军时，受到伤害减少<color=#32a6ff>30%</color>。]=],
	SkillDes_423 = [=[免疫晕眩、位移效果。行动结束时，对自身<color=#32a6ff>4</color>格范围内的<color=#32a6ff>2</color>个敌军附加“行动前受到最大耐久<color=#32a6ff>15%</color>伤害，无法驱散”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_424 = [=[免疫晕眩、位移效果。受到炮击伤害后，获得“装甲强化Ⅱ”效果，移除“机动强化Ⅱ”效果；受到雷击伤害后，获得“机动强化Ⅱ”效果，移除“装甲强化Ⅱ”效果。]=],
	SkillDes_425 = [=[免疫晕眩、位移效果。自身<color=#32a6ff>1</color>格范围内没有敌军时，受到伤害减少<color=#32a6ff>50%</color>。]=],
	SkillDes_426 = [=[免疫晕眩、位移效果。行动结束时，对自身<color=#32a6ff>4</color>格范围内的<color=#32a6ff>2</color>个敌军附加“行动前受到最大耐久<color=#32a6ff>20%</color>伤害，无法驱散”效果，持续<color=#32a6ff>1</color>回合。]=],
	SkillDes_427 = [=[免疫晕眩、位移效果。受到炮击伤害后，获得“装甲强化Ⅲ”效果，移除“机动强化Ⅲ”效果；受到雷击伤害后，获得“机动强化Ⅲ”效果，移除“装甲强化Ⅲ”效果。]=],
	SkillDes_428 = [=[行动开始时，自身范围<color=#32a6ff>2</color>格范围内每有一个敌军，提升自身<color=#32a6ff>10%</color>雷击值，最高提升<color=#32a6ff>20%</color>，行动后效果消失。]=],
	SkillDes_429 = [=[炮击提升<color=#32a6ff>20%</color>，每受到<color=#32a6ff>1</color>次远程攻击，提升效果削弱<color=#32a6ff>10%</color>。行动结束后清除削弱效果。]=],
	SkillDes_430 = [=[攻击耐久低于<color=#32a6ff>80%</color>敌人时，伤害提高<color=#32a6ff>20%</color>。]=],
	SkillDes_431 = [=[对空提高<color=#32a6ff>20%</color>，主动攻击时，如果目标的<color=#32a6ff>2</color>格范围内有敌对角色，伤害提高<color=#32a6ff>10%</color>。]=],
	SkillDes_432 = [=[行动结束时，随机<color=#32a6ff>4</color>格范围内的一个敌人增加<color=#32a6ff>1</color>个减益，持续<color=#32a6ff>2</color>回合。]=],
	SkillDes_433 = [=[行动结束时，进入下潜状态。]=],
	SkillDes_434 = [=[回合开始时，对随机1个敌人施加“延迟震爆弹”：行动结束时，对2格范围内友军(含自身)造成最大耐久20%的穿透伤害，持续1回合。（不可驱散}。击败敌军后，可以额外行动1次。(每个回合最多触发1次)]=],
	SkillDes_435 = [=[回合开始时，驱散自身2个弱化效果。如果自身无弱化效果，则获得1个随机强化效果，持续4回合（炮击雷击/装甲/机动/防空+20%）。攻击后如果自身强化效果数量达到3个或以上时，则额外对目标造成1次雷击20%的穿透伤害。]=],
	SkillDes_436 = [=[免疫晕眩、位移效果。自身<color=#32a6ff>1</color>格范围内没有敌军时，受到伤害减少<color=#32a6ff>50%</color>。撤退时，全体友军火力、鱼雷提高<color=#32a6ff>20%</color>%，移动力+2，并恢复<color=#32a6ff>20%</color>耐久。]=],
