	SkillDes_438 = [=[免疫晕眩、位移效果。受到炮击伤害后，获得“装甲强化Ⅲ”效果，移除“机动强化Ⅲ”效果；受到雷击伤害后，获得“机动强化Ⅲ”效果，移除“装甲强化Ⅲ”效果。撤退时，全体友军火力、鱼雷提高<color=#32a6ff>20%</color>%，移动力+2，并恢复<color=#32a6ff>20%</color>耐久。]=],
	SkillDes_439 = [=[免疫晕眩、位移效果。回合开始时，在自身周围召唤一个小触手，如果场上有2个或以上小触手则召唤一个大触手。当场上有小触手，自身火力和鱼雷提高20%，当场上有大触手时，效果提高至40%。]=],
