	ScriptLine_101001 = [=[苍蓝避风港]=],
	ScriptLine_101002 = [=[今天是戴这个发箍，还是这个小礼帽呢？真难选哟……{Action=1010103,Time=6}指挥官，你觉得呢？]=],
	ScriptLine_101003 = [=[红色是热烈的甜，黄色是温暖的甜，绿色是青涩的甜……{Action=1010104,Time=7}不同颜色的马卡龙，甜味也有微妙的差别哟！]=],
	ScriptLine_101004 = [=[参加派对不需要穿得太华丽？唔……{Action=1010103,Time=3}那就只戴五件首饰吧。]=],
	ScriptLine_101005 = [=[咿呀！好可怕的雷声！{Action=1010109,Time=2}呜呜呜……指挥官，放我回去嘛，我不要值夜班哟！]=],
	ScriptLine_101006 = [=[这件衣服的布料很高级哦，指挥官也来摸摸看哟！]=],
	ScriptLine_101007 = [=[粉色是可爱的甜，紫色是魅惑的甜，黑色是危险的甜……{Action=1010104,Time=8}亲爱的指挥官，你喜欢哪一种甜？]=],
	ScriptLine_101008 = [=[呜呜呜……虽然很害怕，但现在不能退缩！可恶的蟑螂，快给我滚出指挥官的房间哟！]=],
	ScriptLine_101009 = [=[呜，胸衣又紧了……指挥官，帮、帮我从背后松一下哟……]=],
	ScriptLine_101010 = [=[哼哼哼，哼哼哼……{Action=1010102,Time=3}这条裙子不行，太素了。这条？感觉和项链不太搭。这条？上周穿过了……唔，伤脑筋哟！究竟怎么搭配，才能给指挥官留下最深的印象呢……]=],
	ScriptLine_101011 = [=[我、我还在换衣服呢，不可以偷看哟！]=],
	ScriptLine_101012 = [=[战斗开始，一起来开宴会吧！]=],
	ScriptLine_101013 = [=[优雅，悠闲，游刃有余哟！]=],
	ScriptLine_101014 = [=[讨厌的虫子别过来哟！]=],
	ScriptLine_101015 = [=[讨厌的虫子别过来哟！]=],
	ScriptLine_101016 = [=[宴会……结束了哟……]=],
	ScriptLine_101017 = [=[不遵守宴会礼仪的家伙，给我退场！]=],
	ScriptLine_101018 = [=[不遵守宴会礼仪的家伙，给我退场！]=],
	ScriptLine_101019 = [=[呀——！有增援！这和说好的不一样哟！]=],
	ScriptLine_101020 = [=[呀——！有增援！这和说好的不一样哟！]=],
	ScriptLine_101021 = [=[正餐时间到——！]=],
	ScriptLine_101022 = [=[正餐时间到——！]=],
	ScriptLine_101023 = [=[来块小甜点吧！]=],
	ScriptLine_101024 = [=[来块小甜点吧！]=],
	ScriptLine_101025 = [=[嗯嗯，真是一场完美的宴会！]=],
	ScriptLine_101026 = [=[谁把我的鞋踩掉了哟？]=],
	ScriptLine_101027 = [=[敦刻尔克号战列舰，前来参加宴会哟！真期待啊，今天的甜品会是什么味道呢？]=],
	ScriptLine_101028 = [=[又见面了指挥官！看，这是我亲手做的甜品哟，让我们一起品尝吧！]=],
	ScriptLine_101029 = [=[竟然不知不觉变强了哟！等等，让我换件看起来更强的礼裙……]=],
	ScriptLine_101030 = [=[无论多么华丽的盛宴，都比不上您最平凡的陪伴；无论多么亲密的话语，都无法传达我对您心意的万分之一……]=],
	ScriptLine_101031 = [=[怎么了哟？]=],
