	ScriptLine_102001 = [=[苍蓝避风港]=],
	ScriptLine_102002 = [=[啊哈哈哈！指挥官，跟上我的步伐！我们的征途直至大海尽头！]=],
	ScriptLine_102003 = [=[这、这是……海盗的藏宝图！指挥官，快拿上铲子，跟基德大人去寻宝吧，财宝分你一半哦！]=],
	ScriptLine_102004 = [=[唔哎——！指挥官，你刚刚去哪了！不要丢下基德一个人啊！]=],
	ScriptLine_102005 = [=[呀哈哈哈哈！今天的冒险也好刺激啊！指挥官，那个巨大的爆炸，简直就是艺术！]=],
	ScriptLine_102006 = [=[嘿，居然敢挑衅我基德大人？{Action=1020104,Time=3}看我戳回去！戳戳戳！]=],
	ScriptLine_102007 = [=[嘿，船长！身为冒险团优秀团员，今天的目的地就交给你来决定吧！只要够新奇，去哪里都可以哟！]=],
	ScriptLine_102008 = [=[呼啊……今天真是太开心了……果然有你在的冒险才最有趣……晚安，船长……呼噜……]=],
	ScriptLine_102009 = [=[哼哼，基德大人我可不怕痒——{Action=1020109,Time=3}不行，挠那里犯规！呀哈哈哈哈——！]=],
	ScriptLine_102010 = [=[上午，去码头募集冒险团；下午，去冒险寻宝；晚上，坐在篝火边喝橘子汽水——{Action=1020111,Time=9}完美的计划！海盗之血沸腾起来啦！好的，这就去和指挥官商量！]=],
	ScriptLine_102011 = [=[哦，指挥官，来得正好。我正要跟你商量刚想到的“完美冒险计划”呢！]=],
	ScriptLine_102012 = [=[冲啊，冒险团！让敌人尝尝我们的厉害！]=],
	ScriptLine_102013 = [=[看我的！]=],
	ScriptLine_102014 = [=[看我的！]=],
