	ScriptLine_102026 = [=[海盗冒险团可是无敌的！]=],
	ScriptLine_102027 = [=[哇哈哈哈，太完美啦！海盗旗飘扬在大海之上！]=],
	ScriptLine_102028 = [=[总算赢啦，好险！海盗旗都被炮弹擦破了！]=],
	ScriptLine_102029 = [=[驱逐舰基德前来报道！指挥官，有兴趣加入海盗冒险团，和我一起出发去寻宝吗？]=],
	ScriptLine_102030 = [=[嘿嘿，我又来了！看，这是我新设计的海盗旗，是不是很帅呀！]=],
	ScriptLine_102031 = [=[哇哈哈哈，下次要去更深的海域冒险哦！]=],
	ScriptLine_102032 = [=[每一场战斗，每一次冒险，船长都陪在基德身边，原来船长才是基德最珍贵的宝物！亲爱的船长，今后也要一直陪着基德哦，{Action=1020104,Time=12}嘿嘿！]=],
