	ScriptLine_103061 = [=[嗯……]=],
	ScriptLine_103062 = [=[继续进军！]=],
	ScriptLine_103063 = [=[继续进军！]=],
	ScriptLine_103101 = [=[您注意到这耳环了？呵呵，即便是在办公室，也不能丢掉应有的高雅姿态。为了更好点缀这身服装，我可是稍微花了一点心思的呢~当然，私心也是有一点的……]=],
	ScriptLine_103102 = [=[指挥官，这件衬衫的领口实在太紧了，稍微解开两颗扣子应该没关系吧？呀~？！不、不是的，我没这个打算……呜呜，明石的视线也好刺人……]=],
	ScriptLine_103103 = [=[指挥官，有人在看着呢……您这么喜欢这身衣服的话，今晚下班后，人家会在这里等着您……]=],
	ScriptLine_103104 = [=[哎呀，指挥官要帮我按摩吗？正好坐久了，腿有点麻呢……那个，您的力道可以再大一点哦？现在这样轻轻的，反而有种奇妙的感觉……]=],
	ScriptLine_103105 = [=[我没事的，比起战场上的炮火，咖啡那点温度根本算不上什么。不过……您的手像这样一直贴在这里，传过来的温度，反而比咖啡还要烫人呢……]=],
	ScriptLine_103106 = [=[呀~？！呜……人家的丝袜遭殃了。黏糊糊的，感觉真糟糕……指挥官，我稍微离开一下……]=],
	ScriptLine_103107 = [=[嗯？好像有奇怪的东西跳出来了？是要我按这个吗……诶？诶诶？为什么？我、我什么也没动啊？这该不会要我赔偿吧？这个月还挺吃紧的……指挥官，想、想想办法，拜托了……]=],
	ScriptLine_103108 = [=[哇！框框全都不见了，屏幕也亮起来了！不愧是指挥官，轻易就做到了人家做不到的事！不放，人家还要再抱一会儿！因为人家真的好喜欢指挥官嘛！]=],
	ScriptLine_103109 = [=[指挥官，明石为什么在瞪我？人家明明什么都没做。头绪……？顶多就是把我们组的报销单数额多写了几个零而已——您说原因就是这个？可是钱多了，大家都会开心才对呀？]=],
	ScriptLine_103110 = [=[所谓的培养“大局观”和“后勤思维”，就是指一整天坐在这里瞪着屏幕吗？总觉得没有实感呢。还有这身衣服，穿起来总觉得紧绷绷的，完全限制了肢体的发力嘛。这样子可没办法碾碎敌人喔？]=],
	ScriptLine_104001 = [=[苍蓝避风港]=],
	ScriptLine_104002 = [=[指挥官？来得正好，能帮我拿一下架子顶上的东西吗？{Action=1020103,Time=5}唉……个子矮真不方便。]=],
	ScriptLine_104003 = [=[买卖这种事，讲究的是双方开心。只要对方觉得价格OK，就不算贵。]=],
	ScriptLine_104004 = [=[头发有点油油的，不过最近这天气，今晚洗头明天怕是要炸毛了……不行，忍不了了，还是要洗。]=],
	ScriptLine_104005 = [=[哈～犯困了……处理完账目早点睡吧。]=],
	ScriptLine_104006 = [=[嗯……嘻嘻，别害羞嘛，想摸的话大方点直说就好。]=],
	ScriptLine_104007 = [=[啊！这个别丢，太浪费了，给我吧……{Action=1040101,Time=4}要用来做什么？这你就别管了，我自有妙用。]=],
	ScriptLine_104008 = [=[好无聊啊。来聊点什么吧，指挥官，最好呢，是来点适合大人夜晚聊的话题～]=],
	ScriptLine_104009 = [=[诶……怎、怎么了指挥官，今天突然这么热情……]=],
	ScriptLine_104010 = [=[账目整理得差不多了，接下来……{Action=1040108,Time=5}去指挥官的房间转转好了，说不定能找到什么羞羞的宝贝，嘻嘻嘻～]=],
	ScriptLine_104011 = [=[呀～指挥官你回来啦，有带什么东西来犒劳我吗？]=],
	ScriptLine_104012 = [=[我上前线？真的假的啊……]=],
	ScriptLine_104013 = [=[指挥官，接下来怎么做？]=],
	ScriptLine_104014 = [=[噫！好危险！]=],
	ScriptLine_104015 = [=[唔……别管我！那些装备还没坏，快捞回来啊！]=],
	ScriptLine_104016 = [=[哇哦？真的击沉了诶。]=],
	ScriptLine_104017 = [=[这……怎么没完没了啊！]=],
	ScriptLine_104018 = [=[维修设备准备完毕。]=],
	ScriptLine_104019 = [=[维修设备准备完毕。]=],
	ScriptLine_104020 = [=[给我打中啊！]=],
	ScriptLine_104021 = [=[给我打中啊！]=],
	ScriptLine_104022 = [=[开工咯——！]=],
	ScriptLine_104023 = [=[开工咯——！]=],
	ScriptLine_104024 = [=[以我的实力来说，这战果算是很不错吧？]=],
	ScriptLine_104025 = [=[大家平安归来，就是不幸中的万幸了。]=],
	ScriptLine_104026 = [=[维修舰明石号，前来报到。打打杀杀的我不在行，后勤交给我包你放心。]=],
	ScriptLine_104027 = [=[指挥官你尽管盯着前线，受伤的人就交给我明石号来照顾。]=],
	ScriptLine_104028 = [=[在我身上投资，保证有所回报。]=],
	ScriptLine_104029 = [=[当初平平无奇的港区，如今也像模像样了呀……功成身退？怎么可能嘛，没我盯着，财政搞不好隔天就赤字了……喂喂，我就是说说而已，不用露出这种小狗一样的眼神啦。放心，我会……永远在你身边（小声）。听、听不到就算啦！]=],
	ScriptLine_104030 = [=[啊咧？]=],
	ScriptLine_104031 = [=[啊咧？]=],
