	ScriptLine_106001 = [=[苍蓝避风港]=],
	ScriptLine_106002 = [=[早上好，指挥官！若不嫌弃的话，请让我为您泡一杯新茶提提神吧。]=],
	ScriptLine_106003 = [=[“晚霞行千里，朝霞不出门”。泛红的天色是暴风雨的前兆，今天的远征计划，是否应当调整一下？]=],
	ScriptLine_106004 = [=[照顾上蹿下跳的基德就如同钓鱼，生拉硬拽是新手的做法。如何让她高高兴兴地自愿跳进网兜，可是一门学问哦。]=],
	ScriptLine_106005 = [=[劳累了一天，您看起来似乎有些疲惫呢。要解乏的话，我推荐来一杯加了蜂蜜的香茶哦。]=],
	ScriptLine_106006 = [=[冲泡茶叶也好，开扇收扇也罢，明明这些都能轻易做到，为何唯独筷子——！]=],
	ScriptLine_106007 = [=[红油火锅？很抱歉，我不习惯吃辣，鸳鸯锅是我的底线。而且在指挥室吃火锅……是否有些不妥呢？]=],
	ScriptLine_106008 = [=[如此轻浮地对待淑女，想来您已经做好觉悟了吧？]=],
	ScriptLine_106009 = [=[放心交给我吧，指挥官。身为淑女，无论执行多么困难的任务，都绝不会令您蒙羞。]=],
	ScriptLine_106010 = [=[您说茶的味道有点怪？不应该呀，我只是加入了一些能传达心意的香料……{Action=1060115,Time=7}呜！怎么有辣椒——！]=],
	ScriptLine_106011 = [=[指挥官，您知道的，让我吃辣会招致可怕的事……今晚的暗锅大会，您确定不会有人放辣椒进锅吗？]=],
	ScriptLine_106012 = [=[为了下次聚餐时不给指挥官丢脸而半夜练习夹豆子……这么做真的很奇怪吗？]=],
	ScriptLine_106013 = [=[有资格直接触碰淑女身体的，只有温柔体贴的您……]=],
	ScriptLine_106014 = [=[无事发生虽然值得庆幸，但总觉得有点无趣……{Action=1060104,Time=4}如果是基德的话，会不会为了寻求刺激，弄出震动港区的“大事件”来呢？比如偷偷跑进武器库，搞出个爆炸性的序章………]=],
	ScriptLine_106015 = [=[呃，指挥官！刚刚我只是在担心基德，绝对没有想要加入的意思哦！]=],
	ScriptLine_106016 = [=[淑女们，拿出餐刀！茶点时间开始了！]=],
	ScriptLine_106017 = [=[战斗就位！]=],
	ScriptLine_106018 = [=[战斗就位！]=],
	ScriptLine_106019 = [=[完全不痛！]=],
	ScriptLine_106020 = [=[完全不痛！]=],
	ScriptLine_106021 = [=[我还能战斗！我还能……]=],
	ScriptLine_106022 = [=[我还能战斗！我还能……]=],
	ScriptLine_106023 = [=[沉没吧！不自量力的家伙！]=],
	ScriptLine_106024 = [=[沉没吧！不自量力的家伙！]=],
	ScriptLine_106025 = [=[竟还有不请自来的家伙，真是……令人愉悦啊！]=],
	ScriptLine_106026 = [=[领受这一击！]=],
	ScriptLine_106027 = [=[领受这一击！]=],
	ScriptLine_106028 = [=[哈——！]=],
	ScriptLine_106029 = [=[哈——！]=],
	ScriptLine_106030 = [=[前进的道路……由我开拓！]=],
	ScriptLine_106031 = [=[喝彩吧！这是属于淑女的完全胜利！]=],
	ScriptLine_106032 = [=[胜利？不，这种程度，还远远不够……]=],
	ScriptLine_106033 = [=[轻巡洋舰重庆号向您报道！无论战斗、泡茶、照顾朋友还是战斗，都是我应尽的责任……哎，“战斗”说了两遍？]=],
	ScriptLine_106034 = [=[重庆号于此起誓，将为了成为更端庄的淑女而继续修行……哎？太正式了吗？]=],
	ScriptLine_106035 = [=[对辣抗性提升了……吗？似乎并没有，真可惜……]=],
	ScriptLine_106036 = [=[勇敢的淑女越是直面困境，越应吹起希望的号角——与您相伴的日子让我明白，这绝不是毫无依据的空言，而是鼓舞我永远支持您的誓言……]=],
