	ScriptLine_106064 = [=[哈哈哈！]=],
	ScriptLine_107001 = [=[苍蓝避风港]=],
	ScriptLine_107002 = [=[从忙碌的工作中解放了，究竟是好事还是坏事呢？心里面像是缺了一块重要的东西。{Action=1070107,Time=8}还好，您依旧在我身边。看着您，就不会想那么多了。]=],
	ScriptLine_107003 = [=[世界就像是一场宏大的舞台剧，身处其中的我们，或许渺小，却不卑微。我们的人生，由我们自己决定。]=],
	ScriptLine_107004 = [=[趁它们去做体检了，正好给宿舍来一个大扫除。{Action=1070127,Time=4}还有，这么大的猫爬架，您得来帮忙。我对拼装是一窍不通，真要我自己来，不知道最后会变成什么“奇观”。]=],
	ScriptLine_107005 = [=[或许可以在这里增设岗哨……{Action=1070107,Time=3}啊，您也来了。{Action=1070128,Time=5}是的，一闲下来就想给自己找点事做。但逛了一圈，她们都觉得我要是来帮忙，反而会让她们压力很大……]=],
	ScriptLine_107006 = [=[对人保持微笑，可以获得很不错的印象分。再说了，您笑起来更好看，总是沉着脸也太浪费了。来，调动一下嘴角的肌肉——{Action=1070129,Time=12}微、笑。]=],
	ScriptLine_107007 = [=[你们看来是真喜欢这个东西。呵呵，是指挥官给你们买的。{Action=1070128,Time=5}俗话说，要“知恩图报”，但你们是小猫咪，也就不要求那么多了。只要他下次再来的时候，别又跳到他头上……]=],
	ScriptLine_107008 = [=[（握拳）什么是不会改变的？请解释清楚哦。]=],
	ScriptLine_107009 = [=[我买了不少冷萃咖啡液，这样就能直接往茶里加了。哈哈，当然是用的一般茶叶。好茶是不需要咖啡来调和味道的，不信你尝尝看——]=],
	ScriptLine_107010 = [=[嗯，我算是习惯现在的生活了。当然，这都要归功于你。{Action=1070108,Time=5}要是没你陪我到处逛的话，我又要回到演习场跟宿舍两点一线的生活了。{Action=1070105,Time=11}所以说，下次要去哪里呢？]=],
	ScriptLine_107011 = [=[空闲下来，总会不由得回想过去。一直在你身边的我，比谁都要清楚你究竟吃了多少苦才走到今天。{Action=1070107,Time=10}也自然，比谁都要高兴——因为，你的理想正在逐步成为现实。]=],
	ScriptLine_107012 = [=[鱼饼——！{Action=1070127,Time=2}哎，它好像特别喜欢待在你肩膀上。那里明明应该是我…咳咳，夜里风有点大，最好多加件衣服。至于你，快点下来！]=],
	ScriptLine_107013 = [=[唉，又是这种恶作剧。呀~我好吃惊~]=],
	ScriptLine_107014 = [=[既然同在一个小队里，必须要处理好彼此的关系。放任不管的话，迟早会……说是这么说，该从哪里开始着手呢？威尔士亲王…你到底经历过什么？]=],
	ScriptLine_107015 = [=[嗯？您找我有事吗？{Action=1070107,Time=2}不，我有空哦。请您吩咐。]=],
	ScriptLine_107016 = [=[不用担心，有前辈我在。]=],
	ScriptLine_107017 = [=[是时候了。]=],
	ScriptLine_107018 = [=[咕……！]=],
	ScriptLine_107019 = [=[咕……！]=],
	ScriptLine_107020 = [=[咕……！]=],
	ScriptLine_107021 = [=[接下来交给你们了。]=],
	ScriptLine_107022 = [=[嗯，手感不错。]=],
	ScriptLine_107023 = [=[小心，敌方支援到了。]=],
	ScriptLine_107024 = [=[热身结束了。]=],
	ScriptLine_107025 = [=[热身结束了。]=],
	ScriptLine_107026 = [=[我的对手是你吗？]=],
	ScriptLine_107027 = [=[我的对手是你吗？]=],
	ScriptLine_107028 = [=[理所当然的结果。]=],
	ScriptLine_107029 = [=[还有不少改进空间啊。]=],
	ScriptLine_107030 = [=[看来我们的时代还没有结束啊。能重回战场，是好事也是坏事。但无论如何，胡德永远站在您的身边。]=],
	ScriptLine_107031 = [=[胡德，听候您的差遣。]=],
	ScriptLine_107032 = [=[百尺竿头，更进一步。]=],
	ScriptLine_107033 = [=[我们的命运，已经紧紧地相连在一起了。就算这段旅程迎来终点，我也会陪在您身边。毕竟，我们早就约好了，要永远在一起。]=],
	ScriptLine_107034 = [=[嗯？]=],
	ScriptLine_107035 = [=[嗯？]=],
	ScriptLine_107036 = [=[嗯。]=],
	ScriptLine_107037 = [=[嗯。]=],
	ScriptLine_107038 = [=[呵呵。]=],
	ScriptLine_107039 = [=[呵呵。]=],
	ScriptLine_107040 = [=[啊……]=],
	ScriptLine_107041 = [=[啊……]=],
	ScriptLine_107042 = [=[啧……]=],
	ScriptLine_107043 = [=[啧……]=],
	ScriptLine_107044 = [=[调整策略，变更为支援战术。]=],
	ScriptLine_107045 = [=[调整策略，变更为支援战术。]=],
	ScriptLine_107046 = [=[嗯。]=],
