	ScriptLine_107048 = [=[嗯……]=],
	ScriptLine_107049 = [=[指挥官。]=],
	ScriptLine_107050 = [=[指挥官。]=],
	ScriptLine_107051 = [=[等……等一下……！]=],
	ScriptLine_107052 = [=[等……等一下……！]=],
	ScriptLine_107053 = [=[嗯呵呵……]=],
	ScriptLine_107054 = [=[嗯呵呵……]=],
	ScriptLine_107055 = [=[诶？]=],
	ScriptLine_107056 = [=[诶？]=],
	ScriptLine_107057 = [=[退散吧。]=],
	ScriptLine_107058 = [=[退散吧。]=],
	ScriptLine_107059 = [=[可爱的小家伙……]=],
	ScriptLine_107060 = [=[可爱的小家伙……]=],
	ScriptLine_107061 = [=[我会处理好一切。]=],
	ScriptLine_107062 = [=[我会处理好一切。]=],
	ScriptLine_107101 = [=[你干什么……这样我就看不清了。坏心眼……又在盘算什么呢？]=],
	ScriptLine_107102 = [=[你的指尖，好像在颤抖。呵呵，使坏的人怎么先紧张起来了~]=],
	ScriptLine_107103 = [=[想知道……这一颗是什么味道吗？]=],
	ScriptLine_107104 = [=[一件件不起眼的小事，构成了爱的旋律。]=],
	ScriptLine_107105 = [=[蓝风铃与玫瑰，盛放活力，将甜蜜融于指尖。]=],
	ScriptLine_107106 = [=[……怎么不说话了？哼，一定没安好心。]=],
	ScriptLine_107107 = [=[也没必要……这么急于表现吧……我知道了！快停下啦……]=],
	ScriptLine_107108 = [=[这算是按摩吗……总觉得，你的手法很奇怪啊……]=],
	ScriptLine_107109 = [=[呀！？这不是玩具啦！你到底在想些什么呀……]=],
	ScriptLine_107110 = [=[你给我送了这么多礼物，我也要有点表示才对。还有，今晚我只想听到肯定的答复。相应的，我也会尽量满足…你的要求。那么，你~满意吗？]=],
	ScriptLine_108001 = [=[苍蓝避风港]=],
	ScriptLine_108002 = [=[为了适应时代，学习种种新事物固然重要。但“传统”亦有其价值，无论是视之为经验，或是为了所谓的修养。]=],
	ScriptLine_108003 = [=[我的箭，会为那些孩子们护航，确保她们能一往无前。]=],
	ScriptLine_108004 = [=[呵呵，请放心，加贺即便贪杯，也不会忘记正事。即便她忽略了，我也会在一旁好好看住她。]=],
	ScriptLine_108005 = [=[要来杯热茶暖暖身子吗？指挥官。]=],
	ScriptLine_108006 = [=[看来处理文书，让您甚是烦恼呢。{Action=1080101,Time=3}那，要试着冥想一会儿，平静下内心吗？]=],
	ScriptLine_108007 = [=[真是宁静呢……真好，特别是，能像这样伴您左右。]=],
	ScriptLine_108008 = [=[指挥官……刚才，是无心的吧？]=],
	ScriptLine_108009 = [=[我喜欢的食物吗？呵呵……指挥官不妨猜猜看，{Action=1080102,Time=6}提示是……无论是什么食物，前缀必然是“指挥官亲手做的”。]=],
	ScriptLine_108010 = [=[最近，似乎有些松懈了。一面觉得这样不好的同时，{Action=1080110,Time=6}却又不禁为您的存在而感到放松……真是一处令人安心的港湾。]=],
	ScriptLine_108011 = [=[这份请求或许有点唐突，能再……稍微陪您一会儿吗？就像这样，与您静静地沐浴在月光中……]=],
	ScriptLine_108012 = [=[夜深了，肚子会饿吗？只要是我知道的，都可以做给您尝尝。]=],
	ScriptLine_108013 = [=[唔……可别让其他人看到……特别是加贺……]=],
	ScriptLine_108014 = [=[指挥官今天也甚是忙碌，在他回来之前，先把这些文书工作处理完吧……{Action=1080106,Time=8}指挥官……请，快点回来……]=],
	ScriptLine_108015 = [=[恭候多时了，指挥官。]=],
	ScriptLine_108016 = [=[一航战，出击。]=],
	ScriptLine_108017 = [=[一航战，出击。]=],
	ScriptLine_108018 = [=[等待您的调遣。]=],
	ScriptLine_108019 = [=[等待您的调遣。]=],
	ScriptLine_108020 = [=[未伤到要害……]=],
	ScriptLine_108021 = [=[未伤到要害……]=],
	ScriptLine_108022 = [=[别、别担心，我不要紧的……加贺，指挥官就拜托你了。]=],
	ScriptLine_108023 = [=[别、别担心，我不要紧的……加贺，指挥官就拜托你了。]=],
	ScriptLine_108024 = [=[箭无虚发，一击……必杀。]=],
	ScriptLine_108025 = [=[箭无虚发，一击……必杀。]=],
	ScriptLine_108026 = [=[保持好阵形，航空队，出动！]=],
	ScriptLine_108027 = [=[保持好阵形，航空队，出动！]=],
	ScriptLine_108028 = [=[天穹之下，无所遁形。]=],
	ScriptLine_108029 = [=[天穹之下，无所遁形。]=],
	ScriptLine_108030 = [=[中！]=],
	ScriptLine_108031 = [=[中！]=],
	ScriptLine_108032 = [=[如指挥官您所预测的那样，教科书般的胜利。]=],
	ScriptLine_108033 = [=[很抱歉，未能尽善尽美。]=],
	ScriptLine_108034 = [=[一航战，赤城号。我会和加贺一起，守护好此处，不辱您的荣耀。]=],
	ScriptLine_108035 = [=[赤城号，以一航战的名誉起誓，无论何时都会护您左右。]=],
	ScriptLine_108036 = [=[必将不负您的期望。]=],
	ScriptLine_108037 = [=[我有过太多的遗憾，但……如今的我想称之为“试练”，是为了与您相遇，而踏过的试练。跨越巨浪，拨云见日，我终于寻得……属于我的“避风港”。]=],
	ScriptLine_108038 = [=[嗯？]=],
	ScriptLine_108039 = [=[嗯？]=],
	ScriptLine_108040 = [=[了解。]=],
	ScriptLine_108041 = [=[了解。]=],
	ScriptLine_108042 = [=[呵呵。]=],
	ScriptLine_108043 = [=[呵呵。]=],
	ScriptLine_108044 = [=[唔……]=],
	ScriptLine_108045 = [=[唔……]=],
	ScriptLine_108046 = [=[指挥官。]=],
	ScriptLine_108047 = [=[指挥官。]=],
	ScriptLine_108048 = [=[指挥官。]=],
	ScriptLine_108049 = [=[指挥官。]=],
	ScriptLine_108050 = [=[断不能原谅！]=],
	ScriptLine_108051 = [=[断不能原谅！]=],
	ScriptLine_108052 = [=[精妙之策……无需多言。]=],
	ScriptLine_108053 = [=[精妙之策……无需多言。]=],
	ScriptLine_108054 = [=[唔？！]=],
	ScriptLine_108055 = [=[唔？！]=],
	ScriptLine_108056 = [=[呵呵……真是的……]=],
	ScriptLine_108057 = [=[呵呵……真是的……]=],
	ScriptLine_108058 = [=[心静自然清。]=],
	ScriptLine_108059 = [=[无意义的事，何时休止？]=],
	ScriptLine_108060 = [=[呀……！]=],
	ScriptLine_108061 = [=[呀……！]=],
	ScriptLine_108062 = [=[唔……]=],
	ScriptLine_108063 = [=[唔……]=],
	ScriptLine_108064 = [=[不可以这样。]=],
	ScriptLine_108065 = [=[不可以这样。]=],
	ScriptLine_108066 = [=[嗯……？]=],
	ScriptLine_108067 = [=[嗯……？]=],
	ScriptLine_108101 = [=[呵呵，欢迎回来，指挥官……嗯？在意我这副打扮吗？家里只有我们两人，就让我稍微放松一下，任性一下，也可以吧？]=],
	ScriptLine_108102 = [=[我正在整理床铺呢。都怪今早……嗯，稍微有些贪睡了……指、指挥官，您一直这样注视着我，会让我……有些不知所措的……请再稍等片刻，等我整理好这里……今天剩下的所有时间，都只属于您一人。]=],
	ScriptLine_108103 = [=[啊……！指挥官，好痒……呵呵，是故意的吗？真是的，您偶尔也会像个孩子一样调皮呢。]=],
	ScriptLine_108104 = [=[后背，是自己无法触及的地方呢。将这里交给您，就意味着……我将全部的信赖，都托付给了您——呀！？人家明明在认真表白，您的手指却……真是的……{Action=1080307,Time=13.1}]=],
	ScriptLine_108105 = [=[呵呵，您在看那幅画吗？画里那孩子的笑容，您不觉得……和您偶尔有鬼点子时候的样子，有几分神似吗？呵呵，开玩笑的。]=],
	ScriptLine_108106 = [=[您的手好温暖……指尖划过发丝的触感，让人安心到……快要融化了……被您这样珍视着的感觉，真好。]=],
	ScriptLine_108107 = [=[据说，我心情好的时候，这对猫耳会轻轻地动一下……您看，像现在这样……是不是很可爱？]=],
	ScriptLine_108108 = [=[指挥官……这是？呵呵，是在考验我们之间的信赖吗？也好……我愿意将自己完全交托于您。只是看不见您的脸庞，反而让我的心跳……有些加快呢。]=],
	ScriptLine_108109 = [=[啊……睁眼后第一眼就看到您……让我感到安心。现在我更加确信，您就是我的“避风港”了。呵呵，您那带着些许绯红的脸庞……真可爱。]=],
	ScriptLine_108110 = [=[这件睡衣的料子很薄吧？所以……您的指尖在做什么，我可都一清二楚哦。不许……乱来……{Action=1080304,Time=9.4}]=],
	ScriptLine_109001 = [=[苍蓝避风港]=],
	ScriptLine_109002 = [=[我没有提不起劲哦，只是在思考下次画画的素材罢了。对了，指挥官也来帮我想想吧，您喜欢绚丽的珊瑚，还是洁白的贝壳？]=],
	ScriptLine_109003 = [=[和他人对话真的好难，不仅要理解明面上的意思，还要分析说话人的情绪和意图……{Action=1090101,Time=9}相比之下，和伯格它们沟通就简单多了。]=],
	ScriptLine_109004 = [=[夜潜时的海水虽然很凉，但有助于让人头脑清醒，有时候还能因此看到特别的风景呢。]=],
	ScriptLine_109005 = [=[……（发呆）……这样的夜晚，很适合做一些有气氛的事，像是……看恐怖片之类的？]=],
	ScriptLine_109006 = [=[指、指挥官身上传来了不洁的气息……]=],
	ScriptLine_109007 = [=[海底世界的照片，很漂亮吧？呵呵，下次我还会再多拍一些。]=],
	ScriptLine_109008 = [=[除了恐怖片，偶尔我也是会想看其他电影的……比如和指挥官一起看爱、爱情片……]=],
	ScriptLine_109009 = [=[再这样的话，我真的要反击了哦~]=],
	ScriptLine_109010 = [=[奥托，不要在指挥官这里捣乱啦，弗里德里希你也是，为什么总是要欺负伯格呢？]=],
	ScriptLine_109011 = [=[啊，嗯……让您见笑了，小家伙们虽然闹腾，但其实是很喜欢您这边才会如此。]=],
	ScriptLine_109012 = [=[我会尽好职责，也希望大家能好好配合我……就这样。]=],
	ScriptLine_109013 = [=[请下令吧。]=],
	ScriptLine_109014 = [=[请下令吧。]=],
