	ScriptLine_109019 = [=[拜拜，下辈子不要再撞上我了。]=],
	ScriptLine_109020 = [=[拜拜，下辈子不要再撞上我了。]=],
	ScriptLine_109021 = [=[又来？唉……运气不好啊。]=],
	ScriptLine_109022 = [=[又来？唉……运气不好啊。]=],
	ScriptLine_109023 = [=[弗里德里希，我们上。]=],
	ScriptLine_109024 = [=[弗里德里希，我们上。]=],
	ScriptLine_109025 = [=[哦，有破绽。]=],
	ScriptLine_109026 = [=[哦，有破绽。]=],
	ScriptLine_109027 = [=[嗯……去吧！]=],
	ScriptLine_109028 = [=[嗯……去吧！]=],
	ScriptLine_109029 = [=[太好了……今天注意力超集中……]=],
	ScriptLine_109030 = [=[呼……胜利了就好，我准备带小家伙们回去休息一下。]=],
	ScriptLine_109031 = [=[……啊，抱歉，不小心走神了一会。我是U-81哦，需要我出马的时候，就尽管来叫我吧。]=],
	ScriptLine_109032 = [=[我们又相遇了，指挥官。刚好这些小家伙们也说想见你，要一起玩一会儿吗？]=],
	ScriptLine_109033 = [=[嗯，这样就能赶上前辈们了。]=],
	ScriptLine_109034 = [=[和指挥官在一起的感觉就像潜水一样，发呆也没关系，说错话也没关系……我懂了，指挥官对我来说是不可缺少的，只要您一直陪在我身边，我就……非常高兴了~]=],
