	ScriptLine_110020 = [=[击沉目标！大家表现得都很棒喔！]=],
	ScriptLine_110021 = [=[侦测到敌军增援！没关系，物资还很充足。]=],
	ScriptLine_110022 = [=[侦测到敌军增援！没关系，物资还很充足。]=],
