	ScriptLine_110065 = [=[夜晚可是我的时间。]=],
	ScriptLine_110066 = [=[哼哼哼哼~哼哼哼哼~♪]=],
	ScriptLine_110101 = [=[嘿~指挥官莫非对女性的素颜也感兴趣？我是不介意让你看啦，毕竟无论什么时候我都是没有破绽的，呵呵~]=],
	ScriptLine_110102 = [=[指挥官，这个颜色怎么样？适合我吗？哼哼，你的眼神已经告诉我答案了。]=],
	ScriptLine_110103 = [=[你好奇的是这件衣服还是…我本人？老实交代~]=],
	ScriptLine_110104 = [=[咿，那里稍微有点……你的使坏方式还真是特别呢。]=],
	ScriptLine_110105 = [=[指挥官这是想……我这边正忙着，想和我玩闹的话还得再等会儿哦。]=],
	ScriptLine_110106 = [=[怎么样？身材保持得不错吧？我对自己这方面还是很有自信的。]=],
	ScriptLine_110107 = [=[只是一些成熟女士的爱用品罢了，没什么特别之处……呵呵，连我的私人物品都忍不住关心，真是一位缠人的指挥官~这样的你我也很…喜欢。]=],
	ScriptLine_110108 = [=[嗯，如你所说，这件衣服和我平时穿的那件颜色很相近，毕竟黑色是能给女性增添魅力的颜色，也非常适合我，不是吗？]=],
	ScriptLine_110109 = [=[像这样松懈的状态仅限于在你面前呢，一会儿出门后我会换上工作时的穿着。话说你身上这件衣服也有些皱了，等我化完妆后，帮你整理一下吧？]=],
	ScriptLine_110110 = [=[指挥官的存在感太过强烈，都让我无法安下心来化妆了，真是~今天就随便画画好了。诶？“即使不画也很美丽”……哎呀，不管是不是恭维话都让人听了很开心……]=],
	ScriptLine_111001 = [=[苍蓝避风港]=],
	ScriptLine_111002 = [=[说漂亮话的人太多，不差我一个，难听的话就由我来说。]=],
	ScriptLine_111003 = [=[训练了一上午，着实是饿坏了。若这时候能来碗热腾腾的面，那可真是再好不过了。]=],
	ScriptLine_111004 = [=[驱逐舰也不尽是需要让人照顾的小孩子，优秀的人理应照顾他人。而我，则是这类人之中的佼佼者～]=],
	ScriptLine_111005 = [=[天色好暗，也不知道巡逻执勤的其他孩子会不会害怕……]=],
	ScriptLine_111006 = [=[瞧，依我说的做，工作效率果然上去了吧。]=],
	ScriptLine_111007 = [=[瞧，依我说的做，工作效率果然上去了吧。]=],
	ScriptLine_111008 = [=[皱着眉头做什么？有什么烦恼就说吧，让我看看能不能帮你。]=],
	ScriptLine_111009 = [=[喂？！做、做什么呀！]=],
	ScriptLine_111010 = [=[喂？！做、做什么呀！]=],
	ScriptLine_111011 = [=[常言道“忠言逆耳”，指挥官你最讨人喜欢的，就是愿意把“苦口良药”服下去的这份真心。]=],
	ScriptLine_111012 = [=[觉得我很适合当“老师”？唔……我确实有考虑过这方面的事，但济南姐姐说我总爱管太多事，当老师怕是要被折腾得不轻。]=],
	ScriptLine_111013 = [=[乏了？那随我唱两段曲儿，提提神如何？]=],
	ScriptLine_111014 = [=[累了就去歇会儿，不用硬撑，这不是还有我在吗？去歇着吧。]=],
	ScriptLine_111015 = [=[唔……下次，可别再这么“不小心”了……]=],
	ScriptLine_111016 = [=[嘴上说着“没关系”，一眼望去尽是没完成的活儿。哼，指挥官果然令人放心不下……]=],
	ScriptLine_111017 = [=[回来了吗？能做的都帮你做了，剩下的可别偷懒啊。]=],
	ScriptLine_111018 = [=[集合队伍，准备出发。]=],
	ScriptLine_111019 = [=[集合队伍，准备出发。]=],
