	ScriptLine_113049 = [=[指挥官~]=],
	ScriptLine_113050 = [=[昆！]=],
	ScriptLine_113051 = [=[昆！]=],
	ScriptLine_113052 = [=[昆……昆昆昆昆！]=],
	ScriptLine_113053 = [=[昆……昆昆昆昆！]=],
	ScriptLine_113054 = [=[昆……唔……OVO]=],
	ScriptLine_113055 = [=[昆……唔……OVO]=],
	ScriptLine_113056 = [=[昆……唔……OVO]=],
	ScriptLine_113057 = [=[昆？？！！OVO]=],
	ScriptLine_113058 = [=[昆？？！！OVO]=],
	ScriptLine_113059 = [=[昆——！]=],
	ScriptLine_113060 = [=[昆——！]=],
	ScriptLine_113061 = [=[昆西是大家的偶像哦！]=],
	ScriptLine_113062 = [=[昆西是大家的偶像哦！]=],
	ScriptLine_113063 = [=[昆西不清楚~]=],
	ScriptLine_113064 = [=[昆西不清楚~]=],
	ScriptLine_113101 = [=[啊，发带！呼……幸好没掉下来，如果再打翻别的东西，昆西就打扫不完了——]=],
	ScriptLine_113102 = [=[指挥官在看哪里……？唔……低头看？——昆！？这、这里也沾上了吗？！啊啊啊啊，奶油要滑下去了！指挥官救我！！！]=],
	ScriptLine_113103 = [=[哦？指挥官很在意我的胸口吗？哼哼，昆西可是很懂的哦，这样穿能够治愈主人的心灵~“治愈的点是……？”，一定是那个啦！领口的花边很漂亮吧~？]=],
	ScriptLine_113104 = [=[丝袜也弄脏了……怎么办呀~指挥官主人肯定要狠狠惩罚糊涂的昆西女仆了~咦？不会惩罚吗？真的不会对昆西那个那个又那样那样吗！……唔，您不知道“那个”是什么吗？昆西也不知道诶……]=],
	ScriptLine_113105 = [=[昆西昆西卖力拖……嘿咻……咦？奇怪，地板怎么越拖越脏了？——呜啊啊啊！？蛋糕被涂开了！！！]=],
	ScriptLine_113106 = [=[指挥官的咖啡还没喝完……您还想喝吗？——嗯！等昆西打扫完，马上就为您沏一杯热乎乎的“昆西浓浓情谊咖啡”！]=],
	ScriptLine_113107 = [=[竟然到这个时间了！？呜……本来应该早早打扫完，给主人做一套全身的女仆贴心按摩来着……卫生怎么越做越多昆……]=],
	ScriptLine_113108 = [=[主人请放心吧！昆西已经确认过了，除了这里的地板，房间其他地方都打扫干净啦~……诶？桌、桌子上还有零食袋？奇怪……昆西刚才应该收起来了啊……（小声）]=],
	ScriptLine_113109 = [=[呜呜……昆西是不合格的笨蛋女仆，给您增加额外的工作量了……您会责怪昆西吗？不、不会吗？指挥官……您真是昆西最温柔的主人……]=],
	ScriptLine_113110 = [=[昆、昆西还能行……！这点困难，女仆昆西一下子就能解决！主人，请您看着吧！我马上还您一个焕然一新的房间！终极大扫除，开始——！]=],
	ScriptLine_114001 = [=[苍蓝避风港]=],
	ScriptLine_114002 = [=[在战场上要保持冷静，在生活中则要充满激情，你也是这么想的吧，指挥官。看来我们俩还挺投缘的。下次一起去玩高空跳伞怎么样？]=],
	ScriptLine_114003 = [=[虽然看电影要坐很久，能看到影片里公路上车辆撞来撞去还是值得的，毕竟海上没什么机会撞车嘛。那感觉一定很刺激！]=],
	ScriptLine_114004 = [=[敦刻尔克？{Action=1140102,Time=1}嗯哼……确实有时会忍不住逗弄她啦，不觉得她慌张的样子像小动物一样很有反差感吗……呵呵，看指挥官的表情，你也有同感对吧~]=],
	ScriptLine_114005 = [=[指挥官，能告诉我你的幸运色吗？我想着要是把这支箭染成你的幸运色，下次狙击的时候，命中率说不定会蹭蹭地涨呢！]=],
	ScriptLine_114006 = [=[指挥官，我不否认自己闯祸就应该受罚。但我们可是战舰少女，你不觉得这些用于写检讨的时间，放在战场上可以击败更多的敌人吗！要不这样——10个敌人换1页检讨……{Action=1140111,Time=14}10、15个也行！]=],
	ScriptLine_114007 = [=[呵呵，没想到我这风笛独奏，还蛮有模有样的吧？看到我不同以往的一面，是不是让你心跳加速了？]=],
	ScriptLine_114008 = [=[呵呵，你要是一直这样摸下去，可别怪我顺势抱住你，不放你走了。]=],
	ScriptLine_114009 = [=[指挥官，别总盯着文件看了，偶尔也抬头看着我呀。不然的话，你可要错过你最喜欢的笑容了！]=],
	ScriptLine_114010 = [=[胡德为了让我的举止更符合贵族礼仪，可真是操碎了心。且不说花了多长时间来纠正我的言行谈吐——{Action=1140112,Time=7}如今的话，只要我不弄得满身尘土，她就谢天谢地了。]=],
	ScriptLine_114011 = [=[指挥官，今晚工作结束后，要不要来我的房间小坐一下？这次我收拾过房间了，虽然可能还是有点小乱，但绝不会再让你被弓箭绊倒了！]=],
	ScriptLine_114012 = [=[啊（呵欠）……指挥官，我先躺沙发上打个盹儿。如果等会儿你也累了，不用叫醒我，就躺我身边吧。这样我们都暖和一些。]=],
	ScriptLine_114013 = [=[这就是被你“捕猎”的感觉吗？……挺刺激的，我还想再多试试……]=],
	ScriptLine_114014 = [=[徒步冒险的时候，如果中途再加入林间攀岩和悬崖跳水……嗯嗯，这样既能放松心情，又能体验到让人心跳加速的极限挑战，真是一箭双雕！]=],
	ScriptLine_114015 = [=[呀~指挥官，你来得正好！我正筹划一场属于我们两人的野外冒险呢。你一定会喜欢的。]=],
	ScriptLine_114016 = [=[各位，狩猎时刻到啦。大家都准备好跟我一起冲锋吧！]=],
	ScriptLine_114017 = [=[今天的猎物，躲在哪儿呢？]=],
	ScriptLine_114018 = [=[今天的猎物，躲在哪儿呢？]=],
	ScriptLine_114019 = [=[哼，这下我可兴奋起来了。]=],
	ScriptLine_114020 = [=[哼，这下我可兴奋起来了。]=],
	ScriptLine_114021 = [=[咕，还没有结束，我……还没，尽兴……]=],
	ScriptLine_114022 = [=[一击即中！哈哈，你的破绽实在太多了。]=],
	ScriptLine_114023 = [=[一击即中！哈哈，你的破绽实在太多了。]=],
	ScriptLine_114024 = [=[敌军的增援来了？呵呵，猎物越多，我的兴致就越旺！]=],
	ScriptLine_114025 = [=[不管你如何挣扎，也别想逃离猎人的双眼。]=],
	ScriptLine_114026 = [=[不管你如何挣扎，也别想逃离猎人的双眼。]=],
	ScriptLine_114027 = [=[乖乖的别乱动哦。]=],
	ScriptLine_114028 = [=[乖乖的别乱动哦。]=],
	ScriptLine_114029 = [=[呵呵……见识一下我的围猎技巧吧~]=],
	ScriptLine_114030 = [=[呵呵……见识一下我的围猎技巧吧~]=],
	ScriptLine_114031 = [=[真是一场刺激又过瘾的狩猎！这样的胜利，可算得上是最完美的结果吧！]=],
	ScriptLine_114032 = [=[还真是个难缠的猎物啊，不过到头来，还是我的本事更胜一筹！]=],
	ScriptLine_114033 = [=[你好~皇家方舟正式向你报到，我可是满怀期待地一路赶来哦。这里就是避风港吗？感觉比想象中更宽广、更热闹呢！我已经忍不住想绕港跑一圈啦！]=],
	ScriptLine_114034 = [=[狩猎深海的事尽管交给我吧！只要我踏足海域，就必定为你带来胜利！]=],
	ScriptLine_114035 = [=[哦~弓弦的声音变得清脆了许多！]=],
	ScriptLine_114036 = [=[呼……我的心都快跳出来了。真没想到，自诩为猎人的我，在你面前也会变得这么紧张，就像一只害羞的小猎物。呵呵，从今往后，我会用满腔热情注视着你，永远陪伴在你左右。]=],
	ScriptLine_114037 = [=[嗯？]=],
	ScriptLine_114038 = [=[嗯？]=],
	ScriptLine_114039 = [=[嗯？]=],
	ScriptLine_114040 = [=[那当然。]=],
