	ScriptLine_115001 = [=[苍蓝避风港]=],
	ScriptLine_115002 = [=[指挥官，下次一起去郊游吧？不用带太多东西，只要有好天气、好心情，还有您，就足够啦！]=],
	ScriptLine_115003 = [=[好想抱着软乎乎的小猫睡午觉啊……一定超级舒服！不过，抱着上游一号也很舒服！]=],
	ScriptLine_115004 = [=[有句话怎么说的来着？“流汗是女孩子的天敌”？不不不！对我来说，“训练不够才是天敌”！]=],
	ScriptLine_115005 = [=[逸仙前辈总觉得我长不大，其实我已经经历不少风雨了。现在的我，绝对不同以往！]=],
	ScriptLine_115006 = [=[夜晚的海风有点凉呢……指挥官，咱们靠近点好不好？{Action=1150102,Time=5}诶嘿！这样会暖和一点！]=],
	ScriptLine_115007 = [=[指挥官，帮我捏捏肩膀嘛！今天训练有点太拼了……嘿嘿，不行的话，那我就靠着您休息一会儿好了！]=],
	ScriptLine_115008 = [=[指挥官……您、您这样太狡猾了……人家还没准备好……]=],
	ScriptLine_115009 = [=[阳光晒得暖暖的，真舒服……啊，不是我在偷懒哦！只是偶尔也要享受一下悠闲的时光嘛，指挥官也来一起坐坐吧？]=],
	ScriptLine_115010 = [=[想当初我第一次吃煎饼果子，那可真是辣得痛快，香得上头！是足以载入我人生史册的伟大事件！]=],
	ScriptLine_115011 = [=[指挥官……您还没睡啊？嘿嘿，我也睡不着。要不，我们……再靠近一点说话吧？声音小小的，就只有我们能听见的那种。]=],
	ScriptLine_115012 = [=[指挥官，要是我们能在森林里搭个帐篷，看星星、听虫鸣，然后窝在一起取暖就好了……{Action=1150102,Time=9}诶？您的脸怎么红了？]=],
	ScriptLine_115013 = [=[……诶嘿嘿，指挥官，抱紧一点也可以哦。]=],
	ScriptLine_115014 = [=[要是指挥室里能养熊猫就好了，我可以每天陪它玩，看它滚来滚去，开开心心抱着竹子啃！说不定还能带着它去郊游呢……啊啊，光是想想就觉得好幸福！]=],
	ScriptLine_115015 = [=[指挥官，您觉得呢？咱们是不是该去申请一下？写个超级有说服力的申请书！您说，咱们从哪个角度开始忽悠比较好呢？]=],
	ScriptLine_115016 = [=[各系统检查完毕，战斗准备就绪！各舰，听我指挥！]=],
	ScriptLine_115017 = [=[嘿，可要好好表现一下！]=],
	ScriptLine_115018 = [=[嘿，可要好好表现一下！]=],
	ScriptLine_115019 = [=[可恶，看我加倍奉还！]=],
	ScriptLine_115020 = [=[可恶，看我加倍奉还！]=],
	ScriptLine_115021 = [=[呜……还是太脆了……之后就交给大家了……]=],
	ScriptLine_115022 = [=[呜……还是太脆了……之后就交给大家了……]=],
	ScriptLine_115023 = [=[一击必中！完美解决！]=],
	ScriptLine_115024 = [=[一击必中！完美解决！]=],
	ScriptLine_115025 = [=[是敌人的增援……看来敌人还真是看得起我们呢！]=],
	ScriptLine_115026 = [=[是敌人的增援……看来敌人还真是看得起我们呢！]=],
	ScriptLine_115027 = [=[迎风而行，逆浪而上！]=],
	ScriptLine_115028 = [=[迎风而行，逆浪而上！]=],
	ScriptLine_115029 = [=[目标锁定，走你！]=],
	ScriptLine_115030 = [=[目标锁定，走你！]=],
	ScriptLine_115031 = [=[目标锁定，同志，我们上吧！]=],
	ScriptLine_115032 = [=[目标锁定，同志，我们上吧！]=],
	ScriptLine_115033 = [=[耶！完美胜利！看吧，我就说过没问题！]=],
	ScriptLine_115034 = [=[胜利不容易，但我们做到了……感谢大家的努力。]=],
	ScriptLine_115035 = [=[鞍山级驱逐舰三号舰，长春前来报到！嘿嘿，终于见到您了，指挥官！以后咱们可是同志哦！]=],
	ScriptLine_115036 = [=[我有十足的信心迎接任何挑战！有我在，胜利不再遥远！]=],
	ScriptLine_115037 = [=[百·尺·竿·头！嘿嘿，准备好迎接全新的长春了吗？]=],
	ScriptLine_115038 = [=[和您在一起的每一刻，我都觉得好开心！无论未来多么艰难，我都会紧紧握住您的手，一起迎接每一个挑战，直到我们的梦想实现！]=],
