	ScriptLine_115057 = [=[怎么会这样？！]=],
	ScriptLine_115058 = [=[怎么会这样？！]=],
	ScriptLine_115059 = [=[该好好惩罚坏家伙了！]=],
	ScriptLine_115060 = [=[该好好惩罚坏家伙了！]=],
