	ScriptLine_116001 = [=[苍蓝避风港]=],
	ScriptLine_116002 = [=[作战计划的具体部署工作就交给我来安排吧，身为性能优秀的驱逐舰，我一定不辱使命。]=],
	ScriptLine_116003 = [=[早上好啊，指挥官~正好一会儿我打算去给妹妹们准备早餐，您也来一起吃吧~您更喜欢松饼还是煎培根呢？]=],
	ScriptLine_116004 = [=[呼……今天的事务终于都处理完了。{Action=1160102,Time=4}虽然忙碌了整整一天，但完成时的成就感很让人满足呢。]=],
	ScriptLine_116005 = [=[身为姐姐要考虑的事情非常多，妹妹们的起居作息、饮食健康、战斗训练都是我时刻牵挂的事……{Action=1160118,Time=11}等一下，奥班农要的新枕头是不是还没到货？]=],
	ScriptLine_116006 = [=[喵呀？！{Action=1160117,Time=1}什么什么？雨衣贴在身上了……？]=],
	ScriptLine_116007 = [=[我想……作为需要时刻关照大家的长姐，我一定是最能感同身受指挥官平日操劳的心情的人——{Action=1160102,Time=8}放心吧，我会和您一起分担这份重任。]=],
	ScriptLine_116008 = [=[我最近发现睡前按摩可以有效解压！指挥官要不要尝试一下？来嘛来嘛，保证让您舒服~]=],
	ScriptLine_116009 = [=[指、指挥官？！您怎么……在这种地方……下次能选个隐蔽点的地方吗……？]=],
	ScriptLine_116010 = [=[指挥官已经睡着了吗？{Action=1160103,Time=3}真是的……总是这么让人操心呢。{Action=1160102,Time=7}剩下的工作就让我来完成吧，嘿嘿。]=],
	ScriptLine_116011 = [=[原来您醒着啊……刚才的话都被听到了吗？{Action=1160107,Time=5}唔，至少应一声嘛……]=],
	ScriptLine_116012 = [=[大家，保持阵型！决不能放过任何一个敌人！]=],
	ScriptLine_116013 = [=[指挥官，请下达指示。]=],
	ScriptLine_116014 = [=[唔……！小伤而已……]=],
	ScriptLine_116015 = [=[抱歉，指挥官……辜负了您的信任……]=],
	ScriptLine_116016 = [=[确认命中！已对敌人产生有效打击——很好！]=],
	ScriptLine_116017 = [=[发现敌人的支援部队！大家，千万不要慌乱！]=],
	ScriptLine_116018 = [=[这就是我们的力量！]=],
	ScriptLine_116019 = [=[就是这里——看招！]=],
	ScriptLine_116020 = [=[就是这里——看招！]=],
	ScriptLine_116021 = [=[再坚持一下……！]=],
	ScriptLine_116022 = [=[再坚持一下……！]=],
	ScriptLine_116023 = [=[收获满满~回去以后可以和妹妹们好好分享战果呢！]=],
	ScriptLine_116024 = [=[这次的作战成果差强人意，今后我还会再努力一点。]=],
	ScriptLine_116025 = [=[DD-445前来报道，身为弗莱彻级驱逐舰的长姐，我会全力辅佐您完成此次作战任务。]=],
	ScriptLine_116026 = [=[指挥官，我“嗅”到了危险的气息，需要即刻出阵吗？]=],
	ScriptLine_116027 = [=[能力越大，责任越大。]=],
	ScriptLine_116028 = [=[我时常会想，自己作为大家的姐姐是否有完美尽到责任，这种焦虑和不安时刻紧压着我的内心。只有在指挥官这边，我的压力才能得到缓解……这样是不是太任性呢？我可以再依赖您一点吗~]=],
	ScriptLine_116029 = [=[是这样吗？]=],
