	ScriptLine_116063 = [=[真想休息一下啊……]=],
	ScriptLine_117001 = [=[苍蓝避风港]=],
	ScriptLine_117002 = [=[指挥官很在意拉菲的拳套吗？嘿嘿，看起来就很厉害对吧！有了这个，拉菲就不会输给任何人啦！]=],
	ScriptLine_117003 = [=[今天天气真好！指挥官，要跟拉菲赛跑吗！]=],
	ScriptLine_117004 = [=[训练之后就要吃甜食！这是拉菲很喜欢的蜂蜜口味坚果！指挥官也来尝尝吧！啊～]=],
	ScriptLine_117005 = [=[跑了一整个白天，总觉得肚子有些饿了。{Action=1170115,Time=3}指挥官，您有糖吗，拉菲想吃糖！]=],
	ScriptLine_117006 = [=[Zzz……{Action=1170108,Time=2}哈！？{Action=1170107,Time=3}没、没睡！拉菲没打瞌睡喔！]=],
	ScriptLine_117007 = [=[啊，是指挥官，真巧！这么晚还能见到指挥官，看来明天也会是幸运的一天！当然指挥官也会一样幸运的！]=],
	ScriptLine_117008 = [=[明明都没训练，身体却感觉暖暖的……还挺舒服的。]=],
	ScriptLine_117009 = [=[精神饱满的秘诀？那当然是大口吃饭，努力训练，还有每天都看到指挥官的脸！]=],
	ScriptLine_117010 = [=[最近每次看到指挥官，拉菲都觉得心里暖暖的，仿佛有使不完的劲！指挥官是不是也跟拉菲一样啊！]=],
	ScriptLine_117011 = [=[休息也是训练的一环！这么简单的道理拉菲当然懂啦！{Action=1170115,Time=5}嘿嘿，拉菲最近已经不会在夜里绕着港区跑圈了！]=],
	ScriptLine_117012 = [=[拉菲喜欢吃零食，特别是甜甜的糖果！而且啊，拉菲看到别人开开心心吃糖果，也会觉得很开心！]=],
	ScriptLine_117013 = [=[呜呜……指挥官，您怎么老是戳拉菲的……这里？虽然也不讨厌就是了……]=],
	ScriptLine_117014 = [=[指挥官，指挥官？您怎么一直不说话呢？您听得到拉菲说话吗！——该不会是睡着了吧？]=],
	ScriptLine_117015 = [=[哇呀——！指挥官您装睡吓唬人……{Action=1170114,Time=3}哈哈哈，指挥官，您这个鬼脸好好笑啊！]=],
	ScriptLine_117016 = [=[发、发现敌军！就算是指挥战斗，拉菲也不会输给前辈们的！]=],
	ScriptLine_117017 = [=[拉菲，不会辜负前辈的名号！]=],
	ScriptLine_117018 = [=[咕……！Never abandon！]=],
	ScriptLine_117019 = [=[训练的成果……没发挥出来……]=],
	ScriptLine_117020 = [=[太棒了！就跟训练时一样！]=],
	ScriptLine_117021 = [=[太棒了！就跟训练时一样！]=],
	ScriptLine_117022 = [=[增、增援！？呜，拉菲是不会输的！]=],
	ScriptLine_117023 = [=[拉菲决不退缩，决不！]=],
	ScriptLine_117024 = [=[拉菲决不退缩，决不！]=],
	ScriptLine_117025 = [=[Fire!]=],
	ScriptLine_117026 = [=[Fire!]=],
	ScriptLine_117027 = [=[后援行动，开始！]=],
	ScriptLine_117028 = [=[后援行动，开始！]=],
	ScriptLine_117029 = [=[哇哈哈，拉菲是最厉害的！]=],
	ScriptLine_117030 = [=[下次，拉菲会做得更好！]=],
	ScriptLine_117031 = [=[艾伦·萨姆纳级驱逐舰拉菲，为了指挥官，赴汤蹈火在所不辞！准备出击！——诶，拉菲太心急了？诶嘿嘿～]=],
	ScriptLine_117032 = [=[拉菲要更多、更多地训练，为指挥官派上用场！这样才不会辱没这个继承自前辈的伟大名字！]=],
	ScriptLine_117033 = [=[不管是谁都放马过来吧！拉菲是不会输的！]=],
	ScriptLine_117034 = [=[指挥官也喜欢拉菲吗？太开心了！但是港区还有那么多孩子……不，既然指挥官选了拉菲，那拉菲也要全力成为指挥官心中的第一名！]=],
