	ScriptLine_119001 = [=[苍蓝避风港]=],
	ScriptLine_119002 = [=[我已经是成熟的大人了，指挥官，你可以再多多依靠我哦！]=],
	ScriptLine_119003 = [=[指挥官是想问，成熟的大人为什么还要背小学双肩包？{Action=1190102,Time=6}这是我的个性，也就是魅力点啦！]=],
	ScriptLine_119004 = [=[指挥官，加班辛苦了，这是我给你准备的夜宵！——怎么样，就算是夜晚的工作，我也游刃有余！]=],
	ScriptLine_119005 = [=[即便是在姐妹们看不到的地方，也要好好努力……这样才算是成熟的大人。]=],
	ScriptLine_119006 = [=[成长后的我，是不是充满了大人的魅力啊？嘿嘿，谢谢指挥官的夸奖！{Action=1190113,Time=7}——不对，不要对成熟的大人摸头啦！虽然我不讨厌这样……]=],
	ScriptLine_119007 = [=[嗯（注视）……下在这里！{Action=1190114,Time=4}——啊~看错棋子啦！又输给指挥官了……那个，五子棋真的能提高布置水雷的精度吗？]=],
	ScriptLine_119008 = [=[不、不行啦！（咽口水）书上说保持魅力的诀窍是控制夜间饮食……你是说，成熟的大人不会浪费食物？{Action=1190102,Time=12}……对、对啊！就是说，我吃完这盘烤香肠，才显得成熟，对吧！]=],
	ScriptLine_119009 = [=[我的目标是成长为希佩尔姐姐那样的身材。{Action=1190107,Time=4}……诶，你是说，现在的我抱起来的手感很舒适？……可是……嗯……（烦恼）]=],
	ScriptLine_119010 = [=[芙蕾德莉卡呀，来到避风港呀，每天都会布置很多可爱的水雷，今天五十枚呀，明天五十枚呀，后天还会布置很多可爱的水雷!]=],
	ScriptLine_119011 = [=[指挥官，你等会儿要来看我的水雷战术演练吗？好耶，今天我就加把劲，布置一百枚水雷吧！]=],
	ScriptLine_119012 = [=[好耶！准备完毕，随时可以出击！]=],
	ScriptLine_119013 = [=[收到命令，交给我吧！]=],
	ScriptLine_119014 = [=[呀！？]=],
	ScriptLine_119015 = [=[呀！？]=],
	ScriptLine_119016 = [=[呀！？]=],
	ScriptLine_119017 = [=[要是没被……包围的话……]=],
	ScriptLine_119018 = [=[知道水雷的厉害了吧！]=],
	ScriptLine_119019 = [=[知道水雷的厉害了吧！]=],
	ScriptLine_119020 = [=[新敌人？嘿嘿，就怕你们不来呢。]=],
	ScriptLine_119021 = [=[新敌人？嘿嘿，就怕你们不来呢。]=],
	ScriptLine_119022 = [=[接招吧，半径两百米的水雷包围网！]=],
	ScriptLine_119023 = [=[接招吧，半径两百米的水雷包围网！]=],
	ScriptLine_119024 = [=[你们的举动我了如指掌！]=],
	ScriptLine_119025 = [=[你们的举动我了如指掌！]=],
	ScriptLine_119026 = [=[该到我好好表现的时候了！]=],
	ScriptLine_119027 = [=[作为成熟的大人，这是理所当然的成果！]=],
	ScriptLine_119028 = [=[作为成熟的大人，这是理所当然的成果！]=],
	ScriptLine_119029 = [=[呜，感觉有点累了……]=],
	ScriptLine_119030 = [=[1934A系列11号舰，弗雷德里克报道！指挥官，请继续叫我芙蕾德莉卡吧！]=],
	ScriptLine_119031 = [=[哼哼，我已经是成熟的大人了！这样就领先姐妹们一步了吧！]=],
	ScriptLine_119032 = [=[我要变得更强，才能做好姐妹们的榜样！这是成熟大人的义务！]=],
	ScriptLine_119033 = [=[指挥官，您终于注意到我的成熟魅力啦！我好开心！从现在开始，我一定会更加努力，让指挥官更加、更加地喜欢我！]=],
