	ScriptLine_119071 = [=[这就是淑女的魅力~]=],
	ScriptLine_120001 = [=[苍蓝避风港]=],
	ScriptLine_120002 = [=[我担任过一段时间的教官，算是一次失败的尝试。我不懂该怎么“宽慰”学员，也不会在她们有所进步后给予鼓励。所以，她们给我取了“铁面”这个绰号。]=],
	ScriptLine_120003 = [=[看您很有精神的样子，干脆把体测挪到今天吧。还是老样子，谁先拿到对方脖子上的丝巾就算赢。三局两胜，我在演习场等您。]=],
	ScriptLine_120004 = [=[即便放到现在，大多数人也依旧觉得我和胡德是仇敌。而事实上，我们是可以放心托付后背的同伴。“化干戈为玉帛”——难道不好吗？和人钩心斗角，实在不是我的作风。]=],
	ScriptLine_120005 = [=[“成功”不在于你取得了什么成就，即便这次挑战以世俗的“失败”告终，你也可以昂首离开，消化此次经历，等待时机再度发起挑战——“勇气”，才是贯穿人生始终的奠基石。]=],
	ScriptLine_120006 = [=[我能感受到…您快要坐不住了。这“耳朵”可不是单纯的装饰，往夸张了说，百米之外有颗钉子掉到地上我都能听到。所以，您接下来打算做什么？算我一个。]=],
	ScriptLine_120007 = [=[有些特质，不会随着时间而改变。好比您在这里加班，有人却在房里打游戏。只要不耽误正事，我也没法说她什么。至少，她的玩伴是越来越多了。这也是一种成长，我很欣慰。]=],
	ScriptLine_120008 = [=[您的目的……是什么？]=],
	ScriptLine_120009 = [=[这件大衣是定制的，您要是喜欢，我可以帮您搭个线。]=],
	ScriptLine_120010 = [=[耳朵没有触……噫！？什么时候加上的！？]=],
	ScriptLine_120011 = [=[利爪，是用来撕碎猎物的。对您，它们是无害的。]=],
	ScriptLine_120012 = [=[这下…事情变得有趣了。]=],
	ScriptLine_120013 = [=[我该把这看作“试探”，还是“邀请”？]=],
	ScriptLine_120014 = [=[您走神了吗？我想，这说不定是身体给您释放的“需要休息”的信号。闭上眼睛，打个盹……别太拼了，多为自己考虑一下。]=],
	ScriptLine_120015 = [=[好吧……看来您也是不听劝的类型。也许，我该用上一些物理手段了。]=],
	ScriptLine_120016 = [=[就该这么做。]=],
	ScriptLine_120017 = [=[就该这么做。]=],
	ScriptLine_120018 = [=[你们逃不掉了。]=],
	ScriptLine_120019 = [=[你们逃不掉了。]=],
	ScriptLine_120020 = [=[哼，有点意思。]=],
	ScriptLine_120021 = [=[哼，有点意思。]=],
	ScriptLine_120022 = [=[这……不可能！]=],
	ScriptLine_120023 = [=[这……不可能！]=],
	ScriptLine_120024 = [=[该说再见了。]=],
	ScriptLine_120025 = [=[该说再见了。]=],
	ScriptLine_120026 = [=[来再多，结局也不会改变。]=],
	ScriptLine_120027 = [=[来再多，结局也不会改变。]=],
	ScriptLine_120028 = [=[你的结局，由我来决定。]=],
	ScriptLine_120029 = [=[你的结局，由我来决定。]=],
	ScriptLine_120030 = [=[退下吧，弱者。]=],
	ScriptLine_120031 = [=[退下吧，弱者。]=],
	ScriptLine_120032 = [=[把握好机会。]=],
	ScriptLine_120033 = [=[把握好机会。]=],
	ScriptLine_120034 = [=[不错的挑战，我们继续吧。]=],
	ScriptLine_120035 = [=[稍微活动下筋骨也不错。]=],
	ScriptLine_120036 = [=[我是俾斯麦，自我介绍的环节就到这里吧。说的太多，反倒显得生疏了。长官，我们的下一个目标是？]=],
	ScriptLine_120037 = [=[还等什么呢？该战斗了，长官。]=],
	ScriptLine_120038 = [=[追求力量的道路，永无止境。]=],
	ScriptLine_120039 = [=[爱情就像一团烈火，极具侵略性。一旦被其俘获，就再也不能脱身了。我们甘愿成为爱情的俘虏，不是吗？]=],
	ScriptLine_120040 = [=[是吗？]=],
	ScriptLine_120041 = [=[是吗？]=],
	ScriptLine_120042 = [=[好。]=],
	ScriptLine_120043 = [=[好。]=],
	ScriptLine_120044 = [=[哼～～]=],
	ScriptLine_120045 = [=[哼～～]=],
	ScriptLine_120046 = [=[我……]=],
	ScriptLine_120047 = [=[我……]=],
	ScriptLine_120048 = [=[哦？]=],
	ScriptLine_120049 = [=[哦？]=],
	ScriptLine_120050 = [=[指挥官。]=],
	ScriptLine_120051 = [=[指挥官。]=],
	ScriptLine_120052 = [=[不行。]=],
	ScriptLine_120053 = [=[不行。]=],
	ScriptLine_120054 = [=[噫。]=],
	ScriptLine_120055 = [=[噫。]=],
	ScriptLine_120056 = [=[这……]=],
	ScriptLine_120057 = [=[真有你的。]=],
	ScriptLine_120058 = [=[有趣。]=],
	ScriptLine_120059 = [=[有趣。]=],
	ScriptLine_120060 = [=[好啊。]=],
	ScriptLine_120061 = [=[好啊——！]=],
	ScriptLine_120062 = [=[别后悔。]=],
	ScriptLine_120063 = [=[可笑。]=],
	ScriptLine_120101 = [=[你可真闹腾，奥斯卡。没看见我们睡得正香吗？啊……（哈欠）帮我开一下这个，谢谢您了。]=],
	ScriptLine_120102 = [=[简单一点，跟往常一样。再复杂的我也不会做。好了，您先去洗把脸，这里有我。]=],
	ScriptLine_120103 = [=[您要接手啊，那好～我到旁边观摩，顺便也模仿一下您刚才的那些小动作。看看您又能坚持多久。]=],
	ScriptLine_120104 = [=[（眯眼）我的精神可没你那么好，奥斯卡……啊！好险！差点就煎煳了……]=],
	ScriptLine_120105 = [=[呜喵——！？您突然干什么呢！？奥斯卡，帮我回敬一下他！我给你双份的罐头！]=],
	ScriptLine_120106 = [=[——您回来了。会玩这种恶作剧的，也只有您了。呵呵，下次我努力显得更惊讶一些。]=],
	ScriptLine_120107 = [=[咳咳……！奥斯卡还在呢。您要是真闲得没事做，就帮它把罐头打开。]=],
	ScriptLine_120108 = [=[看看……她还挺关心我们的，说是食材都在冰箱里了。我们是不是也该回报一下她了？]=],
	ScriptLine_120109 = [=[现在是几点了？奥斯卡，你真会折磨人。您也说它两句，它把我的话都当耳旁风，说不定您的话它会听呢。]=],
	ScriptLine_120110 = [=[谢谢您，吐司的焦脆度刚刚好。对了，牛奶在冰箱里，帮我拿一下。一大早可不能喝冰的，对您的肠胃不好。]=],
	ScriptLine_121001 = [=[苍蓝避风港]=],
	ScriptLine_121002 = [=[今天我的惊喜清单上，有条“发现港区小惊喜”的目标。指挥官，不如我们一起去外面逛逛，看能不能巧遇一只可爱的小猫吧~]=],
	ScriptLine_121003 = [=[指挥官，你刚刚达成了一条额外惊喜喔。惊喜积分+5！要不要试试手气？说不定能抽到“甘比尔湾的特别笑容”哦？]=],
	ScriptLine_121004 = [=[港区也安静下来了呢……指挥官，有没有觉得，现在特别适合用积分兑换一瓶精心酿造的果饮，让它为我们带来一个温暖而甜美的夜晚？]=],
	ScriptLine_121005 = [=[虽然安静的夜晚也不错，但我还是更喜欢被烟火点亮的热闹夜空。纵使只有刹那芳华，最美的姿态也将永远定格在我们心中，对吧？]=],
	ScriptLine_121006 = [=[啊，指挥官！？这个惊喜有点……太突然了吧？不过我喜欢，嘻嘻~]=],
	ScriptLine_121007 = [=[指挥官，跟你在一起，我总能发现之前没注意到的小惊喜。你就像我的幸运雷达一样呢。嘻嘻，所以，接下来我也要一直紧紧跟着你，不许放开我哦！]=],
	ScriptLine_121008 = [=[指挥官，夜空中这些闪亮的星星，像不像我们一点一滴积累的惊喜积分？而你……就是我最想兑换的那个永恒的奖品哦。嘿嘿，你懂的吧？]=],
	ScriptLine_121009 = [=[指挥官，你解锁了我最秘密的惊喜呢……不过这个奖品，只有私下的时候才能给你哦……]=],
	ScriptLine_121010 = [=[嗯——指挥官到底藏到哪里去了啊？今天就差“与指挥官的惊喜相遇”还没达成了……指挥官~你快出来吧~]=],
	ScriptLine_121011 = [=[哇，发现指挥官啦！恭喜你，你刚刚获得了10点惊喜积分哦。你问可以抽到什么奖品？嘿嘿，我推荐……一个最棒的惊喜拥抱哦！]=],
	ScriptLine_121012 = [=[大家都准备好了吗？今天的惊喜目标是——赢得一场最棒的胜利！]=],
	ScriptLine_121013 = [=[耶~~！]=],
	ScriptLine_121014 = [=[耶~~！]=],
	ScriptLine_121015 = [=[呀！]=],
	ScriptLine_121016 = [=[呀！]=],
	ScriptLine_121017 = [=[呜……这份惊喜，没法和大家一起完成吗……]=],
	ScriptLine_121018 = [=[真棒！惊喜积分+100哦！]=],
	ScriptLine_121019 = [=[敌人的援军来了吗？这可是达成额外惊喜奖励的幸运机会~]=],
	ScriptLine_121020 = [=[看，这是最美的惊喜！]=],
	ScriptLine_121021 = [=[看，这是最美的惊喜！]=],
	ScriptLine_121022 = [=[拿好你的奖励吧~]=],
	ScriptLine_121023 = [=[拿好你的奖励吧~]=],
	ScriptLine_121024 = [=[试试你的手气吧~]=],
	ScriptLine_121025 = [=[试试你的手气吧~]=],
	ScriptLine_121026 = [=[锵锵，惊喜清单完美达成！丰厚的奖赏在等着大家哦！]=],
	ScriptLine_121027 = [=[大家平安无事就好。下次，我们会赢得更棒的惊喜！]=],
	ScriptLine_121028 = [=[指挥官，今天的特别惊喜，就是与甘比尔湾的相遇啦。我特地为你准备了……锵锵，1000点惊喜积分！要不要试试我推荐的奖品？那就是，与我一起开启新的惊喜生活哦！]=],
	ScriptLine_121029 = [=[嘿嘿，和指挥官在一起，就是最棒的终极奖励。接下来无论是怎样的挑战，我都会为你，为同伴，赢下所有的惊喜哦！]=],
	ScriptLine_121030 = [=[惊喜升级！甘比尔湾无所不能！]=],
	ScriptLine_121031 = [=[指挥官，和你在一起的每一天，都像拆开一份全新的惊喜奖励。我对你的爱也像积分一样不断加深累积。如果能够与你永远相伴，我的人生旅途，一定永远都会惊喜不断，奖励不断。指挥官，你愿意兑换“甘比尔湾”这个最最浪漫的“终极大奖”吗？]=],
	ScriptLine_121032 = [=[嗯……？]=],
	ScriptLine_121033 = [=[嗯……？]=],
	ScriptLine_121034 = [=[交给我吧！]=],
	ScriptLine_121035 = [=[交给我吧！]=],
