	ScriptLine_121052 = [=[真是的！]=],
	ScriptLine_121053 = [=[真是的！]=],
	ScriptLine_121054 = [=[积分来啦！]=],
	ScriptLine_121055 = [=[积分来啦！]=],
	ScriptLine_121056 = [=[锵锵！]=],
	ScriptLine_121057 = [=[锵锵！]=],
	ScriptLine_122001 = [=[苍蓝避风港]=],
	ScriptLine_122002 = [=[新来的那批孩子们进步很快，基础操演已经像模像样了，再过不久，应该就能开始实战演练了吧……呵，看来我的教导，还是有些成效的。]=],
	ScriptLine_122003 = [=[指挥官，您午餐准备用些什么？若是还没决定的话，不如跟我一起试试金枪鱼寿司套餐？听说今天的金枪鱼是上等货色，错过就可惜了。]=],
	ScriptLine_122004 = [=[很好奇为什么我喜欢挑战强者，是吗？因为这可以让我认识自己的弱小。认识到弱小之后，人才能变得温柔与坚强。]=],
	ScriptLine_122005 = [=[今晚的港区，总感觉空荡荡的，是错觉吗？……对了，是少了那孩子咋咋呼呼的声音吧。{Action=1220102,Time=10}真是的，明明平时那么吵闹，突然安静下来，还真让人有些……不习惯，呵呵。]=],
	ScriptLine_122006 = [=[“工作是永远做不完的，但身体可是会累垮的。”呵呵，忽然想起曾几何时您对我说过这话呢。{Action=1220110,Time=9}所以，您现在不会介意让我来分担一些吧？]=],
	ScriptLine_122007 = [=[独自打谱虽能精进棋艺，但终究少了些趣味。难得今晚兴致颇佳，指挥官，可以请您陪我对弈一局吗？]=],
	ScriptLine_122008 = [=[指挥官……您真是……越来越放肆了呢……不过，嗯……]=],
	ScriptLine_122009 = [=[指挥官，今天天气很好，阳光也格外温暖……唔，我们要不要久违地去野外走走？嗯，就我们两个人。]=],
	ScriptLine_122010 = [=[您在为下一次作战的方案烦恼吗？{Action=1220102,Time=2}……不，我并不担心，以您的实力，这样的作战想必不在话下。我想说的是，BIG SEVEN的力量，随时为您待命。]=],
	ScriptLine_122011 = [=[这么晚了，您还在加班……至少让我为您准备宵夜……呵呵，不用担心，所谓士别三日，海苔饭团已经难不倒我了。]=],
	ScriptLine_122012 = [=[指挥官，不知不觉，我们已经在一起这么久了……呵呵……时间过得真快啊……不过，往后还有更漫长的岁月。您说……我们会一直这样……在一起吗？]=],
	ScriptLine_122013 = [=[唔……这样……稍微有些痒……但、但是……感觉……也并不讨厌……]=],
	ScriptLine_122014 = [=[新战线的补给线搭建……方案一稳妥但效率稍慢，方案二风险较高但响应速度更快，方案三风险与收益并存，但是弹性不够……唔唔……]=],
	ScriptLine_122015 = [=[指挥官，您来了啊。有关新战线补给线的方案，我正在整理思路……{Action=1220110,Time=6}呵呵，放心吧，问题越是棘手，越能激起我的斗志。我一定能想出万全之策。]=],
	ScriptLine_122016 = [=[诸位，拿出你们的全部实力，不要辜负了海军的荣耀，还有指挥官的期待——全舰队，准备战斗！]=],
	ScriptLine_122017 = [=[收到指令。接下来就交给我吧。]=],
	ScriptLine_122018 = [=[收到指令。接下来就交给我吧。]=],
	ScriptLine_122019 = [=[唔……有点能耐，但也仅此而已！]=],
	ScriptLine_122020 = [=[唔……有点能耐，但也仅此而已！]=],
	ScriptLine_122021 = [=[抱歉了……指挥官……辜负了您的信任……]=],
	ScriptLine_122022 = [=[哼，不是我的对手。]=],
	ScriptLine_122023 = [=[哼，不是我的对手。]=],
	ScriptLine_122024 = [=[新的敌人吗？看来她们还不死心。也好，就彻底击溃她们的意志吧！]=],
	ScriptLine_122025 = [=[新的敌人吗？看来她们还不死心。也好，就彻底击溃她们的意志吧！]=],
	ScriptLine_122026 = [=[以最强的力量，开拓出道路！]=],
	ScriptLine_122027 = [=[以最强的力量，开拓出道路！]=],
	ScriptLine_122028 = [=[开炮！]=],
	ScriptLine_122029 = [=[开炮！]=],
	ScriptLine_122030 = [=[这是必要的支援……！]=],
	ScriptLine_122031 = [=[这是必要的支援……！]=],
	ScriptLine_122032 = [=[这是一场精彩的胜利！诸位，我为你们感到骄傲！]=],
	ScriptLine_122033 = [=[这是一场精彩的胜利！诸位，我为你们感到骄傲！]=],
	ScriptLine_122034 = [=[诸位，动作还是有点僵硬。切记，任何情况下都不能疏忽大意。]=],
	ScriptLine_122035 = [=[诸位，动作还是有点僵硬。切记，任何情况下都不能疏忽大意。]=],
	ScriptLine_122036 = [=[曾沐浴无数战火，亦曾见证时代变迁。唯有与您的约定，历久弥坚。BIG SEVEN——战列舰长门，如约而至。为您的意志而战，是我的无上荣耀。]=],
	ScriptLine_122037 = [=[无需赘言，这份身躯与荣耀将为您所用。让我们并肩作战，直至胜利来临的那一天。]=],
	ScriptLine_122038 = [=[现在的我，定能更好地回应您的期待。]=],
	ScriptLine_122039 = [=[指挥官，您知道吗？最近，每每想起您，我心中都会涌起一股难以言喻的暖意。而这股暖意，随着时间流逝，只会愈发浓烈而深沉……呵呵，您当然知道了，因为我相信，您也有着和我相同的心情。]=],
	ScriptLine_122040 = [=[难道……？]=],
	ScriptLine_122041 = [=[难道……？]=],
	ScriptLine_122042 = [=[啊。]=],
	ScriptLine_122043 = [=[啊。]=],
	ScriptLine_122044 = [=[呵呵。]=],
	ScriptLine_122045 = [=[呵呵。]=],
	ScriptLine_122046 = [=[……罢了。]=],
	ScriptLine_122047 = [=[……罢了。]=],
	ScriptLine_122048 = [=[是这样吗……]=],
	ScriptLine_122049 = [=[是这样吗……]=],
	ScriptLine_122050 = [=[指挥官。]=],
	ScriptLine_122051 = [=[指挥官。]=],
	ScriptLine_122052 = [=[哼……]=],
	ScriptLine_122053 = [=[哼……]=],
	ScriptLine_122054 = [=[不足……为惧……]=],
	ScriptLine_122055 = [=[不足……为惧……]=],
	ScriptLine_122056 = [=[呵呵……]=],
	ScriptLine_122057 = [=[呵呵……]=],
	ScriptLine_122058 = [=[什么……！]=],
	ScriptLine_122059 = [=[什么……！]=],
	ScriptLine_122060 = [=[碾碎敌人……！]=],
	ScriptLine_122061 = [=[碾碎敌人……！]=],
	ScriptLine_122062 = [=[竟还有这等事……！]=],
	ScriptLine_122063 = [=[竟还有这等事……！]=],
	ScriptLine_122064 = [=[这就是BIG SEVEN的力量。]=],
	ScriptLine_122065 = [=[这就是BIG SEVEN的力量。]=],
	ScriptLine_122101 = [=[发带有些松了吗？大概是之前挥刀暖身的时候弄的……能帮我重新绑一下吗？……嗯，多谢。]=],
	ScriptLine_122102 = [=[您的手很暖和……像这样捧着我的脸，是担心我感冒吗？但我头发湿哒哒的，会弄湿您的袖子，所以……好了好了，您该不会把我当成落水小猫了吧？真是的。]=],
	ScriptLine_122103 = [=[您觉得我穿得太过单薄了吗？这身衣服能更好地感应四周的环境，有助于我进入“明镜止水”的状态。]=],
	ScriptLine_122104 = [=[唔，怎么突然凑过来……我身上有香味？今天应该没有喷香水……体、体香？胡说八道，肯定是山间的花香，您一定是搞错了……不·许·深·呼·吸！]=],
	ScriptLine_122105 = [=[山泉水浸泡双足确实能解乏。如果不介意的话，您也把鞋脱了，陪我坐一会儿吧。]=],
	ScriptLine_122106 = [=[湿透的布料缠在腿上，有种说不出来的奇怪感觉……我都这么说了，为什么还要来摸啊？就是想看我犯愁的样子吧，我知道的，您偶尔就是会冒出这种坏心思，唉……]=],
	ScriptLine_122107 = [=[以此身受自然之洗礼，祛除杂念，精神统一……呼……这样一来，瀑布修行也告一段落了。指挥官，麻烦您将我带来的替换衣服拿给我好吗？]=],
	ScriptLine_122108 = [=[多谢。请您在此稍等片刻……让您久等了……唉，看您这一脸失望的样子，刚才还没捉弄够我吗？您这人可真是的……]=],
	ScriptLine_122109 = [=[这山间的空气确实清新。在这里持刀而立，总能让我回想起纯粹追求强大的那段修行日子。那时的您，也像今天一样，一直陪在我身边呢。]=],
	ScriptLine_122110 = [=[唔，湿气渐渐渗进皮肤了……指挥官，快把衣服……真是的，您这样盯着看，眼神还这么火热，不是又让我心生杂念了吗？]=],
	ScriptLine_127001 = [=[苍蓝避风港]=],
	ScriptLine_127002 = [=[你问我狼和牛更喜欢哪边？嘿嘿，都喜欢！U-47是像狼一样精准、狠厉的牛，也是像牛一样无所畏惧的狼。怎么样，是不是很帅气？哞！]=],
	ScriptLine_127003 = [=[呼……今天的阳光有点刺眼呢。指挥官，要不要来杯冰镇橘子汁呀？U-47也来一杯。嘻嘻！]=],
	ScriptLine_127004 = [=[哇——！嘻嘻，指挥官，没发现我吧？我的隐蔽训练成果这么好，是不是该给我点奖励了？]=],
	ScriptLine_127005 = [=[指挥官，看样子今晚有空闲呢。不如我带你去水下看看？夜光藻群和熟睡的鱼群，都超——美的哦！]=],
	ScriptLine_127006 = [=[指挥官，你还没睡吗？我这次夜间训练的成果超棒哦！要不给你展示一番？你看了一定会夸奖我的，嘿嘿。]=],
	ScriptLine_127007 = [=[嘿嘿，晚上也能跟指挥官在一起，真好。就算是晚上，也有很多能玩的恶作剧游戏，保证让你跟白天一样开心！]=],
	ScriptLine_127008 = [=[哎呀！指挥官，好、好痒啦！别、别闹了嘛——！]=],
	ScriptLine_127009 = [=[啊——！今天又被指挥官找到了。就算我藏得再隐蔽，您也总能发现我。嘿嘿，这种感觉，居然还挺开心的！]=],
	ScriptLine_127010 = [=[嘘……正好大家都不在，指挥官……不如我们悄悄溜去水族馆，看看那些我们没见过的鱼吧？好多都是平时见不到的，我很好奇呢！]=],
	ScriptLine_127011 = [=[指挥官，你听到U-47的心跳声了吗？扑通扑通的，一整天都响个不停……这一定是你，在U-47心里留下的“恶作剧”吧！嘿嘿~]=],
	ScriptLine_127012 = [=[指挥官，U-47今晚决定不玩恶作剧了。今晚，我只想安静地待在你身边，感受这份暖暖的、安心的感觉。]=],
	ScriptLine_127013 = [=[指挥官！这是U-47的私密领地啦！……不过，看在是指挥官的份上，就、就稍微……哼！]=],
	ScriptLine_127014 = [=[嘻嘻，藏在这里的话，肯定没人能找到。等指挥官来了，就给他一个大大的惊喜……{Action=1270116,Time=9}唔，指挥官什么时候来啊，一个人玩好没劲哦。]=],
	ScriptLine_127015 = [=[呀——！嘻嘻~指挥官，吓到了吗！你一定没看到我是从哪里跳出来的吧。今天也成功吓到指挥官了，好开心哦！哞！]=],
	ScriptLine_127016 = [=[姐妹们，我们到战场了！嘘，悄悄地，给敌人一个大大的惊喜吧！]=],
	ScriptLine_127017 = [=[明白，悄悄地行动~]=],
	ScriptLine_127018 = [=[明白，悄悄地行动~]=],
	ScriptLine_127019 = [=[啊呀！]=],
	ScriptLine_127020 = [=[啊呀！]=],
	ScriptLine_127021 = [=[被、被发现了……可恶！]=],
	ScriptLine_127022 = [=[喜欢我给你的惊喜吗？哞！]=],
	ScriptLine_127023 = [=[哎唷，还有帮手啊？那就送她们一份特别的惊喜咯！]=],
	ScriptLine_127024 = [=[嘿嘿，让火焰冲上云霄！]=],
	ScriptLine_127025 = [=[嘿嘿，让火焰冲上云霄！]=],
	ScriptLine_127026 = [=[悄悄地……砰！]=],
	ScriptLine_127027 = [=[悄悄地……砰！]=],
	ScriptLine_127028 = [=[悄悄地帮帮你，不用谢啦。]=],
	ScriptLine_127029 = [=[哼哼，这就是斯卡帕湾之牛的本事！哞！]=],
	ScriptLine_127030 = [=[呼，有些地方没能藏好……不过没关系，下次我一定会做得更完美！]=],
	ScriptLine_127031 = [=[呀——！嘿嘿，指挥官，有没有被U-47吓一跳呀？隐蔽大作战，大·成·功！哞！接下来陪我一起，去给其他人也送上特别的惊喜吧，绝对会很有趣的~]=],
	ScriptLine_127032 = [=[指挥官，我会紧紧跟着你，把所有挡路的家伙，通通变成海底的碎屑！谁都别想再把我们分开哦！哞！]=],
	ScriptLine_127033 = [=[嘿嘿，这下我的隐蔽能力更完美啦。]=],
	ScriptLine_127034 = [=[指挥官，我发现，我比以前还要更加、更加喜欢你啦！以后无论多黑、多远的地方，我都要和你一起去探索。所以，永远，永远都不许离开我哦！不管我藏在哪里，你都要立刻找到我哦！]=],
	ScriptLine_127035 = [=[诶？]=],
	ScriptLine_127036 = [=[诶？]=],
	ScriptLine_127037 = [=[知道啦！]=],
	ScriptLine_127038 = [=[知道啦！]=],
	ScriptLine_127039 = [=[嘻嘻！]=],
	ScriptLine_127040 = [=[嘻嘻！]=],
	ScriptLine_127041 = [=[哎……]=],
	ScriptLine_127042 = [=[哎……]=],
	ScriptLine_127043 = [=[唔——]=],
	ScriptLine_127044 = [=[唔——]=],
	ScriptLine_127045 = [=[指挥官！]=],
	ScriptLine_127046 = [=[指挥官！]=],
	ScriptLine_127047 = [=[讨厌！]=],
	ScriptLine_127048 = [=[讨厌！]=],
	ScriptLine_127049 = [=[呜……]=],
	ScriptLine_127050 = [=[呜……！]=],
	ScriptLine_127051 = [=[嘿嘿……]=],
	ScriptLine_127052 = [=[嘿嘿……]=],
	ScriptLine_127053 = [=[哎呀！]=],
	ScriptLine_127054 = [=[哎呀！]=],
	ScriptLine_127055 = [=[哼！]=],
	ScriptLine_127056 = [=[哼！]=],
	ScriptLine_127057 = [=[哞！]=],
	ScriptLine_127058 = [=[该恶作剧咯~]=],
	ScriptLine_127101 = [=[U-47在做料理啦，别突然捏人家的脸……诶，软软的，像海星？啊，真的……跟U-47的海星朋友触感一模一样诶……不对，你害得U-47脸上都沾上酱料啦！]=],
	ScriptLine_127102 = [=[我们都是木头人，不许说话不·许·动！……………………啊，沙拉要掉……啊！不算，不算！指挥官你耍赖！敢不敢让U-47放下沙拉再比一次！]=],
	ScriptLine_127103 = [=[嘻嘻，指挥官你……是在找U-47身上有没有偷偷藏着小零食吗？马上就要开饭啦，U-47再怎么贪吃也不会……好痒哦~都说了没有藏啦！哞！]=],
	ScriptLine_127104 = [=[在厨房做料理的时候不能穿睡衣？谁规定的？这是指挥官送我的睡衣，我就要一直穿着——会沾上味道？那就到海里洗洗就好啦，正好还可以潜水，一举两得！]=],
	ScriptLine_127105 = [=[哎呀，指挥官你看！那些锅碗瓢盆挂得好高哦，U-47踮着脚尖都拿不到啦！每次都要爬上桌子，弄得一脚水……这种时候，要是正好有个宽厚稳重的肩膀让U-47骑上去……嘿嘿，就知道指挥官最疼爱U-47啦~]=],
	ScriptLine_127106 = [=[哎呀！指挥官，那里、那里好痒啦！噗嗤……不管你怎么逼供，U-47也不会透露今天的食谱的！食材我都藏起来啦！斯卡帕湾之牛绝不屈服！哞！]=],
	ScriptLine_127107 = [=[锵锵！U-47特制的“度假沙拉”完成啦！……白色的东西？哪有……啊！？这小家伙，趁我一不留神就……！难怪之前一直在一旁虎视眈眈，我就该想到它们也嘴馋的，咕呜呜……指挥官，我们吃了它吧！]=],
	ScriptLine_127108 = [=[呀，指挥官你来啦，U-47一个人在厨房里做料理，总觉得有点空荡荡的呢。这下好啦，有你陪我一起做料理，肯定会好开心的！]=],
	ScriptLine_127109 = [=[指挥官！这间度假屋，好多东西都跟平时用的不一样呢！U-47好喜欢这里的新鲜感！而且离海这么近，太棒啦！谢谢指挥官选了这里！]=],
	ScriptLine_127110 = [=[指挥官，你猜U-47有没有偷偷尝一口？嘿嘿，才不告诉你呢！不过我保证，U-47做的料理，绝对是这个世界上最美味的！]=],
	ScriptLine_128001 = [=[苍蓝避风港]=],
	ScriptLine_128002 = [=[哎呀呀……真是失态了，刚才看着窗外的景色太入神，竟然忘记时间了~不过话说回来，指挥官，您刚才是不是也站在附近，注视了我很久呢？]=],
	ScriptLine_128003 = [=[巡逻也可以是一次浪漫的漫步——来吧，指挥官。把手递给我，让我们像欣赏风景一样，优雅地完成工作吧。]=],
	ScriptLine_128004 = [=[夜深人静的时候，总是让人忍不住想起往事呢。那些辉煌的、平静的、又或是遗憾的时光……呵呵，别担心，我只是在享受这种怀旧的情绪而已。]=],
	ScriptLine_128005 = [=[港区里总有那么几个孩子，对我的态度一直毕恭毕敬的……这还真让我有点苦恼。比起当一个受人敬仰的“老古董”，我还是更希望和那些孩子聊聊她们喜欢什么呢。]=],
	ScriptLine_128006 = [=[这么想深入地了解我吗？真可爱~]=],
	ScriptLine_128007 = [=[今天的工作计划是——和指挥官到无人的沙滩上，一起练习贴身舞~呵呵，果然害羞了呢？我还没开始教，您就已经浮想联翩了？]=],
	ScriptLine_128008 = [=[您知道吗？每个人都有属于自己的故事，而我呢，恰好见证过很多很多悲欢离合……想听吗？请靠近我一点，这些悄悄话只能让您一个人听哦？]=],
	ScriptLine_128009 = [=[呵呵……被您发现我的“小秘密”了呢？]=],
	ScriptLine_128010 = [=[他看待事物的眼神……总能够穿透表象，或许正是因为这一点，我才会被那副眼神深深吸引……]=],
	ScriptLine_128011 = [=[……哦？您听到了吗？呵呵……不必感到难为情，我的内心不是早就被您看透了吗？]=],
	ScriptLine_128012 = [=[大家，注意咯~战场局势如同变幻的舞曲，不用心可会乱了拍子的。]=],
	ScriptLine_128013 = [=[听从您的调遣~]=],
	ScriptLine_128014 = [=[听从您的调遣~]=],
	ScriptLine_128015 = [=[呀……！]=],
	ScriptLine_128016 = [=[呀……！]=],
	ScriptLine_128017 = [=[传奇会陨落……但是故事总会被人铭记……]=],
	ScriptLine_128018 = [=[退场吧——！]=],
	ScriptLine_128019 = [=[退场吧——！]=],
	ScriptLine_128020 = [=[哦？又有人来扰乱我们的舞台了？]=],
	ScriptLine_128021 = [=[翩然起舞吧！]=],
	ScriptLine_128022 = [=[翩然起舞吧！]=],
	ScriptLine_128023 = [=[你能跟上我的舞步吗？]=],
	ScriptLine_128024 = [=[你能跟上我的舞步吗？]=],
	ScriptLine_128025 = [=[偶尔也得履行一下前辈的责任呢~]=],
	ScriptLine_128026 = [=[偶尔也得履行一下前辈的责任呢~]=],
	ScriptLine_128027 = [=[完美的表演！能和大家一起演绎这样一曲胜利之舞，真是让人心情愉悦呢~]=],
	ScriptLine_128028 = [=[虽然有美中不足的地方，但总归来说算是一场美妙的体验哦。收起自我检讨的想法，坦然对待结果吧~]=],
	ScriptLine_128029 = [=[战列巡洋舰，戈本号已经抵港~我的过去曾是一部传奇，而我的未来……呵呵，似乎与您交织在一起了呢。]=],
	ScriptLine_128030 = [=[我又回到您身边了~无论多少次，重逢的喜悦都不会褪色呢。]=],
	ScriptLine_128031 = [=[舞步更轻盈了~]=],
	ScriptLine_128032 = [=[您知道吗？世界上最美的舞步，是一颗心与另一颗心的共鸣，而指挥官您，为我的每一步都赋予了意义……您是否愿意，和我将这支双人舞持续到时光的尽头？]=],
	ScriptLine_128033 = [=[嗯~？]=],
	ScriptLine_128034 = [=[嗯~？]=],
	ScriptLine_128035 = [=[好啊~]=],
	ScriptLine_128036 = [=[好啊~]=],
	ScriptLine_128037 = [=[呵呵……]=],
	ScriptLine_128038 = [=[呵呵……]=],
	ScriptLine_128039 = [=[唉……]=],
	ScriptLine_128040 = [=[唉……]=],
	ScriptLine_128041 = [=[嗯——]=],
	ScriptLine_128042 = [=[嗯——]=],
	ScriptLine_128043 = [=[指挥官~]=],
	ScriptLine_128044 = [=[指挥官~]=],
	ScriptLine_128045 = [=[这可不行哦。]=],
