	ScriptLine_128052 = [=[嚯？]=],
	ScriptLine_128053 = [=[过火了呢。]=],
	ScriptLine_128054 = [=[过火了呢。]=],
	ScriptLine_128055 = [=[放轻松~]=],
	ScriptLine_128056 = [=[来跳舞吧~]=],
	ScriptLine_128057 = [=[苍蓝避风港]=],
	ScriptLine_129001 = [=[苍蓝避风港]=],
	ScriptLine_129002 = [=[指挥官，不挠给我推荐了一家新开的点心店，据说红茶也很地道。要不要一起去品尝一下？就当是放松一下心情。]=],
	ScriptLine_129003 = [=[指挥官，我最近买到一本古老的魔法典籍！好像是叫《最强航母在异世界也要无双》，很特别又很长的名字呢，{Action=1290111,Time=11}一定记载了很强的魔法！]=],
	ScriptLine_129004 = [=[你问这些礼物？当然是奖励给那些努力训练的孩子们啊——看起来很贵？远超购物预算？{Action=1290104,Time=10}没……没关系！胡德会理解我的！……她会理解我的……吧？]=],
	ScriptLine_129005 = [=[黑暗越是深沉，人们就越渴望光明。我们所做的一切努力，就像在黑暗中点燃一盏盏明灯，为迷途的人们指引方向，带来希望之光。你说对吗？]=],
	ScriptLine_129006 = [=[指挥官，吃过夜宵了吗？我可以帮你准备些热牛奶和小饼干。{Action=1290110,Time=6}我想想……应该只要把牛奶倒进电热水壶，然后按一下按钮就好了吧……]=],
	ScriptLine_129007 = [=[可畏太宅，不挠太闹，胜利又太认真。我这三个妹妹啊，各个都是不让人省心的人才。真是……拿她们没办法呢，呵呵。]=],
	ScriptLine_129008 = [=[呀……{Action=1290108,Time=1}指挥官，突然……摸这种地方，会、会让人有些困扰的……]=],
	ScriptLine_129009 = [=[指挥官，你今天看起来精神不错呢，是有什么好事发生吗？呵呵……如果每天都能看到你这样就好了。{Action=1290112,Time=10}今天有什么特别想做的事情吗？我可以陪你一起。]=],
	ScriptLine_129010 = [=[指挥官，你看，阳光洒在海面上，波光粼粼的。现在，我让它们凝聚成更特别的光芒了……只为你一个人闪耀的光芒，你喜欢吗？]=],
	ScriptLine_129011 = [=[夜空之中，点点星光就如同人们炽热的愿望、未言的心绪。我愿所有的星辰，都能绽放出最耀眼的光芒，这样即使相隔遥远，也终将……被彼此的光芒吸引，交相辉映……就像现在的我们一样。]=],
	ScriptLine_129012 = [=[今晚的月光真美……柔和又皎洁，就像一层薄纱，轻轻笼罩着我们……像这样靠着你，也好温暖……啊，原来我感受到的光芒，不仅仅是月色啊……]=],
	ScriptLine_129013 = [=[呼……真是的……你总是喜欢突然这样……{Action=1290116,Time=6}那就，稍微再来一下下好了……]=],
	ScriptLine_129014 = [=[……指挥官今天……会晚点来吗？总觉得，这间指挥室，少了那份无可替代的光芒，就显得有些空旷了呢……]=],
	ScriptLine_129015 = [=[指挥官，你来啦。我就知道，因为这里一下就亮起来了。呵呵，你总是可以照亮任何地方。]=],
	ScriptLine_129016 = [=[愿各位的光芒，如星耀般刺破黑夜，驱散迷雾，指引方向。]=],
	ScriptLine_129017 = [=[我会用光芒照亮战场。]=],
	ScriptLine_129018 = [=[我会用光芒照亮战场。]=],
	ScriptLine_129019 = [=[唔……要更加集中精神。]=],
	ScriptLine_129020 = [=[唔……要更加集中精神。]=],
	ScriptLine_129021 = [=[光芒……要……消散了吗……？]=],
	ScriptLine_129022 = [=[光芒……要……消散了吗……？]=],
	ScriptLine_129023 = [=[连一道影子也不会留下。]=],
	ScriptLine_129024 = [=[连一道影子也不会留下。]=],
	ScriptLine_129025 = [=[是敌人的增援……不必在意，我的光芒会将她们彻底粉碎。]=],
	ScriptLine_129026 = [=[于星夜之下，宣告汝等的终结！辉煌，一闪！]=],
	ScriptLine_129027 = [=[于星夜之下，宣告汝等的终结！辉煌，一闪！]=],
	ScriptLine_129028 = [=[上吧！]=],
	ScriptLine_129029 = [=[上吧！]=],
	ScriptLine_129030 = [=[以光辉之名……！]=],
	ScriptLine_129031 = [=[以光辉之名……！]=],
	ScriptLine_129032 = [=[聚集的祈愿，将化作光芒闪耀的道路。]=],
	ScriptLine_129033 = [=[是大家的光芒带来了胜利。]=],
	ScriptLine_129034 = [=[指挥官，光辉前来报道。能够在此地与你相逢，定然是出自命运光芒的指引。愿我们如同星光般，携手照亮彼此的前路。]=],
	ScriptLine_129035 = [=[我会追随你的步伐，以光辉为刃，斩破一切阻碍，直至辉耀最终的胜利。]=],
	ScriptLine_129036 = [=[这份新的力量，让我的光芒更加耀眼夺目。]=],
	ScriptLine_129037 = [=[【冷漠】曾如星火般微弱的<ruby=爱>勇气</ruby>，如今已化为……永恒不变的魔法。【害羞】那是当我凝视你眼眸时，满溢心中的温暖。是连无尽黑夜也能温柔拥抱的、世界上最绚烂的、只为你一人盛放的光华。]=],
	ScriptLine_129038 = [=[嗯？]=],
	ScriptLine_129039 = [=[嗯？]=],
	ScriptLine_129040 = [=[嗯！]=],
	ScriptLine_129041 = [=[嗯！]=],
	ScriptLine_129042 = [=[Brilliant！]=],
	ScriptLine_129043 = [=[Brilliant！]=],
