	ScriptLine_129055 = [=[嗯哼……]=],
	ScriptLine_129056 = [=[呀……！]=],
	ScriptLine_129057 = [=[呀……！]=],
	ScriptLine_129058 = [=[光将驱散一切不净！]=],
	ScriptLine_129059 = [=[光将驱散一切不净！]=],
	ScriptLine_129060 = [=[愿光驱散迷雾与不安。]=],
	ScriptLine_129061 = [=[这个当然是魔法~]=],
	ScriptLine_129062 = [=[这个当然是魔法~]=],
	ScriptLine_129101 = [=[哎呀，别把我的发丝弄乱了嘛~虽然这样子……只会给你一个人看……]=],
	ScriptLine_129102 = [=[嘻嘻，我戴眼镜的样子好看吗？我可不是视力不好哦，只是想让你看到我最“聪明”的一面啦。难得你来家里，想给你留下个好印象嘛。]=],
	ScriptLine_129103 = [=[哦？你很在意这件睡衣的材质吗？嗯……确实很柔软，很透气，摸起来有一种冰凉感，适合炎热的日子在家里穿呢……我说，这可是你之前送我的睡衣啊，你……该不会是故意装作不记得的吧？哼。]=],
	ScriptLine_129104 = [=[你这是……担心我穿太少受凉吗？傻瓜……才不会呢。反而是你在身边的缘故，我整个人……都暖暖。]=],
	ScriptLine_129105 = [=[这样坐久了，腿会有些麻呢。指挥官……可以帮我按摩一下吗？对，就是脚底那块……唔，指挥官你，手法也太好了吧，这么舒服，我都没法安心看书啦。]=],
	ScriptLine_129106 = [=[很在意这本书吗？这可是最近很流行的异世界冒险奇幻小说呢！故事里描绘的魔法啊，简直天马行空，光怪陆离……总能给我带来不少启发和乐趣。你也很好奇吗？那我们可以一起看呀！]=],
	ScriptLine_129107 = [=[平时灵感来了，我会随手记下一些魔法术式的草稿和构想。指挥官如果有兴趣可以随便翻看……页脚的咖啡渍？别在意那种地方嘛，是人都会有失误啦。]=],
	ScriptLine_129108 = [=[这些孩子可喜欢这屋子里的光芒了。你看，阳光透过窗户，洒在叶片上，它们就会努力地吸收、转化……将光芒变成自己的生命。这，又何尝不是一种非常基础、却又伟大的光魔法呢？]=],
	ScriptLine_129109 = [=[我这副……嗯，居家打扮，没吓到你吧？其实这是为了你特地穿的，平时我才不是这个样子呢……啊，你那眼神，是完全不相信啊。好吧好吧，我平时一个人在家就是这么穿的，哼，那又怎么啦，这样才最放松，最自然啦。]=],
	ScriptLine_129110 = [=[和你一起在家里放松的感觉真好，仿佛整个世界都充满光芒……再过来一点，好吗？我想更多、更多感受你的心跳和温度。]=],
	ScriptLine_131001 = [=[苍蓝避风港]=],
	ScriptLine_131002 = [=[今天的风儿有些喧嚣，仿佛正在哭泣……指挥官，您为什么要偷偷笑啊！]=],
	ScriptLine_131003 = [=[暖洋洋的天气会让人昏昏欲睡呢，我明白您的感受。这是提神醒脑的薄荷茶。今天的工作还剩最后一点了，指挥官，加油~]=],
	ScriptLine_131004 = [=[您今天工作一天辛苦了。我帮您按摩放松一下吧，大家都说我很擅长的~来，请趴在沙发上~]=],
	ScriptLine_131005 = [=[听说按摩手部，可以缓解腱鞘炎和胃疼的症状……指挥官，能拜托您……帮我按摩一下吗？]=],
	ScriptLine_131006 = [=[呀！？等一下，指挥官，这样我没办法写报告啦……真是的。]=],
	ScriptLine_131007 = [=[树叶在风中翩然起舞，心爱之人缓缓而来…………原来如此，这景象或许能用在小说里，先记在笔记上……]=],
	ScriptLine_131008 = [=[星空下的散步约会，很浪漫呢。如此寂静的夜晚，月光似乎也染上了温柔的夜色。]=],
	ScriptLine_131009 = [=[指挥官……刚刚那个，能再来一次吗？这次……要在嘴唇上……]=],
	ScriptLine_131010 = [=[……其实A也没什么不好的，至少买衣服很方便，作战时也不会影响行动和视线……指挥官也说过他不在意……唉，神明已死……]=],
	ScriptLine_131011 = [=[呀！？指挥官，您……什么时候来的？我在碎碎念？……啊哈哈，一定是您幻听了！——对，就是幻·听。]=],
	ScriptLine_131012 = [=[由我来向您展示，何谓二航战的战术吧。]=],
	ScriptLine_131013 = [=[这里就由我来——]=],
	ScriptLine_131014 = [=[这里就由我来——]=],
	ScriptLine_131015 = [=[这不算什么……！]=],
	ScriptLine_131016 = [=[这不算什么……！]=],
	ScriptLine_131017 = [=[对不起，指挥官……]=],
	ScriptLine_131018 = [=[沦没于碧海之下吧。]=],
	ScriptLine_131019 = [=[沦没于碧海之下吧。]=],
	ScriptLine_131020 = [=[是敌人的援军吗？冷静应对吧。]=],
	ScriptLine_131021 = [=[拜托大家了……！]=],
	ScriptLine_131022 = [=[拜托大家了……！]=],
	ScriptLine_131023 = [=[你已经无处可逃！]=],
	ScriptLine_131024 = [=[你已经无处可逃！]=],
	ScriptLine_131025 = [=[希望这能帮到大家——]=],
	ScriptLine_131026 = [=[希望这能帮到大家——]=],
	ScriptLine_131027 = [=[我们胜利了，指挥官！就跟计划的一样呢！]=],
	ScriptLine_131028 = [=[有人负伤了，先休整一下吧。]=],
	ScriptLine_131029 = [=[飞鹰型轻母二号舰隼鹰，前来与指挥官重逢了。让我们一起结束这场战争吧。]=],
	ScriptLine_131030 = [=[作战计划就交由我来制订吧。我会为指挥官、为大家带来完美的胜利。]=],
	ScriptLine_131031 = [=[我会不断变得更强，直至迎来和平的那一天。]=],
	ScriptLine_131032 = [=[您眼中的远景，亦是照亮我心中未来蓝图的光芒。让我成为您诗篇第一页的起笔，一起书写属于我们的结局。]=],
	ScriptLine_131033 = [=[嗯？]=],
