	ScriptLine_132001 = [=[苍蓝避风港]=],
	ScriptLine_132002 = [=[嗯……？指挥官觉得我和以前不太一样了？{Action=1320104,Time=5}呼呼~是不是觉得很惊艳呢？我这身可是经过全面升级的战斗服，战斗性能和色彩设计都无可挑剔！您看，“使魔”们的样子也焕然一新了呢！]=],
	ScriptLine_132003 = [=[刚才在Z16面前演示了空中悬浮魔法，结果被她狠狠羡慕了呢~小萤超得意！]=],
	ScriptLine_132004 = [=[从大家房间里透出的灯光，远看就像成群的萤火虫一样……每次看到这幅景象都会觉得自己不孤单了呢。]=],
	ScriptLine_132005 = [=[杯子裂了没关系，交给魔法小萤来解决吧！哗啦啦啦~哗啦啦啦~杯子小姐请复原吧☆{Action=1320116,Time=10}呜啊啊啊啊？！怎么炸掉了！]=],
	ScriptLine_132006 = [=[哈哈哈——指挥官，不要摸这里了啦~好痒哦~]=],
	ScriptLine_132007 = [=[我我我我现在有变得很得意吗？！……{Action=1320118,Time=4}唔，小萤只是想要指挥官多看看我嘛……]=],
	ScriptLine_132008 = [=[指挥官累了吗？唔……让小萤帮您缓解一下疲劳吧。来，请躺下——{Action=1320104,Time=11}怎么样？这样揉太阳穴会不会舒服一点呢？嗯嗯~舒服就好，看来小萤的放松魔法奏效了呢~]=],
	ScriptLine_132009 = [=[小萤也喜欢指挥官哦……好喜欢和您贴贴的感觉~]=],
	ScriptLine_132010 = [=[指挥官~您在哪里呀~？……{Action=1320113,Time=4}诶？难道不在这里？]=],
	ScriptLine_132011 = [=[咦？原来您在这里呀！难道是在和小萤玩捉迷藏……？{Action=1320104,Time=6}嘿嘿~被抓到的人要惩罚一个抱抱！]=],
	ScriptLine_132012 = [=[咳……咳咳！感谢大家信任！这次的战斗就交给我吧！]=],
	ScriptLine_132013 = [=[小萤会全力以赴的！]=],
	ScriptLine_132014 = [=[小萤会全力以赴的！]=],
