	ScriptLine_132026 = [=[大家！振作一点哇！]=],
	ScriptLine_132027 = [=[大功告成~！我的魔法是不是很厉害呢！]=],
	ScriptLine_132028 = [=[嗯……小萤会继续努力，争取以后完美完成任务！]=],
	ScriptLine_132029 = [=[G级驱逐舰萤火虫，登场——！嘿嘿~小萤和“使魔”们能够见到您实在是太开心啦！]=],
	ScriptLine_132030 = [=[魔法小萤，降临！指挥官请放心，我会好好教训坏家伙们的！]=],
	ScriptLine_132031 = [=[好耶~小萤能用更厉害的魔法了！]=],
	ScriptLine_132032 = [=[小萤一直都知道，您时刻陪伴着我、守望着我、爱护着我……小萤一定是世界上最幸福的人。小萤也会努力，用我的<ruby=魔法>爱意</ruby>让您成为世界上最幸福的指挥官！请您多多期待吧~]=],
