	ScriptLine_133001 = [=[苍蓝避风港]=],
	ScriptLine_133002 = [=[这房间有点闷啊……指挥官，请允许我为您开窗换换气吧，这样能方便您更清醒地处理公务。]=],
	ScriptLine_133003 = [=[背挺直！指挥官，您的眼睛离文件太近了。说了多少次，坐姿不对以后可有的受。]=],
	ScriptLine_133004 = [=[驱逐舰们的换季衣服还没整理完，食堂的采购清单又来了……唉，事情总是做不完啊。]=],
	ScriptLine_133005 = [=[油炸食品申请……？这可不行啊指挥官，那东西太不健康了，对您的肠胃负担很重的——对了，您要不要尝尝看我刚做的蔬菜便当？我有自信做得比那种食物更好吃哦。]=],
	ScriptLine_133006 = [=[指挥官，您来评评理。企业小姐居然说我最近唠叨的程度升级了！我不过每天随口提醒大家按时吃饭、早点睡觉、别熬夜多休息、出门注意安全小心车辆……这怎么能算唠叨呢？]=],
	ScriptLine_133007 = [=[巡逻完毕，一切正常。指挥官，您是我检查的最后一站了，快关灯吧，我们一起下班。]=],
	ScriptLine_133008 = [=[呀！——指、指挥官请自重，您这样会教坏小孩子的……]=],
	ScriptLine_133009 = [=[嗯，气色总算红润点了。看来我最近一个月的督促早睡服务效果不错，加油噢指挥官，要继续坚持下去呀~]=],
	ScriptLine_133010 = [=[我的碗比其他人的碗大了两圈……？您误会了，这、这些都是试菜用的容器！啊哈哈……在开什么玩笑呢指挥官，我的食量当然很正常啊。]=],
	ScriptLine_133011 = [=[看着那些孩子们一个个平安回来，能吃能睡，我就很欣慰了。]=],
	ScriptLine_133012 = [=[无论是修复舰装，还是守护大家的精神与活力，对我来说，都是至关重要的职责……好啦，指挥官。您的牛奶也喝完了，现在该轮到您去睡觉了，我收拾完这里就去休息。]=],
	ScriptLine_133013 = [=[又、又来？唔，真拿您没办法……]=],
	ScriptLine_133014 = [=[指挥官今天已经喝了三杯咖啡，这样下去晚上的睡眠质量肯定会受影响……得想办法让他早点休息才行。]=],
	ScriptLine_133015 = [=[……啊，原来您在这里啊。真是的，正在坏心眼地看着我担心您的样子吗？]=],
	ScriptLine_133016 = [=[孩子们，都给我打起精神！“盛宴”开始了！]=],
	ScriptLine_133017 = [=[该下点狠料了。]=],
	ScriptLine_133018 = [=[唔……！]=],
	ScriptLine_133019 = [=[唔……！]=],
	ScriptLine_133020 = [=[抱歉，指挥官……感觉使不上力了……]=],
	ScriptLine_133021 = [=[尝到我的厉害了吧！]=],
	ScriptLine_133022 = [=[尝到我的厉害了吧！]=],
	ScriptLine_133023 = [=[新敌人？看来“盛宴”一时半会还无法结束呢！]=],
	ScriptLine_133024 = [=[开饭啦！呃不对……是修理领域展开！]=],
	ScriptLine_133025 = [=[吃我一记！]=],
	ScriptLine_133026 = [=[吃我一记！]=],
	ScriptLine_133027 = [=[坚持住！]=],
	ScriptLine_133028 = [=[坚持住！]=],
	ScriptLine_133029 = [=[大获全胜——嗯嗯，大家做得真好，今晚加餐管够！]=],
	ScriptLine_133030 = [=[赢了就好……快过来，让我看看伤在哪里了？下次可不许这么莽撞了！]=],
	ScriptLine_133031 = [=[维修舰AR-4，女灶神号，已抵达港区。我会全力负责港区的后勤维护与成员们的健康管理——特别是指挥官，我会重点关照您的饮食起居哦。]=],
	ScriptLine_133032 = [=[又见面啦，指挥官。无论是港区需要修理的地方，还是您需要被“修理”的坏习惯，都尽管放马过来吧。]=],
	ScriptLine_133033 = [=[很好很好，手艺见长~]=],
	ScriptLine_133034 = [=[我们的命运早已紧紧交织在一起……我习惯了照顾您，而您也已经习惯我的唠叨。在您为港区奋斗的每一天里，我的料理都会持续为您提供温暖与力量，就让我们共同面对今后的生活吧~我亲爱的指挥官。]=],
	ScriptLine_133035 = [=[嗯？]=],
	ScriptLine_133036 = [=[嗯？]=],
	ScriptLine_133037 = [=[明白了。]=],
	ScriptLine_133038 = [=[明白了。]=],
	ScriptLine_133039 = [=[太好了！]=],
	ScriptLine_133040 = [=[太好了！]=],
	ScriptLine_133041 = [=[唉……]=],
	ScriptLine_133042 = [=[唉……]=],
	ScriptLine_133043 = [=[唔……]=],
	ScriptLine_133044 = [=[唔……]=],
	ScriptLine_133045 = [=[指挥官！]=],
	ScriptLine_133046 = [=[指挥官~]=],
	ScriptLine_133047 = [=[这可不行！]=],
	ScriptLine_133048 = [=[这可不行！]=],
	ScriptLine_133049 = [=[什么……]=],
	ScriptLine_133050 = [=[什么……]=],
	ScriptLine_133051 = [=[真是的……]=],
	ScriptLine_133052 = [=[真是的……]=],
	ScriptLine_133053 = [=[呀！]=],
	ScriptLine_133054 = [=[呀！]=],
	ScriptLine_133055 = [=[太不像话！]=],
	ScriptLine_133056 = [=[太不像话！]=],
	ScriptLine_133057 = [=[听话——]=],
	ScriptLine_133058 = [=[听话——]=],
	ScriptLine_133059 = [=[谁是老妈子啊！]=],
	ScriptLine_137001 = [=[苍蓝避风港]=],
	ScriptLine_137002 = [=[当我遇到困难时，我会尝试以您的视角来看待问题。嗯？我当然了解您了，我连您做梦会说什么梦话都知道～{Action=1370104,Time=11}真的真的，您再凑近点，我悄悄告诉您～]=],
	ScriptLine_137003 = [=[小队之间有竞争关系，更有利于共同进步。如果大家都相敬如宾，那干脆拉起手围个圈跳友谊舞得了。战斗，可不是和和气气就能妥善处理的事情。]=],
	ScriptLine_137004 = [=[这套制服是为了纪念那次任务而特别定做的，我都说过好多遍了，想必您也听烦了。{Action=1370106,Time=9}不过呀，“巫女”还真没有看上去那么轻松。每一个职业背后，都付诸了努力与汗水。]=],
	ScriptLine_137005 = [=[您刚才的小动作被我发现了！把手伸出来～{Action=1370101,Time=5}嘿嘿，果然藏了好吃的。张开嘴，啊～好东西呀，自然要先请您吃。剩下的，交给我保管吧。晚上吃太多甜食可不好～]=],
	ScriptLine_137006 = [=[——刚刚那是什么！？您有看到吗？突然碰了我一下……{Action=1370118,Time=5}就是您吧！]=],
	ScriptLine_137007 = [=[老实说，我还挺佩服您的。工作之余，还能想到这么多完全不重样的小把戏来逗我。果然，像您这样的人，做什么都会成功的。{Action=1370123,Time=12}哈哈，就算听起来怪怪的，也是在夸您哦～]=],
	ScriptLine_137008 = [=[差一点点就能看到月亮了，乌云真是不解风情啊。{Action=1370119,Time=6}如果有满月，我就可以拉您去外面，然后适时地引导您说出“月色真美”。比起直白的那种，我更喜欢浪漫一些的~]=],
	ScriptLine_137009 = [=[——嘿！抓到您了。同样的招数，对我……{Action=1370104,Time=4}啊哈哈哈，赖皮！别挠我了啊哈哈哈哈——]=],
	ScriptLine_137010 = [=[您该不会是睡着了吧？嘿嘿，要怎么整您才好呢？在您的手背上画一个吹雪的徽记～{Action=1370103,Time=14}您醒了之后，会是什么反应呢～？]=],
	ScriptLine_137011 = [=[呀啊！？您没睡着啊？咳咳……我这是在给您设计签名呢。真的，千真万确！您突然吓我，害得我灵感都跑光了。]=],
	ScriptLine_137012 = [=[第十一驱逐队旗舰，吹雪，等候指令。]=],
	ScriptLine_137013 = [=[该做出变化了。]=],
	ScriptLine_137014 = [=[我还能行。]=],
	ScriptLine_137015 = [=[我还能行。]=],
	ScriptLine_137016 = [=[别紧张，继续执行战术，我相信你们。]=],
	ScriptLine_137017 = [=[你没看起来那么厉害。]=],
	ScriptLine_137018 = [=[又出现了吗……我们占据上风，坚持就是胜利。]=],
	ScriptLine_137019 = [=[你的罪业，到此为止了。]=],
	ScriptLine_137020 = [=[你的罪业，到此为止了。]=],
	ScriptLine_137021 = [=[别想再靠近了。]=],
	ScriptLine_137022 = [=[别想再靠近了。]=],
	ScriptLine_137023 = [=[冷静，有我在呢。]=],
	ScriptLine_137024 = [=[冷静，有我在呢。]=],
	ScriptLine_137025 = [=[大家没事吧？不要太勉强自己了。]=],
	ScriptLine_137026 = [=[大家没事吧？不要太勉强自己了。]=],
	ScriptLine_137027 = [=[……出现这样的情况，要更加警惕了。]=],
	ScriptLine_137028 = [=[——勉强赶上了！我是特型驱逐舰一番舰，吹雪。指挥官，让您久等了。我没有睡过头，是在帮人解决烦恼！而接下来，就轮到您啦~有什么事都可以跟我讲，欢迎“投稿”！]=],
	ScriptLine_137029 = [=[您抽到了“大吉”！今天一定会有好事发生~]=],
	ScriptLine_137030 = [=[在您的督促下，我又变强了！]=],
	ScriptLine_137031 = [=[自从当上巫女后，我开始觉得“缘分的红绳”是真实存在的。它呀，就缠绕在我们的小指上，守护着相邻在无名指上的——我们爱情的结晶。]=],
	ScriptLine_137032 = [=[嗯？]=],
	ScriptLine_137033 = [=[出问题了吗？]=],
	ScriptLine_137034 = [=[就这样！]=],
	ScriptLine_137035 = [=[就这样！]=],
	ScriptLine_137036 = [=[嘿嘿。]=],
	ScriptLine_137037 = [=[嘿嘿。]=],
	ScriptLine_137038 = [=[不行……]=],
	ScriptLine_137039 = [=[不行……]=],
	ScriptLine_137040 = [=[好像……]=],
	ScriptLine_137041 = [=[好像……]=],
	ScriptLine_137042 = [=[指～挥～官～]=],
	ScriptLine_137043 = [=[指～挥～官～]=],
	ScriptLine_137044 = [=[别开玩笑。]=],
	ScriptLine_137045 = [=[别开玩笑。]=],
	ScriptLine_137046 = [=[哎——]=],
	ScriptLine_137047 = [=[哎——]=],
	ScriptLine_137048 = [=[又来了……]=],
	ScriptLine_137049 = [=[又来了……]=],
	ScriptLine_137050 = [=[呀啊！？]=],
	ScriptLine_137051 = [=[呀啊！？]=],
	ScriptLine_137052 = [=[竟敢……！]=],
	ScriptLine_137053 = [=[竟敢……！]=],
	ScriptLine_137054 = [=[你没事吧？]=],
	ScriptLine_137055 = [=[你没事吧？]=],
	ScriptLine_138001 = [=[苍蓝避风港]=],
	ScriptLine_138002 = [=[锵锵~这就是基林的宝贝《指挥官百科大全》啦！您的所有、所有的一切，都记载在这本工具书里面了喔！{Action=1380108,Time=11}因为，我想把关于您的所有事情，都变成我最熟悉、最拿手的知识呀！]=],
	ScriptLine_138003 = [=[刚才列克星敦前辈夸我文件整理得“有点样子”了！嘿嘿~只要我幻想指挥官站在我身后，就能把文件都整理在指挥官最顺手的位置！{Action=1380110,Time=12}所以，这是基林跟指挥官的共同成果呢~]=],
	ScriptLine_138004 = [=[指挥官，白天的我有些兴奋了，没给您添麻烦吧？{Action=1380101,Time=5}……欸？很有活力、很可爱？{Action=1380121,Time=9}——嗯哼！（清嗓子）那、那还用说，我可是您最棒的专属小秘书，每一天都元气十足啦！]=],
	ScriptLine_138005 = [=[指挥官，干杯！——噗啊！果然晚上的冰可乐就是爽啊！指挥官白天工作那么努力，晚上适当放纵一下也没关系啦！{Action=1380108,Time=16}对了，干脆我再拿点小点心来，开个小party？]=],
	ScriptLine_138006 = [=[呀啊！？指、指挥官！？{Action=1380118,Time=3}那、那个地方……哎哎，这种情况应该要怎么办来着……]=],
	ScriptLine_138007 = [=[哼哼~刚才Z16又来问我您的喜好了，我当然是用《百科》里的“公开版”情报打发她啦！至于“绝密版”嘛……{Action=1380120,Time=11}那当然只属于我们两人，对~吧？指挥官？]=],
	ScriptLine_138008 = [=[呼……今天也努力工作了呢！{Action=1380118,Time=4}指挥官，基林的“燃油”好像快用完啦，需要补充一点“指挥官燃油”才行……{Action=1380119,Time=13}耶，指挥官的肩膀到手啦！基林就靠一会儿，可以的吧？]=],
	ScriptLine_138009 = [=[哼、哼！这、这点程度的接触，对、对专属秘书来说不算什么！{Action=1380118,Time=7}（啊呜……身、身体好烫……完全冷静不下来……）]=],
	ScriptLine_138010 = [=[嘿咻，嘿咻……还差一点点，再往左边挪一点……大功告成！{Action=1380110,Time=12}呼，这样就好啦……{Action=1380121,Time=15}哼哼，我可真是个天才秘书！]=],
	ScriptLine_138011 = [=[指挥官！根据《少女星座周刊》今日运势，您今天的幸运方位是东南方！所以，我把您的办公桌挪了一下，这样就能接收到幸运能量了！]=],
	ScriptLine_138012 = [=[我看见了……我心中的指挥官，正对我微笑——这就是胜利的“预感”！]=],
	ScriptLine_138013 = [=[等您下令啦！]=],
	ScriptLine_138014 = [=[等您下令啦！]=],
	ScriptLine_138015 = [=[呀！？怎么会……]=],
	ScriptLine_138016 = [=[呀！？怎么会……]=],
	ScriptLine_138017 = [=[呜……！跟我想的，不一样……！]=],
	ScriptLine_138018 = [=[呜……！跟我想的，不一样……！]=],
	ScriptLine_138019 = [=[看吧，就跟我想的一样！]=],
	ScriptLine_138020 = [=[看吧，就跟我想的一样！]=],
	ScriptLine_138022 = [=[敌人的增援来了吗……没关系，这也在我的预料之中！]=],
	ScriptLine_138023 = [=[敌人的增援来了吗……没关系，这也在我的预料之中！]=],
	ScriptLine_138024 = [=[指挥官您在看吗？您的基林要出手啦！]=],
	ScriptLine_138025 = [=[指挥官您在看吗？您的基林要出手啦！]=],
	ScriptLine_138026 = [=[你的弱点在这儿吧！]=],
	ScriptLine_138027 = [=[你的弱点在这儿吧！]=],
	ScriptLine_138028 = [=[这个时候……就要用这招！]=],
	ScriptLine_138029 = [=[这个时候……就要用这招！]=],
	ScriptLine_138030 = [=[哼哼~看到了吗？完美胜利，跟我预想的一模一样！]=],
	ScriptLine_138031 = [=[姆……我对指挥官的战术理解还不够透彻吗……要继续精进！]=],
	ScriptLine_138032 = [=[基林级首舰，基林，前来报到！嘻嘻，看您这表情，是在期待什么呀？我可不会再咬到舌头了哦！嘿嘿，是不是感觉我有点不一样了？没错，现在的我，可是最懂你的那个人哦！]=],
	ScriptLine_138033 = [=[咦、咦咦……指挥官您，竟然这么重视基林……这、这毫无疑问是基林的大胜利！要赶紧更新在《指挥官百科大全》里！今后，我会更加努力帮助指挥官的！]=],
	ScriptLine_138034 = [=[基林level up！这样就能更快地跑到您身边啦！]=],
	ScriptLine_138035 = [=[……我一直以为把关于您的一切都写下来，就能完全理解您，也理解自己的感情。可就在刚才，看着您的目光时我才突然明白，那些都不是答案。答案是……我好像，每天都会比昨天更喜欢您一点——唔，这个，也要赶紧写下来才行……]=],
	ScriptLine_138036 = [=[嗯？]=],
	ScriptLine_138037 = [=[嗯？]=],
	ScriptLine_138038 = [=[哼哼！]=],
	ScriptLine_138039 = [=[哼哼！]=],
	ScriptLine_138040 = [=[耶！]=],
	ScriptLine_138041 = [=[耶！]=],
	ScriptLine_138042 = [=[呜……]=],
	ScriptLine_138043 = [=[呜……]=],
	ScriptLine_138044 = [=[哦哦……]=],
	ScriptLine_138045 = [=[哦哦……]=],
	ScriptLine_138046 = [=[指挥官！]=],
	ScriptLine_138047 = [=[指挥官！]=],
	ScriptLine_138048 = [=[姆——！]=],
	ScriptLine_138049 = [=[姆——！]=],
	ScriptLine_138050 = [=[咦……咦咦……]=],
	ScriptLine_138051 = [=[咦……咦咦……]=],
	ScriptLine_138052 = [=[那、那个……]=],
	ScriptLine_138053 = [=[那、那个……]=],
	ScriptLine_138054 = [=[什、什么！？]=],
	ScriptLine_138055 = [=[什、什么！？]=],
	ScriptLine_138056 = [=[真是的！]=],
	ScriptLine_138057 = [=[真是的！]=],
	ScriptLine_138058 = [=[我觉得啊……]=],
	ScriptLine_138059 = [=[我觉得啊……]=],
	ScriptLine_138060 = [=[啊呜！]=],
	ScriptLine_138061 = [=[啊呜！]=],
	ScriptLine_139001 = [=[苍蓝避风港]=],
	ScriptLine_139002 = [=[呼……刚结束晨练回来。看到您也一早就投入工作，我便放心了。规律的生活是保持状态的基石，我们都要坚持才行。]=],
	ScriptLine_139003 = [=[最近妹妹们的训练量都不小，得多补充营养才行。我做了一些她们爱吃的可乐饼，您也来尝尝吧？{Action=1390104,Time=9}呵呵，我的手艺，您是知道的。]=],
	ScriptLine_139004 = [=[说来也怪，明明是同样的可乐饼，白天还吃得很开心的鸟海，晚上却总是说吃不下……摩耶也是，一到晚上就拉着爱宕不知道在忙些什么。{Action=1390101,Time=13}唉，她们几个，真让人操心。]=],
	ScriptLine_139005 = [=[今天的工作都处理完了呢。办公室安静下来，反而有些不习惯……不过，能和您静静地待一会儿，感觉……也不坏。]=],
	ScriptLine_139006 = [=[诶……？您觉得……很有魅力吗？我知道了……]=],
	ScriptLine_139007 = [=[呵呵……不知从何时起，比起在训练场挥洒汗水，像这样只是安静地看着您工作的侧脸，反而更让我感到安心……{Action=1390101,Time=11}我，是不是有点变奇怪了？]=],
	ScriptLine_139008 = [=[您累了吗？我的肩膀可以借给您依靠一下……还是说，您更喜欢靠在我的怀里呢？{Action=1390102,Time=8}呵呵，开玩笑的，别当真……（小声）{Action=1390112,Time=13}如果您希望的话，也……不是不行……]=],
	ScriptLine_139009 = [=[……您的手很温暖。像这样被您触碰着，总觉得……训练后的疲惫都消失了。]=],
	ScriptLine_139010 = [=[呵呵……连我走近了都没发觉，究竟在想什么呢？这么专注的表情……真可爱……再多看一会儿吧。]=],
	ScriptLine_139011 = [=[唔！{Action=1390105,Time=1}……咳咳……没什么，指挥官。我只是看您似乎在思考重要的事情，不敢打扰……那个，{Action=1390103,Time=9}您需要来杯茶提提神吗？]=],
	ScriptLine_139012 = [=[抱着必死的决心攻过来吧！]=],
	ScriptLine_139013 = [=[我在。]=],
	ScriptLine_139014 = [=[就这点本事！]=],
	ScriptLine_139015 = [=[就这点本事！]=],
	ScriptLine_139016 = [=[未能完成职责……万分抱歉……]=],
	ScriptLine_139017 = [=[未能完成职责……万分抱歉……]=],
	ScriptLine_139018 = [=[下一个。]=],
	ScriptLine_139019 = [=[下一个。]=],
	ScriptLine_139020 = [=[……麻烦的家伙来了。全员，阵型变更，准备迎击！]=],
	ScriptLine_139021 = [=[你已无处可逃……葬身浪涛之中吧！]=],
	ScriptLine_139022 = [=[你已无处可逃……葬身浪涛之中吧！]=],
	ScriptLine_139023 = [=[别想逃！]=],
	ScriptLine_139024 = [=[别想逃！]=],
	ScriptLine_139025 = [=[稳住阵脚，跟上我。]=],
	ScriptLine_139026 = [=[稳住阵脚，跟上我。]=],
	ScriptLine_139027 = [=[战斗结束，准备返航。各位都辛苦了。]=],
	ScriptLine_139028 = [=[战斗结束，准备返航。各位都辛苦了。]=],
	ScriptLine_139029 = [=[确保了战术胜利，但还称不上完美。平日的训练不可懈怠。]=],
	ScriptLine_139030 = [=[重巡洋舰高雄，此刻归建。让您久等了，指挥官。从今天起，我的航路将再次与您交汇。]=],
	ScriptLine_139031 = [=[我相信，您一定能带领大家走向未来。那么我的职责，就是为您开辟通向未来的道路。]=],
	ScriptLine_139032 = [=[……嗯，感觉很好。能更好地为您效力了。]=],
	ScriptLine_139033 = [=[身为您的剑，便当为您斩尽前路荆棘。这是我的职责，亦是不变的誓言……而您的臂弯，便是这柄剑，唯一的归处与安眠之鞘。如果这份感情被称为“幸福”，那我现在……一定是无比幸福。]=],
