	ScriptLine_140001 = [=[苍蓝避风港]=],
	ScriptLine_140002 = [=[还在为批不完的文件烦恼吗？哼哼~让专业的魔术师来帮您吧！文件文件~消失不见~Abraca~{Action=1400101,Time=10}诶，“快住手”？]=],
	ScriptLine_140003 = [=[和萨拉托加前辈一起作战时，我总能迸发出最棒的灵感！组队模拟战的连胜记录也在绝赞更新中！{Action=1400115,Time=7}这就是“天下无敌”吗，哈~哈~哈~]=],
	ScriptLine_140004 = [=[有时候，我会梦到自己是艘巡洋舰，和克利夫兰她们一起在海上遨游……{Action=1400101,Time=6}啊，难道说，这就是小说里常提到的“前世的记忆”吗？有种浪漫的感觉呢！]=],
	ScriptLine_140005 = [=[指挥官，要不要用卡牌来占卜一下我们的明天呢？夜深人静的时候，翻开的卡牌声……还有心跳声，都会听得特别清楚哦。]=],
	ScriptLine_140006 = [=[呀！？那、那里可没有藏着鸽子哦！]=],
	ScriptLine_140007 = [=[之前有个认死理的孩子一直追着我问“硬币到底藏在哪里”……真是的，魔术的乐趣就在于那份惊喜感呀！{Action=1400103,Time=9}还是指挥官最好，只会安静地笑着看我表演，从来不问东问西。]=],
	ScriptLine_140008 = [=[魔术师最大的禁忌，就是向观众揭晓谜底……但是，如果是您的话，好像……也没关系。{Action=1400111,Time=10}因为，<ruby=我最大的谜底>我的心意</ruby>  ，您不是早就已经看穿了吗？]=],
	ScriptLine_140009 = [=[……不、不行啦……再、再碰下去……我的脑袋就要像被变走点数的扑克牌一样……一片空白了……]=],
	ScriptLine_140010 = [=[搭档先生真是个大忙人啊……没有他在的舞台，总感觉有点冷清呢……哈……练习一下鸽子魔术好了……]=],
	ScriptLine_140011 = [=[欢迎回来，搭档先生！锵锵！您看，这只可爱的白鸽，也在拍着翅膀欢迎您哟！它也想您啦！]=],
	ScriptLine_140012 = [=[聚光灯已经亮起，欢迎来到我的魔术世界。]=],
	ScriptLine_140013 = [=[精彩的马上就来。]=],
	ScriptLine_140014 = [=[精彩的马上就来。]=],
	ScriptLine_140015 = [=[呀，穿帮啦！？]=],
	ScriptLine_140016 = [=[呀，穿帮啦！？]=],
	ScriptLine_140017 = [=[剩下的舞台，就交给你们了！]=],
	ScriptLine_140018 = [=[剩下的舞台，就交给你们了！]=],
	ScriptLine_140019 = [=[真真假假，虚虚实实~]=],
	ScriptLine_140020 = [=[真真假假，虚虚实实~]=],
	ScriptLine_140021 = [=[姗姗来迟的观众，却不知自己的命运早已被书写。现在，让好戏进入高潮。]=],
	ScriptLine_140022 = [=[奇迹即将诞生于舞台。让我们，沉浸其中。]=],
	ScriptLine_140023 = [=[奇迹即将诞生于舞台。让我们，沉浸其中。]=],
	ScriptLine_140024 = [=[Show time~！]=],
	ScriptLine_140025 = [=[Show time~！]=],
	ScriptLine_140026 = [=[Abracadabra！]=],
	ScriptLine_140027 = [=[Abracadabra！]=],
	ScriptLine_140028 = [=[完美的落幕！各位，掌声可以再热烈一点哦！]=],
	ScriptLine_140029 = [=[不完美的轨迹，往往正是通往更大奇迹的路标。别在意，我亲爱的搭档先生~]=],
	ScriptLine_140030 = [=[掌声越多，奇迹越多。欢呼越响，魔法越强——锵锵！轻型航母普林斯顿，回应召唤前来报到！指挥官，从此刻开始，我就是您专属的“奇迹向导”！]=],
	ScriptLine_140031 = [=[指挥官，这是我们的长期契约，就等您签字了！合约内容嘛……就是陪我玩到世界的尽头哦！]=],
	ScriptLine_140032 = [=[普林斯顿Magic power Make up！]=],
	ScriptLine_140033 = [=[呜……又是这招“让人脸红的魔术”！不对同一个观众表演第二次……这可是萨斯顿三原则的第一条！您、您这都第几次……偷偷亲上来了……我、我可没说我不愿意哦？哼，随便您啦，谁叫您是我认定的唯一搭档呢……]=],
	ScriptLine_140034 = [=[嗯？]=],
	ScriptLine_140035 = [=[嗯？]=],
	ScriptLine_140036 = [=[嗯！]=],
	ScriptLine_140037 = [=[嗯！]=],
	ScriptLine_140038 = [=[嘻嘻~]=],
	ScriptLine_140039 = [=[嘻嘻~]=],
	ScriptLine_140040 = [=[呜……]=],
	ScriptLine_140041 = [=[呜……]=],
	ScriptLine_140042 = [=[嗯……]=],
	ScriptLine_140043 = [=[嗯……]=],
	ScriptLine_140044 = [=[嘿，搭档先生~]=],
	ScriptLine_140045 = [=[嘿，搭档先生~]=],
	ScriptLine_140046 = [=[姆！]=],
	ScriptLine_140047 = [=[姆！]=],
	ScriptLine_140048 = [=[呜呜……]=],
	ScriptLine_140049 = [=[呜呜……]=],
	ScriptLine_140050 = [=[欸嘿嘿……]=],
	ScriptLine_140051 = [=[欸嘿嘿……]=],
	ScriptLine_140052 = [=[欸欸欸！？]=],
	ScriptLine_140053 = [=[欸欸欸！？]=],
	ScriptLine_140054 = [=[怎么这样！？]=],
	ScriptLine_140055 = [=[怎么这样！？]=],
	ScriptLine_140056 = [=[Abraca~dabra~]=],
	ScriptLine_140057 = [=[暂、暂停……暂停！]=],
	ScriptLine_140101 = [=[诶？搭档先生想摸摸头吗？嘿嘿，摸不着摸不着~平时都是我仰视您，今天难得换我在上面……好啦，等会儿摘完橙子下来，让您摸个够~]=],
	ScriptLine_140102 = [=[我的新发卡好看吗？嘻嘻，这可是我特意为了这次约会准备的，是不是很有“田园派”的淑女气质？怎么样，摘掉兔子耳朵的普林斯顿，也很不赖吧~]=],
	ScriptLine_140103 = [=[“穿得有够大胆？”嘿嘿，搭档先生色色的哦，在盯着哪儿看呢？——“当心蚊虫叮咬？”……您就没有其他话说吗！]=],
	ScriptLine_140104 = [=[呀哈！好痒！……搭档先生！这种时候从手牌发动“挠痒偷袭”是严重犯规的！万一我笑得从梯子上滚下去……那您就要负责接住我——而且是一辈子的那种负责！]=],
	ScriptLine_140105 = [=[哼哼，这绑带可是我精心挑选的“决胜王牌”！怎么样，是不是很有女性魅力呀？……唔，但也别盯着看太久……我会不好意思的……]=],
	ScriptLine_140106 = [=[唔唔，在梯子上坐久了，腿确实有点酸呢……搭档先生，等会儿休息的时候，能不能申请一下您的按摩服务？……诶？现在就要按？在这里？！]=],
	ScriptLine_140107 = [=[锵锵~！普林斯顿的“隔空取物”表演您还满意吗？树上的甜甜果实，全都被我转移到篮子里啦！看这满满的收获！……嗯？您说我还漏了一颗“最甜的”？不可能呀，我的手法应该是完美的……]=],
	ScriptLine_140108 = [=[嘻嘻，这条绸带可是我今天特意系上的，据说能锁住两个人之间的缘分……{Action=1400302,Time=7}哎哎，别拽！要是散开了，缘分跑掉了怎么办！]=],
	ScriptLine_140109 = [=[3、2、1……锵锵！凭空消失的普林斯顿小姐，正在梯子上向您发来问候！嘻嘻，搭档先生，别再检查那棵树啦，看这里看这里！耶~！]=],
	ScriptLine_140110 = [=[哼哼，搭档先生，这个Pose是不是很眼熟啊？对啦，就是之前我们一起看的电影里，女主角的经典姿势！我可是练习了好久的！快快快，趁现在帮我拍张照！耶~！]=],
	ScriptLine_143001 = [=[苍蓝避风港]=],
	ScriptLine_143002 = [=[能每天和姐姐们在一起，还能像这样……被指挥官哥哥摸头。柯蒂斯觉得，自己一定是世界上最幸福的孩子了，嘿嘿……]=],
	ScriptLine_143003 = [=[刚刚……柯蒂斯拒绝了圣地亚哥姐姐的汽水邀请，因为工作期间要保持专注……{Action=1430102,Time=9}指挥官哥哥，柯蒂斯这样做，是对的吧？]=],
	ScriptLine_143004 = [=[指挥官哥哥快看！这是柯蒂斯的新发明“小雪鹱”——能自动给哥哥送上热茶的无人机！嘿嘿，这样哥哥就不会忘记喝水啦！]=],
	ScriptLine_143005 = [=[指挥官哥哥，柯蒂斯，好像……有点困了呢。要是，要是能靠在哥哥身边……柯蒂斯，一定，很快就能睡着了……]=],
	ScriptLine_143006 = [=[呀！……指、指挥官哥哥……]=],
	ScriptLine_143007 = [=[指挥官哥哥，能和您在一起，柯蒂斯就觉得……每天都有用不完的力气，精神也好好喔！]=],
	ScriptLine_143008 = [=[呀……指挥官哥哥，那个……是柯蒂斯新发明的情感腕带，被你碰到的话，心跳数据会……会直接显示在屏幕上的啦……！]=],
	ScriptLine_143009 = [=[……嗯，柯蒂斯的心，只有指挥官哥哥可以触碰哦。]=],
	ScriptLine_143010 = [=[啊……指挥官哥哥，不在呢……冰淇淋要等哥哥回来，一起吃才最开心……柯蒂斯，要、要加油忍住……]=],
	ScriptLine_143011 = [=[啊……指挥官哥哥，您、您回来了！柯蒂斯带了冰淇淋来哦！我们一起吃吧！{Action=1430112,Time=10}嘿嘿，好开心呢~]=],
	ScriptLine_143012 = [=[柯蒂斯会和大家一起努力！请平安回来！加油，加油！]=],
	ScriptLine_143013 = [=[嗯！]=],
	ScriptLine_143014 = [=[嗯！]=],
	ScriptLine_143015 = [=[呃……柯蒂斯，没、没事！]=],
	ScriptLine_143016 = [=[呜……大家请不要担心……柯蒂斯，只是去休息一下……]=],
	ScriptLine_143017 = [=[呼……总算是……打倒了呢。]=],
	ScriptLine_143018 = [=[是新的敌人！……大家的状态还好吗？柯蒂斯，会全力支援大家的！]=],
	ScriptLine_143019 = [=[演算开始……最优解锁定！]=],
	ScriptLine_143020 = [=[演算开始……最优解锁定！]=],
	ScriptLine_143021 = [=[这、这样应该……能帮上忙吧？]=],
	ScriptLine_143022 = [=[这、这样应该……能帮上忙吧？]=],
	ScriptLine_143023 = [=[大家，元气满满喔！]=],
	ScriptLine_143024 = [=[大家，元气满满喔！]=],
	ScriptLine_143025 = [=[太好了！大家都、都平平安安的呢！大家，都是最棒的！]=],
	ScriptLine_143026 = [=[呼……能赢下来真是太好了！大家，柯蒂斯会在这里哦……请，请好好休息吧。]=],
	ScriptLine_143027 = [=[啊……指挥官哥哥！柯蒂斯，能在这里见到您……心里，暖烘烘的……好开心。指挥官哥哥……可以……可以摸摸柯蒂斯的头吗？]=],
	ScriptLine_143028 = [=[柯蒂斯，想一直……一直陪在指挥官哥哥身边……成为能帮助到哥哥的力量！]=],
	ScriptLine_143029 = [=[柯蒂斯，构筑出新的“可能性”了！]=],
	ScriptLine_143030 = [=[指挥官哥哥……柯蒂斯的心里，一直都暖烘烘的呢。柯蒂斯，想要把这份，暖烘烘的心情……永远……永远地，都交给指挥官哥哥……柯蒂斯，永远都会陪着您的。]=],
