	Signaldesc50001 = [=[以自由为名，点亮永不熄灭的希望之光。她们照亮前方未知的航路，守护着心中的理想。]=],
	Signaldesc50002 = [=[钢铁铸就历史，优雅承载荣耀。她们是王冠的守护者，为古老的秩序和无上的尊严而战。]=],
	Signaldesc50003 = [=[受女神眷顾的战士们，拥有不屈的自由之魂。她们如同盛开的鸢尾花，美丽而坚韧。]=],
	Signaldesc50004 = [=[力量与勇气构筑出铁血的壁垒。她们演奏着钢铁碰撞的交响曲，在战场上奏响守护的乐章。]=],
	Signaldesc50005 = [=[灵魂深处铭刻着永恒之城的回忆。她们吟唱着辉煌的咏叹调，用热情点缀战场，谱写浪漫诗篇。]=],
	Signaldesc50006 = [=[神话时代的残响，回荡于蔚蓝战场之上。她们以虔诚信仰承载八百万神明的意志，净化一切邪恶与污秽。]=],
	Signaldesc50007 = [=[淬炼于极北凛冬之中，纯洁而不灭的意志。她们为了集体的荣耀和理想，在寒风中坚韧绽放。]=],
	Signaldesc50008 = [=[祥云环绕，气化流行，生生不息。古老的祝福赐予她们智慧和包容，化解纷争，守护世界的和谐与安宁。]=],
	Signaldesc70001 = [=[与耐久值低于一定值的对手战斗时，暴击率小幅度提升]=],
	Signaldesc70002 = [=[胡德在场时，己方全体炮击伤害增加3%；当胡德被击沉时，己方全体炮击降低2%]=],
	Signaldesc70003 = [=[我方航母系角色防空+2%，夜战情况下该效果翻倍]=],
	Signaldesc70004 = [=[对当前生命值30%以下的敌方单位，造成额外3%的伤害]=],
	Signaldesc70005 = [=[当我方俾斯麦在场时，欧根亲王与俾斯麦同时获得装甲+2%，机动+2%]=],
	Signaldesc70006 = [=[造成一次暴击后，2回合内炮击伤害增加2%，不可叠加]=],
	Signaldesc70007 = [=[同时可受到【雷欧顿】相关效果影响]=],
	Signaldesc70008 = [=[场上每一个弗莱彻级的我方单位会给弗莱彻提供1.5%的雷击与装甲]=],
	Signaldesc70009 = [=[使用单体攻击与耐久值低于自己的对手攻击时，暴击率小幅度提升]=],
	Signaldesc70010 = [=[耐久+2%，2格范围内存在2名以上敌方单位时，装甲+2%]=],
