	skinTag_20 = [=[暂无]=],
	skinDesc_1000001 = [=[层层叠叠的洛可可裙摆，华贵的三色头饰，优雅得如同漫步在宫廷花园。]=],
	skinDesc_1000101 = [=[层层叠叠的洛可可裙摆，华贵的三色头饰，优雅得如同漫步在宫廷花园。]=],
	skinDesc_1000102 = [=[笑容藏起眼角的泪水。纵使指尖颤抖，她仍要优雅地展开折扇，奏响风暴的序曲。]=],
	skinDesc_1000201 = [=[不合身的飞行员夹克，是她最棒的航海服。腰间皱巴巴的海图，画满了她尚未征服的梦想！]=],
	skinDesc_1000202 = [=[谁也不能阻止这个大海盗！丢掉海图吧，整个世界都是她随心所欲的游乐场！]=],
	skinDesc_1000301 = [=[贴身的制服，难以遮住她扑面而来的丰满，以及荣耀和骄傲。]=],
	skinDesc_1000302 = [=[当她拔刀出鞘，战场上就只剩下碾碎一切的纯粹力量。刀尖所指之处，便是这场钢铁交响曲的终章。]=],
	skinDesc_1000303 = [=[金色长发自然垂落，纯白衬衫与修身黑裙勾勒出端庄的线条。她端坐于整洁的办公桌前，宛如游刃有余的白领，却对即将到来的兵荒马乱毫无自觉。]=],
	skinDesc_1000401 = [=[挂满工具的工作裙，是这位港区大管家的专属制服。翠色的眼瞳透过镜片，时刻都在计算着如何让每一分预算都花在刀刃上。]=],
	skinDesc_1000402 = [=[肌肤上沾满的油污，才是她为港区一砖一瓦积攒出的、最值得炫耀的、闪闪发光的勋章。]=],
	skinDesc_1000501 = [=[厚重的铁甲包裹着坚实的四肢。红色基调的军服，象征着龙的威严。]=],
	skinDesc_1000502 = [=[当红龙咆哮时，那柄巨剑便划开前路，为这片大海带来最荣耀的胜利。]=],
	skinDesc_1000601 = [=[贴合玲珑身姿的青蓝色改良旗袍，面料柔软，袖口缀有精致的荷叶边。侧腰的系带方便活动，是她最喜欢的设计。]=],
	skinDesc_1000602 = [=[雷霆万钧之势！每一次踏浪突进，飞扬的黑袖与发间的茜色流霞，皆是撕裂敌阵的锋芒。]=],
	skinDesc_1000701 = [=[洁白的衣装点缀着金色的绶带。就连慵懒的橘猫，也成了她完美日常中，一幅从容的写照。]=],
	skinDesc_1000702 = [=[主炮的轰鸣，不过是下午茶最完美的伴奏。对她而言，无论何时何地，保持这份优雅与从容，本身便是王冠下的至高荣耀。]=],
	skinDesc_1000703 = [=[每一份礼物中，都包含着一段令人难忘的故事。这是你和她一路走来的见证，这是你们相濡以沫的……睡前故事。]=],
	skinDesc_1000801 = [=[纯白的宽袖弓道服上，点缀着象征热诚的绯红。正如她本人一般，将如火的热情，悉心收敛于克己的宁静之下。]=],
	skinDesc_1000802 = [=[当弓弦满张，心意便化作金色箭矢，为战场上的一切污秽，带来终焉的净化。]=],
	skinDesc_1000803 = [=[褪去戎装，回到这片静谧的二人空间。墨色的长发与素白的睡裙，勾勒出她那柔软的曲线。平日里那双澄澈克己的眼眸，只因你的归来，而漾开浅浅的涟漪。这里没有箭无虚发的战士，只有卸下了所有防备、一心一意等待着你的、赤城。]=],
	skinDesc_1000901 = [=[宽大的兜帽遮住不必要的视线，半拉开的外套保护着纤细的肢体。这便是她那小小的世界。]=],
	skinDesc_1000902 = [=[当鱼雷直击对手的要害时，她已经迅速脱离至安全距离。沉默是金。]=],
	skinDesc_1000903 = [=[透明的水花四溅，少女蹲在湿滑的地板上，期盼你能来一起帮忙照顾这三只闹腾的小家伙。是时候加入她，帮她顺利完成这次清洗“任务”了！]=],
	skinDesc_1001001 = [=[优雅的黑色是她的社交礼服。复古的提灯会照亮同伴们回家的路。]=],
	skinDesc_1001002 = [=[她的歌声是最安心的关怀，抚平每一道伤痕，唤醒冷却的炮膛，让钢铁意志再次咆哮。]=],
	skinDesc_1001003 = [=[黑色的丝质布料包裹住起伏的曲线，宛如夜雾般朦胧而温柔。那位平时优雅从容毫无破绽的女士，只在你面前松懈下来，将一抹隐含着热情的玫红色轻点于唇间。]=],
	skinDesc_1001101 = [=[旗袍下摆与流苏摇曳出悄然流转的温婉，一颦一笑间，吐露而出的却是说一不二的利落。]=],
	skinDesc_1001102 = [=[攻势不过是意志的延伸，无论战场或是日常，一切节奏永远由她掌控——那份从容气度令人信赖。]=],
	skinDesc_1001201 = [=[笔挺的制服上，点缀着象征骑士荣誉的银色肩甲。真正的坚韧，悉心收藏于温柔的言行之下。]=],
	skinDesc_1001202 = [=[钢铁的羽翼，是守护同伴的最坚固壁垒。她的坚韧，此刻化为必胜的誓言。]=],
	skinDesc_1001203 = [=[象征终点的黑白菱格，被裁作贴身的衣饰，点缀在热烈的红与沉稳的黑之间。少女内敛的温柔与信赖，伴随着疾驰的绯红身影、与带来胜利的至高之风，一同编织成献给胜利者的无上荣光。]=],
	skinDesc_1001301 = [=[深蓝的连体紧身裙，勾勒出活力洋溢的身形，而那灿烂的笑容，正是她独有的意气风发的最佳标志。]=],
	skinDesc_1001302 = [=[战场的轰响，亦是专属于她的应援——无人能够阻止最强偶像的完美亮相！]=],
	skinDesc_1001303 = [=[轻飘飘的裙摆随着少女忙碌的打扫来回舞动，像一串慌乱又笨拙的音符。虽然女仆想将房间的灰尘一扫而空，但她自己，正是这一片狼藉的源头。]=],
	skinDesc_1001401 = [=[便于活动的游侠裙装，皮质束腰和长筒靴充满了动感和野性，那是她不受束缚的自由宣言。]=],
	skinDesc_1001402 = [=[当她拉开满弓，所有的漫不经心瞬间褪去。琥珀色的眼瞳里，只剩下锁定猎物时的专注。]=],
	skinDesc_1001501 = [=[纯白裙摆轻扬，在那娇小轻盈的身躯里，怀抱着一份无人企及的远大理想。]=],
	skinDesc_1001502 = [=[踏浪前行，她将一切未知的险阻挑战当作突破自我的契机，全力书写由勇气铸就的成长日志。]=],
	skinDesc_1001601 = [=[她很喜欢这件时髦的半透明雨衣，它带来的好心情，能稍微中和掉妹妹们过于活泼的喊叫声——是的，只是稍微。]=],
	skinDesc_1001602 = [=[“——到此为止了！”战场上没有无奈，只有作为战士的责任，因为身后还有很多需要她去守护的重要事物。]=],
	skinDesc_1001701 = [=[看这充满机能美的战斗服，看这巨大的外骨骼机械臂，简直帅到不行，不是吗！]=],
	skinDesc_1001702 = [=[引擎轰鸣，战意高涨。这是她最渴望的战场。用一场场酣畅淋漓的胜利，慢慢靠近憧憬的前辈们的背影。]=],
	skinDesc_1001801 = [=[一阶段]=],
	skinDesc_1001802 = [=[二阶段]=],
	skinDesc_1001901 = [=[青春洋溢的双排扣制服，见证了她的成长，她的憧憬，她的好奇心。]=],
	skinDesc_1001902 = [=[呼啸的火力绽放胜利的礼花。看到了吗，这就是“大人的魅力”！]=],
	skinDesc_1002001 = [=[一阶段]=],
	skinDesc_1002002 = [=[二阶段]=],
	skinDesc_1002003 = [=[天蒙蒙亮，厨房里便响起了厨具碰撞声。早起的不仅有鸟儿，还有等待开饭的猫咪。而你和她，自然倒了霉。]=],
	skinDesc_1002101 = [=[一阶段]=],
	skinDesc_1002102 = [=[二阶段]=],
	skinDesc_1002201 = [=[一阶段]=],
	skinDesc_1002202 = [=[二阶段]=],
	skinDesc_1002301 = [=[锁定目标，投射出致命的空中箭矢，以精确的外科手术式打击，清除阻挡在前的威胁。]=],
	skinDesc_1002401 = [=[自水线之下，张开无处可逃的火网，出其不意间撕裂敌人的防线。]=],
	skinDesc_1002501 = [=[驰骋于海面的移动炮台，用永不间断的弹幕，压制敌方的前锋阵线。]=],
	skinDesc_1002601 = [=[一阶段]=],
	skinDesc_1002602 = [=[二阶段]=],
	skinDesc_1002701 = [=[一阶段]=],
	skinDesc_1002702 = [=[二阶段]=],
	skinDesc_1002703 = [=[U-47坐在度假屋明亮的厨房台面，水洗般湛蓝的发丝，与一袭纯白睡衣，活泼的身姿在金色日光中漾开。她的双手高举，托起那份独属于两人的美味佳肴，眉梢眼角皆是期待。啦啦啦♪尽情喧闹吧，这是你们的快乐假期，快乐惊喜。]=],
	skinDesc_1002801 = [=[一阶段]=],
	skinDesc_1002802 = [=[二阶段]=],
	skinDesc_1002901 = [=[一阶段]=],
	skinDesc_1002902 = [=[二阶段]=],
	skinDesc_1002903 = [=[金色的长发自然垂落，修长的双腿优雅交叠，雅致的黑色衬托出居家慵懒的线条。她置身于此，一如房中汲取光芒的绿植，将饱满的生命力，化作温柔的光华，与最重视的你彼此映照。]=],
	skinDesc_1003001 = [=[一阶段]=],
	skinDesc_1003002 = [=[二阶段]=],
	skinDesc_1003101 = [=[一阶段]=],
	skinDesc_1003102 = [=[二阶段]=],
	skinDesc_1003201 = [=[一阶段]=],
	skinDesc_1003202 = [=[二阶段]=],
	skinDesc_1003301 = [=[挂满工具的工作裙，是这位港区大管家的专属制服。翠色的眼瞳透过镜片，时刻都在计算着如何让每一分预算都花在刀刃上。]=],
	skinDesc_1003302 = [=[肌肤上沾满的油污，才是她为港区一砖一瓦积攒出的、最值得炫耀的、闪闪发光的勋章。]=],
	skinDesc_1003401 = [=[宽大的兜帽遮住不必要的视线，半拉开的外套保护着纤细的肢体。这便是她那小小的世界。]=],
	skinDesc_1003501 = [=[挂满工具的工作裙，是这位港区大管家的专属制服。翠色的眼瞳透过镜片，时刻都在计算着如何让每一分预算都花在刀刃上。]=],
	skinDesc_1003601 = [=[锁定目标，投射出致命的空中箭矢，以精确的外科手术式打击，清除阻挡在前的威胁。]=],
	skinDesc_1003701 = [=[一阶段]=],
	skinDesc_1003702 = [=[二阶段]=],
	skinDesc_1003801 = [=[一阶段]=],
	skinDesc_1003802 = [=[二阶段]=],
	skinDesc_1003901 = [=[洁白的衣装点缀着金色的绶带。就连慵懒的橘猫，也成了她完美日常中，一幅从容的写照。]=],
	skinDesc_1003902 = [=[主炮的轰鸣，不过是下午茶最完美的伴奏。对她而言，无论何时何地，保持这份优雅与从容，本身便是王冠下的至高荣耀。]=],
	skinDesc_1003903 = [=[休息日，身材高挑、站姿笔直的美人一如既往地进行采购日常，并准备向你讨教做什么美食能抓住你的胃。但认真的她没有意料到，下了不少功夫和心思的打扮，已经先一步抓住了你的心。]=],
	skinDesc_1004001 = [=[便于活动的游侠裙装，皮质束腰和长筒靴充满了动感和野性，那是她不受束缚的自由宣言。]=],
	skinDesc_1004002 = [=[当她拉开满弓，所有的漫不经心瞬间褪去。琥珀色的眼瞳里，只剩下锁定猎物时的专注。]=],
	skinDesc_1004003 = [=[她高坐于木梯之上，俏皮地眨着那双碧蓝的眼眸。纯白大胆的长裙点缀着繁花，随风轻扬的红绸带像是放飞的快乐。斑驳光影透过的每一颗果实，仿佛都是这位魔术师为了今日的约会，在假日舞台上精心编织的甜蜜奇迹。]=],
	skinDesc_1004201 = [=[洁白的衣装点缀着金色的绶带。就连慵懒的橘猫，也成了她完美日常中，一幅从容的写照。]=],
