	choice3TextFB_100080102 = [=[赤城点头应声，淡然一笑。
“请您期待我的新作问世吧。我有信心，这款点心不会让您失望。”]=],
	choice3TextFB_100080202 = [=[]=],
	choice3TextFB_100080103 = [=[她轻轻侧首，微笑着看着我。
