	plot_title_100510 = [=[云消雾散]=],
	plot_synopsis_100001 = [=[你在冰冷的海水中缓缓苏醒，映入眼帘的，是一位正一遍遍呼唤着你的银发少女。]=],
	plot_synopsis_100002 = [=[零散的记忆开始重新拼凑。刻进骨子里的指挥本能，在此刻彻底被唤醒。]=],
	plot_synopsis_100003 = [=[战斗顺利结束。接下来登场的，是一位拖着大堆破铜烂铁，誓要为你“复仇”的好伙伴。]=],
	plot_synopsis_100004 = [=[终于抵达了目的地——避风港。然而，有许多意想不到的困难在等待着你。]=],
	plot_synopsis_100005 = [=[在大家的不懈努力下，基地勉强恢复了初步运作。]=],
	plot_synopsis_100006 = [=[基地目前急需补充新的人手，据重庆所说这附近刚好有一位？]=],
	plot_synopsis_100007 = [=[你找到了在附近海域游荡的驱逐舰基德，然而想要让这位“船长”归队并不容易。]=],
	plot_synopsis_100008 = [=[为了让这位桀骜不驯的“海盗”归队，你毅然接下了她设下的挑战。]=],
	plot_synopsis_100009 = [=[寻宝比赛正进行到白热化阶段，一阵突如其来的炮火打乱了你们的阵脚。]=],
	plot_synopsis_100010 = [=[真正的敌人正悄然逼近……]=],
	plot_synopsis_100011 = [=[基德意外陷入了深海的重重包围之中。]=],
	plot_synopsis_100012 = [=[眼前的危机虽已化解，却没想到，基德和吕佐夫之间又出了问题……]=],
	plot_synopsis_100013 = [=[吕佐夫向你解释了基德的情况，而在零碎的线索逐一拼凑后，你发现眼下还有更加紧急的事。]=],
	plot_synopsis_100014 = [=[狂风骤雨中，微弱的信号弹划破了夜空。]=],
	plot_synopsis_100015 = [=[基德终于回到了这座基地，对于及时的救援，她心中似乎有许多疑问。]=],
	plot_synopsis_100201 = [=[来自深海的骚扰接连不断……]=],
	plot_synopsis_100202 = [=[连续高强度的工作让你疲惫不堪，就在你靠特浓咖啡提神时，一位神秘的访客出现了。]=],
	plot_synopsis_100203 = [=[多亏艾塔的勤勉能干，港区的每个人都更好地适应了新生活……敦刻尔克除外。]=],
	plot_synopsis_100204 = [=[对于之前任务中的表现，敦刻尔克很是自责，于是她主动提出要帮你处理工作。可是你察觉到，似乎有另一件心事也在困扰着这位淑女。]=],
	plot_synopsis_100205 = [=[进犯的深海部队占据了有利地形。请留意海域中不同地形带来的移动限制，谨慎规划作战路线。]=],
	plot_synopsis_100206 = [=[最近港区频繁发生奇妙事件，对此，你决定召开一场专项分析会议。]=],
	plot_synopsis_100207 = [=[行踪不定的“幽灵”终于在你们面前现出真容，原来，她的真实身份是——]=],
	plot_synopsis_100208 = [=[敦刻尔克再次抵达上次遇袭的海域。她与深海舰“乌妮妮”展开了第二次接触。]=],
	plot_synopsis_100209 = [=[全新的强力舰装让敦刻尔克占据了上风，但接下来的状况会如她想象的那样顺利吗？]=],
	plot_synopsis_100210 = [=[你们成功击退了乌妮妮。回到港区后，众人迫不及待想要举办一场庆功宴。]=],
	plot_synopsis_100301 = [=[Z16的到来让港区战力得到充实。但与此同时，深海似乎也有什么动作……]=],
	plot_synopsis_100302 = [=[首战告捷的Z16和弗莱彻小队，在返航中却遭遇了意外……]=],
	plot_synopsis_100303 = [=[海面上……传来了熟悉的声音……]=],
	plot_synopsis_100304 = [=[在能见度极低的诡异海雾中，走散的Z16正面临着生存考验。]=],
	plot_synopsis_100305 = [=[Z16与弗莱彻成功在雾中汇合，面对深海的诡计，她们必须设法扭转劣势。]=],
	plot_synopsis_100306 = [=[基德带回了关键情报。而就在这时，Z16那一边的情况发生了意想不到的转折。]=],
	plot_synopsis_100307 = [=[海雾渐渐消散，Z16与弗莱彻试图展开突围，但深海早已暗中布下陷阱。]=],
	plot_synopsis_100308 = [=[就在不久前，为了彻底跳出深海的圈套，Z16向弗莱彻提出了自己的想法。]=],
	plot_synopsis_100309 = [=[成功擒获了乌妮妮。就在你准备处置这名俘虏时，一个威严的声音从海面尽头传来。]=],
	plot_synopsis_100310 = [=[虽然自称“维纳斯”的上位深海舰展现出了压倒性的火力，事情变得棘手起来，但你难道真就没有应对她的办法了吗？]=],
	plot_synopsis_100311 = [=[这次的作战大获全胜，但Z16却异常沮丧。]=],
	plot_synopsis_100401 = [=[针对深海的“海雾”战术，你制定了一场拆分编队的特化应对演习。]=],
	plot_synopsis_100402 = [=[演习如火如荼展开中，一切看起来都那么顺利……]=],
	plot_synopsis_100403 = [=[乌妮妮落荒而逃。这次突如其来的实战演练，取得了丰硕的战果。]=],
	plot_synopsis_100404 = [=[又做了奇怪的梦，但此刻你更在意之前闯入演习场的那群深海舰。]=],
	plot_synopsis_100405 = [=[于遭遇战中再次击败乌妮妮，但她的撤退路线略显不自然……]=],
	plot_synopsis_100406 = [=[深海的巢穴之中，慈爱的“母亲”——维纳斯决定亲自出战。]=],
	plot_synopsis_100407 = [=[大战在即，为了提振士气，港区举办了盛大的聚餐。]=],
	plot_synopsis_100408 = [=[喧闹的餐会上，唯独不见威尔士亲王的身影……]=],
	plot_synopsis_100409 = [=[攻坚作战正式打响，三支舰队按计划分进合击，围剿深海。]=],
	plot_synopsis_100410 = [=[顺利击退乌妮妮，但海雾的流向让你察觉到敌人真正的目标……]=],
	plot_synopsis_100501 = [=[在向主力战场汇合的途中，你的舰队遭遇了一些麻烦……]=],
	plot_synopsis_100502 = [=[威尔士亲王正与维纳斯进行着周旋。她在等待一个破局的“时机”。]=],
	plot_synopsis_100503 = [=[为了履行对你、对同伴们的承诺，胡德率队展开了一次争分夺秒的急行军。]=],
	plot_synopsis_100504 = [=[胡德队的加入，让维纳斯陷入了腹背受敌的窘境。]=],
	plot_synopsis_100505 = [=[在与乌妮妮的战斗中，作为旗舰的敦刻尔克做出了最后的决断。]=],
	plot_synopsis_100506 = [=[得知乌妮妮陷入危机，维纳斯的行动出现了意料之外的变化。]=],
	plot_synopsis_100507 = [=[维纳斯尝试突围。你下令继续追击。]=],
	plot_synopsis_100508 = [=[乌妮妮的意识深处，一段关于“家人”的记忆被唤醒。]=],
	plot_synopsis_100509 = [=[就在所有人都以为胜负已分之时，意外陡生。]=],
	plot_synopsis_100510 = [=[硝烟散尽，两位上位深海舰的最终结局将在这里决定。]=],
